INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-arthurs-world-europe', 'SNES', 'King Arthur''s World (Europe)', '1992', 'Strategy', 'Argonaut', '1', 'Tactical strategy', 'Unique side-scrolling puzzle-strategy game.', 'Lead your army to conquer enemy castles and expand your kingdom.', 'Command the army in King Arthur''s World on the SNES.', 'Known as a spiritual successor to Lemmings. Use a variety of unit types, from archers to engineers, to overcome 16-bit environmental hazards and sieges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-arthurs-world-usa', 'SNES', 'King Arthur''s World (USA)', '1992', 'Strategy', 'Argonaut', '1', 'Tactical strategy', 'Side-scrolling puzzle-strategy game based on unit management.', 'Conquer enemy kingdoms by strategically deploying your army.', 'Command your troops in King Arthur''s World for the SNES.', 'A unique 16-bit strategy title where you lead knights, archers, and engineers. Navigate through trap-filled levels and use siege engines to destroy enemy fortifications.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-arthurs-world-usa-beta', 'SNES', 'King Arthur''s World (USA) (Beta)', '1992', 'Strategy', 'Argonaut', '1', 'Tactical strategy beta', 'Side-scrolling puzzle-strategy game based on unit management.', 'Test the early castle-siege levels and unit balancing.', 'Check out the King Arthur''s World (Beta) for the SNES.', 'An early 16-bit development build. Explore initial level designs and mechanical tweaks for the army-command system before the final North American release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-of-dragons-the-europe', 'SNES', 'King of Dragons, The (Europe)', '1994', 'Action', 'Capcom', '2', 'Beat ''em up', 'Fantasy side-scrolling beat ''em up with RPG leveling elements.', 'Defeat the dragon Gildiss and restore peace to the kingdom.', 'Slay the beast in The King of Dragons for the SNES.', 'A 16-bit Capcom classic. Choose from five heroes, including a Fighter and Mage, and level up your gear as you fight through hordes of mythical monsters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-of-dragons-the-japan', 'SNES', 'King of Dragons, The (Japan)', '1994', 'Action', 'Capcom', '2', 'Beat ''em up', 'Fantasy side-scrolling beat ''em up with RPG leveling elements.', 'Defeat the dragon Gildiss in the original Japanese version.', 'Play The King of Dragons on the Super Famicom.', 'The foundational 16-bit release of this arcade hit. Features incredible boss designs, 2-player co-op, and a perfect blend of action and light RPG mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-of-dragons-the-usa', 'SNES', 'King of Dragons, The (USA)', '1994', 'Action', 'Capcom', '2', 'Beat ''em up', 'Fantasy side-scrolling beat ''em up with RPG leveling elements.', 'Defeat the dragon Gildiss and restore peace to the kingdom.', 'Slay the beast in The King of Dragons for the SNES.', 'Master the 16-bit combat and character-specific abilities. Fight through diverse fantasy environments in one of the most polished brawlers on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-of-rally-the-japan', 'SNES', 'King of Rally, The (Japan)', '1994', 'Racing', 'Atelier Double', '1', 'Rally racing', 'Mode 7-based rally racing simulation with a focus on realism.', 'Win the international rally championship across diverse terrains.', 'Feel the mud in The King of Rally for the Super Famicom.', 'A technical 16-bit racer that uses the console''s rotation effects. Navigate sharp turns and changing weather in various global locations to claim the title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-of-the-monsters-europe', 'SNES', 'King of the Monsters (Europe)', '1992', 'Fighting', 'SNK', '2', 'Monster fighting', 'Giant monster wrestling and city-destruction brawler.', 'Defeat rival kaijus and become the King of the Monsters.', 'Destroy cities in King of the Monsters for the SNES.', 'A port of the Neo Geo classic. Control massive 16-bit monsters, use the environment as a weapon, and wrestle for dominance in fully destructible cityscapes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-of-the-monsters-japan', 'SNES', 'King of the Monsters (Japan)', '1992', 'Fighting', 'SNK', '2', 'Monster fighting', 'Giant monster wrestling and city-destruction brawler.', 'Defeat rival kaijus in the original Japanese version.', 'Experience King of the Monsters on the Super Famicom.', 'The original 16-bit release of the monster-wrestling hit. Choose your favorite kaiju and crush buildings while fighting for the ultimate title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-of-the-monsters-usa', 'SNES', 'King of the Monsters (USA)', '1992', 'Fighting', 'SNK', '2', 'Monster fighting', 'Giant monster wrestling and city-destruction brawler.', 'Defeat rival kaijus and become the King of the Monsters.', 'Destroy cities in King of the Monsters for the SNES.', 'Engage in epic 16-bit battles. Use powerful throws and special attacks to pin your opponent in the middle of a crumbling urban battlefield.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-of-the-monsters-2---the-next-thing-japan', 'SNES', 'King of the Monsters 2 - The Next Thing (Japan)', '1993', 'Fighting', 'SNK', '2', 'Monster fighting', 'Beat ''em up sequel featuring massive monsters and alien invaders.', 'Stop the alien threat by fighting through global locations.', 'Battle for Earth in King of the Monsters 2 on SNES.', 'A shift from the first game''s wrestling focus to a 16-bit side-scrolling brawler. Control three giant heroes and defeat bizarre biological mutations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-of-the-monsters-2-usa', 'SNES', 'King of the Monsters 2 (USA)', '1993', 'Fighting', 'SNK', '2', 'Monster fighting', 'Beat ''em up sequel featuring massive monsters and alien invaders.', 'Save the world from the alien bio-menace.', 'Experience King of the Monsters 2: The Next Thing.', 'Features huge 16-bit sprites and intense boss encounters. A cinematic brawler that scales up the action and destruction on a global level.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kingyo-chuuihou!-tobidase!-game-gakuen-japan', 'SNES', 'Kingyo Chuuihou! Tobidase! Game Gakuen (Japan)', '1992', 'Action', 'Toho', '1', 'Anime action', 'Mini-game collection based on the popular "Goldfish Warning!" anime.', 'Win a series of wacky school-themed mini-games and events.', 'Join the fun in Kingyo Chuuihou! on the Super Famicom.', 'A colorful 16-bit party game. Compete against friends or AI in humorous challenges inspired by the surreal and cute world of the hit manga.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kinnikuman---dirty-challenger-japan', 'SNES', 'Kinnikuman - Dirty Challenger (Japan)', '1994', 'Fighting', 'Bandai', '2', 'Wrestling fighting', 'Wrestling game featuring characters from the Kinnikuman series.', 'Win the wrestling tournament and claim the championship belt.', 'Enter the ring in Kinnikuman: Dirty Challenger on SNES.', 'Features the iconic 16-bit "M.U.S.C.L.E." heroes. Master special grapple moves and finishers in this fast-paced and humorous Japanese wrestling title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-bowl-japan', 'SNES', 'Kirby Bowl (Japan)', '1995', 'Sports', 'HAL Laboratory', '4', 'Minigolf', 'Mini-golf simulation with power-ups and Kirby mechanics.', 'Reach the goal hole by launching Kirby across hazard-filled tracks.', 'Play Kirby Bowl on the Super Famicom.', 'The original Japanese version of Kirby''s Dream Course. A creative 16-bit sports-puzzle hybrid where Kirby''s copy abilities change how he moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-in-super-mario-land-25', 'SNES', 'Kirby in Super Mario Land 2.5', '2016', 'Hack', 'Fanmade', '1', 'Crossover platformer', 'Fan-made crossover mod blending Kirby with Mario mechanics.', 'Navigate reimagined Mario levels using Kirby''s unique skills.', 'Play the Kirby in Super Mario Land 2.5 mod on SNES.', 'A creative 16-bit romhack that ports Kirby into a Mario-inspired world. Features custom sprites and modified level physics for a unique platforming experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-in-the-megaman-29th-anniversary-adventure', 'SNES', 'Kirby in The Megaman 29th Anniversary Adventure', '2017', 'Hack', 'Fanmade', '1', 'Crossover platformer', 'Fan-made crossover mod blending Kirby with Mega Man themes.', 'Defeat Robot Masters using Kirby''s copy abilities and movements.', 'Experience Kirby in the Megaman Adventure on SNES.', 'A clever 16-bit hack that mixes the mechanics of two legendary franchises. Navigate mechanical stages and use classic Kirby skills to win.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-no-kirakira-kids-english-v11', 'SNES', 'Kirby no Kirakira Kids (English v1.1)', '1996', 'Puzzle', 'HAL Laboratory', '2', 'Tile matching', 'Falling-block puzzle game with a full English fan translation.', 'Clear the screen by matching Kirby''s animal friends.', 'Play Kirby no Kirakira Kids in English on the SNES.', 'The fan-translated version of the Super Famicom puzzler. A 16-bit gem that features the "Star Stacker" gameplay with updated graphics and sound.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-no-kirakira-kids-japan', 'SNES', 'Kirby no Kirakira Kids (Japan)', '1996', 'Puzzle', 'HAL Laboratory', '2', 'Tile matching', 'Falling-block puzzle game featuring Kirby and his friends.', 'Outsmart your opponent in this competitive puzzle challenge.', 'Experience the vibrant Kirby no Kirakira Kids on SNES.', 'A beautiful 16-bit remake of the Game Boy classic. Features various modes, a story campaign, and addictive competitive multiplayer action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-super-star-usa', 'SNES', 'Kirby Super Star (USA)', '1996', 'Action', 'HAL Laboratory', '2', 'Platformer compilation', 'Multi-game collection featuring eight distinct Kirby adventures.', 'Complete all eight games to unlock the ultimate challenge.', 'Play the legendary Kirby Super Star on the SNES.', 'The peak of 16-bit Kirby. Features "Great Cave Offensive," "Milky Way Wishes," and more, plus the debut of 2-player co-op with the Helper system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirbys-avalanche-usa', 'SNES', 'Kirby''s Avalanche (USA)', '1995', 'Puzzle', 'HAL Laboratory', '2', 'Competitive puzzle', 'Competitive falling-block puzzle game (Puyo Puyo reskin).', 'Defeat King Dedede and his minions in a puzzle tournament.', 'Challenge the mountain in Kirby''s Avalanche on the SNES.', 'The North American version of Puyo Puyo. Features Kirby-themed 16-bit graphics and dialogue, offering fast-paced and addictive chain-based puzzle action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirbys-dream-course-europe', 'SNES', 'Kirby''s Dream Course (Europe)', '1994', 'Sports', 'HAL Laboratory', '2', 'Minigolf', 'Mini-golf simulation with power-ups and Kirby mechanics.', 'Turn enemies into stars and reach the hole in as few shots as possible.', 'Play Kirby''s Dream Course for the Super Nintendo.', 'An isometric 16-bit masterpiece. Use Kirby''s copy abilities like Stone, Tornado, and Spark to navigate complex 3D-style courses and earn medals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirbys-dream-course-usa', 'SNES', 'Kirby''s Dream Course (USA)', '1994', 'Sports', 'HAL Laboratory', '2', 'Minigolf', 'Mini-golf simulation with power-ups and Kirby mechanics.', 'Master the trajectories and power-ups to win the gold.', 'Experience Kirby''s Dream Course on the Super Nintendo.', 'A unique 16-bit blend of sports and strategy. Features challenging level designs and a highly competitive multiplayer mode for two players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirbys-dream-land-3-usa', 'SNES', 'Kirby''s Dream Land 3 (USA)', '1997', 'Platformer', 'HAL Laboratory', '2', 'Platformer', 'Side-scrolling platformer with a hand-drawn "colored pencil" art style.', 'Defeat Dark Matter and restore peace to Dream Land.', 'Discover the beautiful Kirby''s Dream Land 3 on SNES.', 'One of the most visually unique 16-bit games. Team up with Gooey and animal friends like Rick, Coo, and Kine to solve puzzles and beat bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirbys-fun-pak-europe', 'SNES', 'Kirby''s Fun Pak (Europe)', '1996', 'Action', 'HAL Laboratory', '2', 'Platformer compilation', 'Multi-game collection featuring eight distinct Kirby adventures.', 'Complete the epic collection in the European release.', 'Play Kirby''s Fun Pak on the Super Nintendo.', 'The European title for Kirby Super Star. Features the same high-quality 16-bit content, including the legendary co-op modes and boss rushes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirbys-ghost-trap-europe', 'SNES', 'Kirby''s Ghost Trap (Europe)', '1995', 'Puzzle', 'HAL Laboratory', '2', 'Puzzle action', 'Competitive falling-block puzzle game (Puyo Puyo reskin).', 'Master the chains and defeat rivals in this European puzzler.', 'Play Kirby''s Ghost Trap for the Super Nintendo.', 'The European title for Kirby''s Avalanche. Features the classic 16-bit Puyo Puyo mechanics with a charming Kirby-themed makeover.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kishin-douji-zenki---battle-raiden-japan', 'SNES', 'Kishin Douji Zenki - Battle Raiden (Japan)', '1995', 'Action', 'Banpresto', '1', 'Anime action', 'Side-scrolling action-platformer based on the Zenki anime.', 'Defeat the seeds of Goki and stop the evil Karma.', 'Experience Battle Raiden: Zenki on the Super Famicom.', 'A high-quality 16-bit action game. Transform between Zenki''s forms to balance speed and power while fighting through mythological Japanese stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kishin-douji-zenki---denei-raibu-japan', 'SNES', 'Kishin Douji Zenki - Denei Raibu (Japan)', '1996', 'Action', 'Banpresto', '1', 'Anime action', 'Cinematic visual novel and adventure game based on Zenki.', 'Solve the mystery of the ghost light and protect the world.', 'Explore Denei Raibu: Zenki on the Super Famicom.', 'A dialogue-heavy 16-bit adventure. Navigate through a supernatural narrative, make key choices, and engage in strategic combat sequences inspired by the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kishin-douji-zenki---tenchi-meidou-japan', 'SNES', 'Kishin Douji Zenki - Tenchi Meidou (Japan)', '1997', 'Action', 'Banpresto', '1', 'Anime action', 'Strategy-RPG featuring the cast of the Zenki series.', 'Command Zenki and Chiaki in tactical turn-based combat.', 'Master strategy in Zenki: Tenchi Meidou on Super Famicom.', 'A deep 16-bit tactical game. Manage your party''s skills and placement on the grid to defeat demonic forces in this story-driven JRPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kishin-kourinden-oni-japan', 'SNES', 'Kishin Kourinden Oni (Japan)', '1994', 'RPG', 'Banpresto', '1', 'Action RPG', 'Traditional turn-based RPG with a mythological Oni theme.', 'Lead the Oni warriors to stop a dark demonic uprising.', 'Explore the ancient world of Kishin Kourinden Oni on SNES.', 'Part of the long-running Oni series. Features 16-bit turn-based combat, a world map rooted in Japanese folklore, and a deep character-growth system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kishin-kourinden-oni-japan-beta', 'SNES', 'Kishin Kourinden Oni (Japan) (Beta)', '1994', 'RPG', 'Banpresto', '1', 'Action RPG beta', 'Traditional turn-based RPG with a mythological Oni theme.', 'Test the early world map and combat balancing.', 'Check out the Kishin Kourinden Oni Beta on SNES.', 'A pre-release 16-bit development build. Witness the early implementation of the mythological narrative and tactical encounter designs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kiteretsu-daihyakka---choujikuu-sugoroku-japan', 'SNES', 'Kiteretsu Daihyakka - Choujikuu Sugoroku (Japan)', '1995', 'Board Game', 'Epoch', '4', 'Sugoroku board game', 'Digital board game (Sugoroku) based on the classic anime.', 'Race across time and space to reach the goal before your rivals.', 'Play Kiteretsu Daihyakka on the Super Famicom.', 'A charming 16-bit board game featuring Kiteretsu and Korosuke. Use futuristic gadgets to sabotage opponents and navigate through different historical eras in this colorful family game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('knights-of-the-round-europe', 'SNES', 'Knights of the Round (Europe)', '1994', 'Action', 'Capcom', '2', 'Beat ''em up', 'Side-scrolling beat ''em up with an RPG-style leveling system.', 'Overthrow the tyrant Garibaldi and claim the Holy Grail.', 'Become a legend in Knights of the Round for the SNES.', 'A 16-bit Capcom masterpiece. Choose between Arthur, Lancelot, or Perceval. As you defeat enemies, your character levels up, visually changing their armor and weapons in real-time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('knights-of-the-round-japan', 'SNES', 'Knights of the Round (Japan)', '1994', 'Action', 'Capcom', '2', 'Beat ''em up', 'Side-scrolling beat ''em up with an RPG-style leveling system.', 'Claim the throne in the original Japanese version.', 'Experience Knights of the Round on the Super Famicom.', 'The foundational 16-bit release of the arcade hit. Features horse-mounted combat, satisfying parry mechanics, and some of the best medieval pixel art on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('knights-of-the-round-usa', 'SNES', 'Knights of the Round (USA)', '1994', 'Action', 'Capcom', '2', 'Beat ''em up', 'Side-scrolling beat ''em up with an RPG-style leveling system.', 'Lead the Knights to victory and restore order to Britain.', 'Battle through Knights of the Round on the Super Nintendo.', 'Master the strategic blocking system to earn invincibility frames. A polished 16-bit brawler that rewards skill and features epic boss fights against heavily armored rivals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konpeki-no-kantai-japan', 'SNES', 'Konpeki no Kantai (Japan)', '1993', 'Strategy', 'SEGA', '1', 'Naval strategy', 'Deep naval strategy simulation set in an alternate WWII.', 'Command the Imperial Japanese Navy to dominate the Pacific.', 'Master the seas in Konpeki no Kantai on Super Famicom.', 'A complex 16-bit strategy game based on the popular "Deep Blue Fleet" novels. Manage fleet formations, technological research, and tactical naval engagements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kouryaku-casino-bar-japan', 'SNES', 'Kouryaku Casino Bar (Japan)', '1996', 'Casino', 'Namco', '1', 'Casino simulation', 'Gambling simulation featuring various casino table games.', 'Win the high-stakes tournament and break the casino bank.', 'Test your luck in Kouryaku Casino Bar on Super Famicom.', 'Features realistic 16-bit renditions of Blackjack, Poker, and Roulette. Practice your betting strategies in a detailed virtual casino environment with smooth menu navigation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kouryuu-densetsu-villgust---kieta-shoujo-japan', 'SNES', 'Kouryuu Densetsu Villgust - Kieta Shoujo (Japan)', '1992', 'RPG', 'TOSE', '1', 'Story RPG', 'Turn-based JRPG based on the dark fantasy anime and manga.', 'Lead Murobo and his party to rescue the kidnapped girl.', 'Discover Kouryuu Densetsu Villgust on the Super Famicom.', 'A traditional 16-bit RPG featuring random encounters and turn-based combat. Explore a world filled with mythological creatures and detailed character portraits inspired by the OVA series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kouryuu-densetsu-villgust---kieta-shoujo-japan-en-by-magic-destiny-v10', 'SNES', 'Kouryuu Densetsu Villgust - Kieta Shoujo (Japan) [En by Magic Destiny v1.0]', '1992', 'RPG', 'TOSE', '1', 'Story RPG translated', 'Turn-based JRPG with a full English fan translation.', 'Experience the dark fantasy epic with English text.', 'Play Villgust in English on the Super Nintendo.', 'The Magic Destiny translation makes this hidden 16-bit gem accessible. Follow the emotional story of the lost girl through ancient ruins and dangerous dungeons in English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kouryuu-no-mimi-japan', 'SNES', 'Kouryuu no Mimi (Japan)', '1995', 'Adventure', 'Hudson Soft', '1', 'Adventure', 'Side-scrolling beat ''em up based on the adult action manga.', 'Defeat the rival corporate gangs and reclaim your fortune.', 'Fight for power in Kouryuu no Mimi on Super Famicom.', 'Control Natsume Kiroemon in this stylish 16-bit brawler. Use your magical ear to gain power-ups and unleash devastating attacks against waves of urban thugs and bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kouryuuki-japan', 'SNES', 'Kouryuuki (Japan)', '1992', 'Strategy', 'Naxat Soft', '1', 'Historical strategy', 'Historical strategy simulation set in ancient China.', 'Unify the warring states through diplomacy and conquest.', 'Master the art of war in Kouryuuki on the Super Famicom.', 'A deep Koei-style 16-bit strategy title. Manage your resources, recruit legendary generals, and engage in tactical grid-based battles to claim the imperial throne.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koushien-2-japan', 'SNES', 'Koushien 2 (Japan)', '1992', 'Sports', 'Magical Company', '2', 'Baseball', 'Realistic baseball simulation focusing on the high school tournament.', 'Lead your school team to victory at the legendary Koushien.', 'Play the authentic Koushien 2 on the Super Famicom.', 'Features a deep focus on team training and player development. A 16-bit sports sim that captures the intense drama of Japan''s most famous youth baseball event.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koushien-3-japan', 'SNES', 'Koushien 3 (Japan)', '1994', 'Sports', 'Magical Company', '2', 'Baseball', 'Sequel to the popular high school baseball simulation.', 'Master the 16-bit diamond and win the national championship.', 'Experience Koushien 3 on the Super Famicom.', 'Introduces updated player stats and improved fielding animations. Manage your roster''s stamina and morale to survive the grueling tournament structure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koushien-4-japan', 'SNES', 'Koushien 4 (Japan)', '1996', 'Sports', 'Magical Company', '2', 'Baseball', 'The final entry in the 16-bit Koushien baseball series.', 'Achieve glory at the stadium in this definitive sequel.', 'Play the polished Koushien 4 on the Super Famicom.', 'The most advanced 16-bit entry in the franchise. Features refined pitching mechanics, more detailed stadium crowds, and a comprehensive career mode for your players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kousoku-shikou---shougi-ou-japan', 'SNES', 'Kousoku Shikou - Shougi Ou (Japan)', '1995', 'Board Game', 'Naxat Soft', '2', 'Shougi', 'Traditional Shogi (Japanese Chess) simulation with high-speed AI.', 'Defeat the Shogi King through fast and strategic play.', 'Master Shogi in Kousoku Shikou on the Super Famicom.', 'Known for its rapid AI processing power. A technical 16-bit board game that offers a variety of difficulty levels and a helpful analysis mode for learning players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koutetsu-no-kishi-japan', 'SNES', 'Koutetsu no Kishi (Japan)', '1994', 'Strategy', 'Naxat Soft', '1', 'WWII strategy', 'Tactical tank combat simulation set during World War II.', 'Lead your panzer division to victory across historical battles.', 'Command the armor in Koutetsu no Kishi on Super Famicom.', 'A detailed 16-bit simulation of tank warfare. Focuses on realistic ballistics, armor thickness, and tactical positioning across various European fronts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koutetsu-no-kishi-2---sabaku-no-rommel-gundan-japan', 'SNES', 'Koutetsu no Kishi 2 - Sabaku no Rommel Gundan (Japan)', '1995', 'Strategy', 'Naxat Soft', '1', 'WWII strategy', 'Tactical tank combat sequel set in the North African theater.', 'Master the desert dunes and outmaneuver Rommel''s forces.', 'Experience Koutetsu no Kishi 2 on the Super Famicom.', 'Shifts the 16-bit action to the African desert. Features new tank models and environmental hazards like sandstorms that affect visibility and movement.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koutetsu-no-kishi-3---gekitotsu-europe-sensen-japan', 'SNES', 'Koutetsu no Kishi 3 - Gekitotsu Europe Sensen (Japan)', '1996', 'Strategy', 'Naxat Soft', '1', 'WWII strategy', 'The final installment focusing on the late-war European front.', 'Engage in the ultimate armored clash for the future of Europe.', 'Play Koutetsu no Kishi 3 on the Super Famicom.', 'The peak of the 16-bit tank sim series. Features the most advanced armor rosters and complex tactical scenarios, requiring deep knowledge of WWII machinery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('krustys-super-fun-house-europe', 'SNES', 'Krusty''s Super Fun House (Europe)', '1992', 'Action', 'Audiogenic', '2', 'Puzzle platformer', 'Puzzle-platformer where you guide mice into traps to clear levels.', 'Help Krusty the Clown rid his fun house of a mouse infestation.', 'Solve the puzzles in Krusty''s Super Fun House on SNES.', 'Control Krusty as you manipulate the environment to lead mice to their doom. A clever 16-bit puzzler with a catchy soundtrack and appearances from Simpsons characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('krustys-super-fun-house-europe-rev-a', 'SNES', 'Krusty''s Super Fun House (Europe) (Rev A)', '1992', 'Action', 'Audiogenic', '2', 'Puzzle platformer', 'Puzzle-platformer with refined mechanics and bug fixes.', 'Clear the fun house in this updated 16-bit version.', 'Play the polished Krusty''s Super Fun House (Rev A).', 'An updated European revision that improves the 16-bit physics and fixes minor stage-glitches, providing a smoother puzzle-solving experience for fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('krustys-super-fun-house-usa', 'SNES', 'Krusty''s Super Fun House (USA)', '1992', 'Action', 'Audiogenic', '2', 'Puzzle platformer', 'Puzzle-platformer where you guide mice into traps to clear levels.', 'Help Krusty the Clown rid his fun house of a mouse infestation.', 'Solve the puzzles in Krusty''s Super Fun House on SNES.', 'Navigate through increasingly complex 16-bit levels. Use blocks and stairs to guide the mice while avoiding hazards in this nostalgic licensed classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('krustys-super-fun-house-usa-rev-a', 'SNES', 'Krusty''s Super Fun House (USA) (Rev A)', '1992', 'Action', 'Audiogenic', '2', 'Puzzle platformer', 'Puzzle-platformer with refined mechanics and bug fixes.', 'Clear the fun house in this updated 16-bit version.', 'Play the polished Krusty''s Super Fun House (Rev A) on SNES.', 'The final North American 16-bit revision. Features optimized code for better performance during the game''s more crowded and complex puzzle stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('krustys-world-japan', 'SNES', 'Krusty''s World (Japan)', '1994', 'Action', 'Acclaim', '2', 'Platformer', 'Puzzle-platformer where you guide mice into traps to clear levels.', 'Experience the Japanese version of Krusty''s puzzle challenge.', 'Play Krusty''s World on the Super Famicom.', 'The Japanese release of Krusty''s Super Fun House. Features the same addictive 16-bit logic puzzles and colorful graphics that made the game a global hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kunio-no-oden-japan', 'SNES', 'Kunio no Oden (Japan)', '1994', 'Action', 'Technos Japan', '2', 'Action brawler', 'Unique puzzle-action game based on the Kunio-kun series.', 'Match Oden ingredients to clear the board and defeat rivals.', 'Solve the tasty Kunio no Oden on the Super Famicom.', 'A "Puyo Puyo" style 16-bit puzzler with a Japanese twist. Play as Kunio and match various food items to send garbage blocks to your opponent''s screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kunio-kun-no-dodge-ball-dayo-zenin-shuugou!---tournament-special-japan', 'SNES', 'Kunio-kun no Dodge Ball dayo Zenin Shuugou! - Tournament Special (Japan)', '1993', 'Sports', 'Technos Japan', '4', 'Dodgeball', 'Enhanced dodgeball tournament simulation featuring the Kunio cast.', 'Win the world dodgeball championship using special shots.', 'Hit the court in Kunio''s Dodge Ball: Tournament Special.', 'A high-energy 16-bit sports game. Features flashy special attacks, customizable team stats, and the iconic "super-deformed" art style of the franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kunio-kun-no-dodge-ball-dayo-zenin-shuugou!-japan', 'SNES', 'Kunio-kun no Dodge Ball dayo Zenin Shuugou! (Japan)', '1993', 'Sports', 'Technos Japan', '4', 'Dodgeball', 'Fast-paced arcade dodgeball game for up to four players.', 'Eliminate the opposing team with powerful throws and jumps.', 'Experience Kunio-kun no Dodge Ball on the Super Famicom.', 'The definitive 16-bit dodgeball experience. Features diverse stages with environmental hazards and a huge variety of "super shots" that defy the laws of physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kunio-kun-no-dodge-ball-dayo-zenin-shuugou!-japan-en-by-azelistic-v10-~kunios-dodge-ball', 'SNES', 'Kunio-kun no Dodge Ball dayo Zenin Shuugou! (Japan) [En by Azelistic v1.0] (~Kunio''s Dodge Ball)', '1993', 'Sports', 'Technos Japan', '4', 'Dodgeball translated', 'Fast-paced arcade dodgeball game with a full English translation.', 'Play the ultimate dodgeball tournament with English text.', 'Play Kunio''s Dodge Ball in English on the Super Nintendo.', 'The Azelistic translation makes the team management and special move names accessible. Experience the best 16-bit dodgeball action in your own language.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kuusou-kagaku-sekai-gulliver-boy-japan', 'SNES', 'Kuusou Kagaku Sekai Gulliver Boy (Japan)', '1995', 'Action', 'Bandai', '1', 'Anime action', 'Hybrid Action-RPG and adventure based on the sci-fi anime.', 'Travel the world and stop the evil empire as Gulliver.', 'Join the epic Gulliver Boy on the Super Famicom.', 'A visually impressive 16-bit RPG. Combines top-down exploration with cinematic combat sequences and a humorous, fast-paced story inspired by the hit series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kuusou-kagaku-sekai-gulliver-boy-japan-en-by-stealth-v099', 'SNES', 'Kuusou Kagaku Sekai Gulliver Boy (Japan) [En by Stealth v0.99]', '1995', 'Action', 'Bandai', '1', 'Anime action translated', 'Hybrid Action-RPG and adventure with an English fan translation.', 'Experience Gulliver''s steampunk adventure with English text.', 'Play Gulliver Boy in English on the Super Nintendo.', 'The Stealth translation allows you to enjoy the witty dialogue and complex sci-fi plot of this late-gen 16-bit masterpiece. A must-play for JRPG fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kyle-pettys-no-fear-racing-usa', 'SNES', 'Kyle Petty''s No Fear Racing (USA)', '1995', 'Racing', 'Video System', '1', 'Stock car racing', 'Pseudo-3D racing game featuring stock cars and Mode 7.', 'Win the NASCAR championship with Kyle Petty''s guidance.', 'Experience high-speed action in Kyle Petty''s No Fear Racing.', 'A technical 16-bit racer that uses Mode 7 for smooth track rotation. Features a unique car damage system and varied tracks that require precise driving to master the stock car circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kyuuyaku-megami-tensei-eng-v11', 'SNES', 'Kyuuyaku Megami Tensei (Eng v1.1)', '1995', 'RPG', 'Atlus', '1', 'Dungeon RPG', 'Remake of the first two Shin Megami Tensei games in English.', 'Survive the demon apocalypse with a full English translation.', 'Play Kyuuyaku Megami Tensei in English on the SNES.', 'Experience the origins of the Megaten series. This 16-bit remake features improved graphics and sound, allowing you to recruit and fuse demons in English for the first time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kyuuyaku-megami-tensei-japan', 'SNES', 'Kyuuyaku Megami Tensei (Japan)', '1995', 'RPG', 'Atlus', '1', 'Dungeon RPG', 'Remake of the first two Shin Megami Tensei games with updated tech.', 'Recruit demons and save humanity in the original Japanese version.', 'Discover Kyuuyaku Megami Tensei on the Super Famicom.', 'A comprehensive 16-bit compilation of the Famicom classics. Features atmospheric dungeon crawling, a complex demon fusion system, and the dark narrative that defined the franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lady-stalker---kako-kara-no-chousen-japan', 'SNES', 'Lady Stalker - Kako Kara no Chousen (Japan)', '1995', 'RPG', 'Taito', '1', 'Action RPG', 'Isometric Action-RPG spinoff of the Landstalker series.', 'Lead Lady Stalker on a treasure hunt filled with traps and rivals.', 'Explore the world of Lady Stalker on the Super Famicom.', 'Control the mischievous Lady in this vibrant 16-bit adventure. Features a unique combat system, clever environmental puzzles, and a humorous story from the masters at Climax.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lagoon-europe', 'SNES', 'Lagoon (Europe)', '1991', 'RPG', 'Kemco', '1', 'Action RPG', 'Action-RPG with a focus on real-time combat and exploration.', 'Defeat the evil Zemer and restore the light to Lagoon.', 'Embark on the quest of Lagoon for the Super Nintendo.', 'A classic 16-bit adventure known for its challenging sword-swinging combat. Explore massive castles and dungeons while mastering powerful elemental magic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lagoon-germany', 'SNES', 'Lagoon (Germany)', '1991', 'RPG', 'Kemco', '1', 'Action RPG', 'Action-RPG with a focus on real-time combat and exploration.', 'Defeat the evil Zemer in the localized German version.', 'Spielen Sie Lagoon auf Deutsch für das SNES.', 'The complete 16-bit fantasy adventure with localized German text. Navigate dangerous maps and defeat colossal bosses to save the land of Lakeland.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lagoon-japan', 'SNES', 'Lagoon (Japan)', '1991', 'RPG', 'Kemco', '1', 'Action RPG', 'Action-RPG with a focus on real-time combat and exploration.', 'Defeat the evil Zemer in the original Japanese version.', 'Experience the original Lagoon on the Super Famicom.', 'The foundational 16-bit release. Features impressive boss sprites and an iconic soundtrack that sets the tone for this difficult but rewarding RPG quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lagoon-usa', 'SNES', 'Lagoon (USA)', '1991', 'RPG', 'Kemco', '1', 'Action RPG', 'Action-RPG with a focus on real-time combat and exploration.', 'Defeat the evil Zemer and restore the light to Lagoon.', 'Embark on the quest of Lagoon for the Super Nintendo.', 'Master the short-sword combat and magic system. A nostalgic 16-bit RPG that tests your reflexes and your ability to navigate complex maze-like environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lamborghini---american-challenge-europe', 'SNES', 'Lamborghini - American Challenge (Europe)', '1993', 'Racing', 'Titus', '2', 'Arcade racing', 'High-speed arcade racer featuring licensed Lamborghini cars.', 'Win illegal street races across the USA to buy better cars.', 'Race for glory in Lamborghini American Challenge on SNES.', 'A 16-bit racing classic. Use your earnings to upgrade your Diablo, bet on races, and avoid the police in this fast-paced and stylish arcade simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lamborghini---american-challenge-usa', 'SNES', 'Lamborghini - American Challenge (USA)', '1993', 'Racing', 'Titus', '2', 'Arcade racing', 'High-speed arcade racer featuring licensed Lamborghini cars.', 'Win illegal street races across the USA to buy better cars.', 'Race for glory in Lamborghini American Challenge on SNES.', 'Features smooth Mode 7 scaling and intense 2-player split-screen action. Master the curves and nitro boosts to become the king of the American streets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('langrisser-der-japan', 'SNES', 'Langrisser, Der (Japan)', '1991', 'Strategy', 'NCS', '1', 'Tactical RPG', 'Tactical turn-based JRPG with a focus on branching paths.', 'Lead Ledin or Elwin through an epic war between Light and Dark.', 'Play the legendary Der Langrisser on Super Famicom.', 'The definitive 16-bit tactical RPG. Features a massive cast of units, deep commander mechanics, and a story that changes significantly based on your moral choices.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('langrisser-der-japan-rev-1-en-by-byuu+d-v102', 'SNES', 'Langrisser, Der (Japan) (Rev 1) [En by Byuu+D v1.02]', '1991', 'Strategy', 'NCS', '1', 'Tactical RPG translated', 'Tactical turn-based JRPG with a full English fan translation.', 'Experience the epic branching narrative with English text.', 'Play Der Langrisser in English on the Super Nintendo.', 'The Byuu+D translation makes this 16-bit masterpiece fully accessible. Command massive armies and explore all four major story paths in your own language.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('langrisser-der-japan-rev-a', 'SNES', 'Langrisser, Der (Japan) (Rev A)', '1991', 'Strategy', 'NCS', '1', 'Tactical RPG', 'Tactical turn-based JRPG with a focus on branching paths.', 'Lead the army to victory in this refined revision.', 'Play the polished Der Langrisser (Rev A) on SNES.', 'The updated 16-bit Japanese revision featuring minor balance tweaks to unit stats and bug fixes for a smoother tactical experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('laplace-no-ma-japan', 'SNES', 'Laplace no Ma (Japan)', '1989', 'RPG', 'Video System', '1', 'Horror RPG', 'Survival horror JRPG set in a haunted 1920s mansion.', 'Investigate supernatural occurrences using occult skills.', 'Survive the eerie Laplace no Ma on the Super Famicom.', 'A unique 16-bit blend of RPG and horror. Choose your character class, from detectives to mediums, and explore a cursed estate filled with ghosts and puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('laplace-no-ma-japan-en-by-aeon-genesis-v095b-~laplaces-demon', 'SNES', 'Laplace no Ma (Japan) [En by Aeon Genesis v0.95B] (~Laplace''s Demon)', '1989', 'RPG', 'Video System', '1', 'Horror RPG translated', 'Survival horror JRPG with an English fan translation.', 'Uncover the mansion''s secrets with English text.', 'Play Laplace''s Demon in English on the Super Nintendo.', 'The Aeon Genesis translation allows you to experience this atmospheric 16-bit horror classic. Navigate the dark narrative and tactical turn-based combat in English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('laplaces-demon-english-v20', 'SNES', 'Laplace''s Demon (English v.2.0)', '1989', 'RPG', 'Video System', '1', 'Horror RPG translated', 'Survival horror JRPG with an updated English fan translation.', 'Investigate the occult mysteries in this refined English version.', 'Play Laplace''s Demon v2.0 in English on the SNES.', 'An improved 16-bit translation that polishes the script and interface, providing the most immersive way to experience this cult classic supernatural RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('larry-nixons-super-bass-fishing-japan', 'SNES', 'Larry Nixon''s Super Bass Fishing (Japan)', '1994', 'Sports', 'Konami', '1', 'Fishing', 'Realistic bass fishing simulation featuring Larry Nixon.', 'Win professional tournaments by mastering lure and location.', 'Go pro in Larry Nixon''s Super Bass Fishing on SNES.', 'Features a detailed 16-bit underwater view and realistic fish behavior. Navigate your boat and use Nixon''s expert advice to land the biggest bass.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('las-vegas-dream-in-golden-paradise-japan', 'SNES', 'Las Vegas Dream in Golden Paradise (Japan)', '1995', 'Board Game', 'Human', '1', 'Casino simulation', 'Casino simulation featuring a variety of Las Vegas games.', 'Build your fortune and live the high life in a virtual casino.', 'Bet big in Las Vegas Dream on the Super Famicom.', 'Features 16-bit versions of Blackjack, Slots, and Roulette. Includes a story mode where you manage your wealth and interact with diverse casino characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('laser-suit-powerup-v17', 'SNES', 'Laser Suit Powerup V1.7', '—', 'Homebrew', '—', '1', 'Custom action', 'Fan-made gameplay modification for Metroid.', 'Explore a modified world with enhanced beam power-ups.', 'Play the Laser Suit Powerup mod for the SNES.', 'A creative 16-bit romhack that alters Samus''s suit and weaponry. Experience new combat dynamics and visual effects in a familiar yet revamped environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('last-action-hero-europe', 'SNES', 'Last Action Hero (Europe)', '1993', 'Action', 'Sony Imagesoft', '1', 'Movie platformer', 'Action-platformer based on the film starring Schwarzenegger.', 'Defeat the movie villains and protect the magic ticket.', 'Play Last Action Hero for the Super Nintendo.', 'Control Jack Slater through 16-bit levels inspired by the film''s set pieces. Features brawling action and driving segments with digitized character sprites.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('last-action-hero-usa', 'SNES', 'Last Action Hero (USA)', '1993', 'Action', 'Sony Imagesoft', '1', 'Movie platformer', 'Action-platformer based on the film starring Schwarzenegger.', 'Defeat the movie villains and protect the magic ticket.', 'Play Last Action Hero for the Super Nintendo.', 'Battle through the cinema and the real world. A challenging 16-bit licensed title that captures the over-the-top action and humor of the movie.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('last-battle-the-japan', 'SNES', 'Last Battle, The (Japan)', '1989', 'Action', 'Namco', '1', 'Beat ’em up', 'Action-platformer based on the dark fantasy world of Kenpuryu.', 'Defeat the demonic lords and save the kingdom.', 'Discover The Last Battle on the Super Famicom.', 'Known for its gritty atmosphere and large 16-bit sprites. Master your combat skills and explore a dark world filled with formidable enemies and challenging puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('last-bible-iii-english-v7', 'SNES', 'Last Bible III (English v7)', '1995', 'RPG', 'Atlus', '1', 'JRPG translated', 'Turn-based RPG from the Megami Tensei Gaiden series.', 'Prevent a demonic invasion in a lush fantasy world.', 'Play Last Bible III in English on the Super Nintendo.', 'The first 16-bit entry in the series to leave the handhelds. Features a vibrant world, demon recruitment, and a deep turn-based combat system now fully in English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('last-bible-iii-japan', 'SNES', 'Last Bible III (Japan)', '1995', 'RPG', 'Atlus', '1', 'JRPG', 'Turn-based RPG from the Megami Tensei Gaiden series.', 'Recruit monsters and save the world in the original Japanese version.', 'Experience Last Bible III on the Super Famicom.', 'A late-gen 16-bit JRPG masterpiece. Features beautiful pixel art, an emotional soundtrack, and the trademark demon-negotiation mechanics of the Megaten franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lawnmower-man-the-europe', 'SNES', 'Lawnmower Man, The (Europe)', '1994', 'Action', 'Virgin Interactive', '1', 'Cinematic action', 'Cyberpunk action-adventure based on the 1992 film.', 'Navigate Virtual Reality and stop the Lawnmower Man.', 'Enter the system in The Lawnmower Man for the SNES.', 'Features a mix of side-scrolling platforming and early 3D-style flying segments. Experience the 16-bit interpretation of cyberspace in this unique movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lawnmower-man-the-usa', 'SNES', 'Lawnmower Man, The (USA)', '1994', 'Action', 'Virgin Interactive', '1', 'Cinematic action', 'Cyberpunk action-adventure based on the 1992 film.', 'Navigate Virtual Reality and stop the Lawnmower Man.', 'Enter the system in The Lawnmower Man for the SNES.', 'Master the 16-bit puzzles and high-speed tunnel sequences. A visually ambitious title that pushed the SNES''s scaling and rotation capabilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lawnmower-man-the-usa-beta', 'SNES', 'Lawnmower Man, The (USA) (Beta)', '1994', 'Action', 'Virgin Interactive', '1', 'Cinematic action', 'Cyberpunk action-adventure based on the 1992 film.', 'Test early level designs and VR flight mechanics.', 'Check out The Lawnmower Man (Beta) on the SNES.', 'A pre-release 16-bit development build. Witness the fine-tuning of the pseudo-3D segments and the evolution of the cyberpunk environments before the final launch.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('leading-company-japan', 'SNES', 'Leading Company (Japan)', '1992', 'Simulation', 'Koei', '1', 'Business simulation', 'Business management simulation about running a tech corporation.', 'Build a global electronics empire and bankrupt your rivals.', 'Master the market in Leading Company on Super Famicom.', 'A deep 16-bit strategy game from Koei. Manage R&D, marketing, and manufacturing to stay ahead in the competitive world of technology.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('leading-jockey-japan', 'SNES', 'Leading Jockey (Japan)', '1993', 'Sports', 'Koei', '1', 'Horse racing', 'Professional horse racing simulation and jockey career mode.', 'Climb the ranks and win the G1 races as a pro jockey.', 'Experience Leading Jockey on the Super Famicom.', 'Focuses on the skill of riding rather than just betting. Master 16-bit stamina management and positioning to lead your horse to the finish line.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('leading-jockey-2-japan', 'SNES', 'Leading Jockey 2 (Japan)', '1995', 'Sports', 'Koei', '1', 'Horse racing', 'Professional horse racing simulation and jockey career mode.', 'Achieve glory in the sequel with updated rosters and tech.', 'Play Leading Jockey 2 on the Super Famicom.', 'Features improved 16-bit horse animations and more detailed track physics. Manage your jockey''s career and build relationships with owners to get the best mounts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-europe', 'SNES', 'Legend (Europe)', '1994', 'Action', 'Arc Developments', '2', 'Action adventure', 'Fantasy side-scrolling beat ''em up with a gritty medieval tone.', 'Defeat the evil sorcerer and reclaim the magical amulet.', 'Fight through the darkness in Legend for the SNES.', 'Features large, detailed 16-bit sprites and heavy-hitting combat. A cult classic brawler with an atmospheric soundtrack and challenging boss fights.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-usa', 'SNES', 'Legend (USA)', '1994', 'Action', 'Arc Developments', '2', 'Action adventure', 'Fantasy side-scrolling beat ''em up with a gritty medieval tone.', 'Defeat the evil sorcerer and reclaim the magical amulet.', 'Fight through the darkness in Legend for the SNES.', 'Master your sword skills in this 16-bit medieval epic. Navigate through forests and castles to bring peace to the kingdom of Selece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-usa-beta', 'SNES', 'Legend (USA) (Beta)', '1994', 'Action', 'Arc Developments', '2', 'Action adventure', 'Fantasy side-scrolling beat ''em up with a gritty medieval tone.', 'Test early combat physics and enemy AI in this prototype.', 'Check out the Legend (Beta) version on the SNES.', 'A rare 16-bit development build. Discover initial character movesets and environmental details for this atmospheric medieval brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-axem-rangers', 'SNES', 'Legend of Axem Rangers', '1997', 'Hack', 'Fans', '2', 'Superhero parody', 'Fan-made total conversion of Super Mario World.', 'Explore a new world inspired by the Axem Rangers.', 'Play Legend of Axem Rangers on the Super Nintendo.', 'A creative 16-bit romhack featuring new levels, custom music, and a unique story centered around the colorful villain team from Super Mario RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-the-mystical-ninja-the-europe', 'SNES', 'Legend of the Mystical Ninja, The (Europe)', '1991', 'Action', 'Konami', '2', 'Action-adventure', 'Action-adventure platformer set in a wacky version of feudal Japan.', 'Rescue the Princess and stop the Oedo Clan with Kid Goemon.', 'Experience Legend of the Mystical Ninja on SNES.', 'A 16-bit masterpiece of humor and action. Switch between Goemon and Ebisumaru in 2-player co-op, play mini-games, and explore vibrant Japanese towns.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-the-mystical-ninja-the-germany', 'SNES', 'Legend of the Mystical Ninja, The (Germany)', '1991', 'Action', 'Konami', '2', 'Action-adventure', 'Action-adventure platformer set in a wacky version of feudal Japan.', 'Rescue the Princess in the localized German version.', 'Spielen Sie Mystical Ninja auf Deutsch für das SNES.', 'The complete 16-bit adventure with localized German text. Experience the charm, the weirdness, and the incredible music of the Goemon series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-the-mystical-ninja-the-usa', 'SNES', 'Legend of the Mystical Ninja, The (USA)', '1991', 'Action', 'Konami', '2', 'Action-adventure', 'Action-adventure platformer set in a wacky version of feudal Japan.', 'Rescue the Princess and stop the Oedo Clan with Kid Goemon.', 'Experience Legend of the Mystical Ninja on SNES.', 'Master the pipe and shuriken attacks. A foundational 16-bit title that perfectly blends platforming, exploration, and RPG elements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lemmings-europe', 'SNES', 'Lemmings (Europe)', '1991', 'Puzzle', 'Psygnosis', '2', 'Strategy puzzle', 'Puzzle-strategy game where you guide green-haired creatures to safety.', 'Save the required number of Lemmings by assigning them tasks.', 'Master the puzzles in Lemmings for the Super Nintendo.', 'A perfect 16-bit port of the PC classic. Use climbers, floaters, and blockers to navigate through increasingly lethal environments filled with traps and pits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lemmings-japan', 'SNES', 'Lemmings (Japan)', '1991', 'Puzzle', 'Psygnosis', '2', 'Strategy puzzle', 'Puzzle-strategy game where you guide green-haired creatures to safety.', 'Guide the Lemmings to the exit in the original Japanese version.', 'Play Lemmings on the Super Famicom for brain-teasing fun.', 'Features the same addictive 16-bit logic puzzles and iconic music. A true test of planning and quick thinking across hundreds of levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lemmings-usa', 'SNES', 'Lemmings (USA)', '1991', 'Puzzle', 'Psygnosis', '2', 'Strategy puzzle', 'Puzzle-strategy game where you guide green-haired creatures to safety.', 'Save the required number of Lemmings by assigning them tasks.', 'Master the puzzles in Lemmings for the Super Nintendo.', 'Assign roles like builders and diggers in real-time. This 16-bit version offers smooth cursor controls and a password system for its massive campaign.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lemmings-usa-rev-a', 'SNES', 'Lemmings (USA) (Rev A)', '1991', 'Puzzle', 'Psygnosis', '2', 'Strategy puzzle', 'Puzzle-strategy game with refined controls and minor bug fixes.', 'Guide the Lemmings to safety in this updated revision.', 'Play the polished Lemmings (Rev A) on the SNES.', 'An updated 16-bit revision that fixes minor level-glitches and optimizes performance for a smoother experience during complex puzzle solutions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lemmings-2---the-tribes-europe', 'SNES', 'Lemmings 2 - The Tribes (Europe)', '1993', 'Puzzle', 'Psygnosis', '2', 'Strategy puzzle', 'Expanded puzzle-strategy sequel featuring 12 distinct tribes.', 'Save the Lemmings across diverse themed worlds like Egyptian and Space.', 'Experience Lemmings 2: The Tribes on the SNES.', 'Features way more skills than the original. Master the 16-bit mechanics of the Archer, Roper, and Hang Glider tribes in this ambitious and colorful sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lemmings-2---the-tribes-japan', 'SNES', 'Lemmings 2 - The Tribes (Japan)', '1993', 'Puzzle', 'Psygnosis', '2', 'Strategy puzzle', 'Expanded puzzle-strategy sequel featuring 12 distinct tribes.', 'Guide the tribes to safety in the original Japanese version.', 'Play Lemmings 2: The Tribes on the Super Famicom.', 'The 16-bit Japanese release featuring unique tribe animations and more complex environmental puzzles that require creative use of the new skill sets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lemmings-2---the-tribes-usa', 'SNES', 'Lemmings 2 - The Tribes (USA)', '1993', 'Puzzle', 'Psygnosis', '2', 'Strategy puzzle', 'Expanded puzzle-strategy sequel featuring 12 distinct tribes.', 'Save the Lemmings across diverse themed worlds like Egyptian and Space.', 'Experience Lemmings 2: The Tribes on the SNES.', 'A massive 16-bit expansion of the formula. Each tribe has its own unique music and aesthetic, offering a fresh take on the classic puzzle-strategy gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lennus---kodai-kikai-no-kioku-japan', 'SNES', 'Lennus - Kodai Kikai no Kioku (Japan)', '1992', 'RPG', 'Asmik', '1', 'Turn-based JRPG', 'Turn-based RPG set on the alien planet of Raika.', 'Stop the ancient machine Lennus from destroying the world.', 'Explore the alien Lennus on the Super Famicom.', 'Known as Paladin''s Quest in the West. Features a unique 16-bit pastel art style and a health-based magic system where spells cost HP instead of MP.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lennus-ii---fuuin-no-shito-japan', 'SNES', 'Lennus II - Fuuin no Shito (Japan)', '1994', 'RPG', 'Asmik', '1', 'Turn-based JRPG', 'Ambitious RPG sequel with improved graphics and world-building.', 'Gather the apostles and prevent the world''s destruction.', 'Play the legendary Lennus II on the Super Famicom.', 'One of the most visually striking 16-bit JRPGs. Features a massive world, a refined combat system, and a soundtrack that perfectly captures its alien atmosphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lennus-ii---fuuin-no-shito-japan-en-by-magic-destiny+stealth-v104-~lennus-ii---the-apostles-of-the-seals', 'SNES', 'Lennus II - Fuuin no Shito (Japan) [En by Magic Destiny+Stealth v1.04] (~Lennus II - The Apostles of the Seals)', '1994', 'RPG', 'Asmik', '1', 'Turn-based JRPG translated', 'Ambitious RPG sequel with a full English fan translation.', 'Experience the epic Lennus saga with English text.', 'Play Lennus II in English on the Super Nintendo.', 'The Magic Destiny translation makes this late-gen 16-bit masterpiece fully playable. Explore the bizarre world of Raika and solve the mystery of the Seals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lester-the-unlikely-usa', 'SNES', 'Lester the Unlikely (USA)', '1994', 'Platformer', 'DMA Design', '1', 'Cinematic platformer', 'Action-platformer starring a cowardly and unlikely hero.', 'Navigate through hazardous levels and find your way home.', 'Join the awkward adventure in Lester the Unlikely on SNES.', 'Control Lester, a hero who starts off scared and weak but gains confidence. Features rotoscoped 16-bit animations and a unique "fear" mechanic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lethal-enforcers-europe', 'SNES', 'Lethal Enforcers (Europe)', '1993', 'Shooter', 'Konami', '2', 'Light gun shooter', 'Light-gun arcade shooter set in a gritty urban environment.', 'Eliminate the bank robbers and crime syndicates as a police officer.', 'Take aim in Lethal Enforcers for the Super Nintendo.', 'A 16-bit port of the arcade hit. Use the Justifier light-gun to take down criminals across multiple stages, from bank heists to high-speed chases.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lethal-enforcers-japan', 'SNES', 'Lethal Enforcers (Japan)', '1993', 'Shooter', 'Konami', '2', 'Light gun shooter', 'Light-gun arcade shooter set in a gritty urban environment.', 'Clean up the streets in the original Japanese version.', 'Play Lethal Enforcers on the Super Famicom.', 'Features digitized 16-bit sprites and intense shooting action. Aim for the "Perfect" score while avoiding civilian casualties in this classic rail shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lethal-enforcers-usa', 'SNES', 'Lethal Enforcers (USA)', '1993', 'Shooter', 'Konami', '2', 'Light gun shooter', 'Light-gun arcade shooter set in a gritty urban environment.', 'Eliminate the bank robbers and crime syndicates as a police officer.', 'Take aim in Lethal Enforcers for the Super Nintendo.', 'Master your reload speed and accuracy. A high-stakes 16-bit shooter that rewards quick reflexes and precise aiming with the Justifier peripheral.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lethal-weapon-europe', 'SNES', 'Lethal Weapon (Europe)', '1992', 'Action', 'Ocean', '1', 'Action platformer', 'Side-scrolling action-platformer based on the hit movie series.', 'Stop the criminal cartel as Riggs and Murtaugh.', 'Fight for justice in Lethal Weapon for the SNES.', 'Control the iconic duo in this challenging 16-bit action title. Use guns and martial arts to navigate through levels inspired by the film''s set pieces.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lethal-weapon-usa', 'SNES', 'Lethal Weapon (USA)', '1992', 'Action', 'Ocean', '1', 'Action platformer', 'Side-scrolling action-platformer based on the hit movie series.', 'Stop the criminal cartel as Riggs and Murtaugh.', 'Fight for justice in Lethal Weapon for the SNES.', 'Features digitized character art and a variety of mission objectives. A gritty 16-bit licensed game that captures the "buddy cop" energy of the movies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('libble-rabble-japan', 'SNES', 'Libble Rabble (Japan)', '1989', 'Arcade', 'Namco', '2', 'Classic arcade', 'Unique puzzle-action game involving a "wrapping" mechanic.', 'Trap enemies and clear the board by surrounding them with your line.', 'Play the quirky Libble Rabble on the Super Famicom.', 'Created by the designer of Pac-Man. Features a unique 16-bit dual-cursor control scheme where you wrap lines around pegs to capture items and find treasure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('liberty-or-death-usa', 'SNES', 'Liberty or Death (USA)', '1993', 'Strategy', 'Koei', '1', 'Historical strategy', 'Historical strategy simulation set during the American Revolution.', 'Lead the American or British forces to total victory.', 'Master history in Liberty or Death on the SNES.', 'A deep Koei 16-bit strategy title. Manage finances, diplomacy, and tactical grid-based battles to change the course of the Revolutionary War.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('light-fantasy-japan', 'SNES', 'Light Fantasy (Japan)', '1992', 'RPG', 'Hudson Soft', '1', 'Fantasy JRPG', 'Turn-based JRPG with a bright and colorful fantasy world.', 'Defeat the dark forces and restore light to the kingdom.', 'Discover Light Fantasy on the Super Famicom.', 'A charming 16-bit RPG known for its soft art style and lighthearted narrative. Features a traditional turn-based combat system and a focus on character interactions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('light-fantasy-ii-japan', 'SNES', 'Light Fantasy II (Japan)', '1995', 'RPG', 'Hudson Soft', '1', 'Fantasy JRPG', 'Advanced JRPG sequel with refined mechanics and visuals.', 'Continue the legacy and save the world from a new threat.', 'Explore Light Fantasy II on the Super Famicom.', 'Features improved 16-bit sprites and a more complex story. A solid late-gen JRPG that rewards exploration and strategic party management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lion-king-the-europe', 'SNES', 'Lion King, The (Europe)', '1994', 'Platformer', 'Westwood Studios', '1', 'Action platformer', 'Cinematic action-platformer based on the Disney masterpiece.', 'Guide Simba from cub to king and defeat Scar.', 'Relive the magic in The Lion King for the SNES.', 'Features incredible 16-bit animation by Disney artists. Master the "Can''t Wait to be King" puzzle and the final showdown at Pride Rock.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lion-king-the-japan', 'SNES', 'Lion King, The (Japan)', '1994', 'Platformer', 'Westwood Studios', '1', 'Action platformer', 'Cinematic action-platformer based on the Disney masterpiece.', 'Experience Simba''s journey in the Japanese version.', 'Play The Lion King on the Super Famicom.', 'The original 16-bit Japanese release. Known for its lush jungle environments, iconic soundtrack, and punishing difficulty that challenges even veteran players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lion-king-the-usa', 'SNES', 'Lion King, The (USA)', '1994', 'Platformer', 'Westwood Studios', '1', 'Action platformer', 'Cinematic action-platformer based on the Disney masterpiece.', 'Guide Simba from cub to king and defeat Scar.', 'Relive the magic in The Lion King for the SNES.', 'Roar, pounce, and climb through beautiful 16-bit stages. A visual tour-de-force that captures the heart and challenge of the animated film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-magic-europe-proto', 'SNES', 'Little Magic (Europe) (Proto)', '1993', 'RPG', 'Altron', '1', 'Tactical RPG', 'Puzzle-adventure game with a focus on magical mechanics (Prototype).', 'Guide the protagonist through a series of environmental puzzles.', 'Check out the Little Magic Prototype for the SNES.', 'A rare look at the European version that never was. Features 16-bit magic-based puzzles where you move objects to reach the exit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-magic-japan', 'SNES', 'Little Magic (Japan)', '1993', 'RPG', 'Altron', '1', 'Tactical RPG', 'Puzzle-adventure game featuring a young witch in training.', 'Master your bubble magic to solve complex room-based puzzles.', 'Solve the puzzles in Little Magic for the Super Famicom.', 'A charming 16-bit puzzler. Use your magic to create and push bubbles into switches and pits to clear each of the increasingly difficult stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-magic-japan-beta', 'SNES', 'Little Magic (Japan) (Beta)', '1993', 'RPG', 'Altron', '1', 'Tactical RPG', 'Puzzle-adventure game featuring a young witch in training.', 'Test early bubble physics and level designs in this beta.', 'Check out the Little Magic (Beta) on the SNES.', 'A pre-release 16-bit development build. Witness the fine-tuning of the magic mechanics and early sprite animations for the cute protagonist.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-magic-japan-en-by-aeon-genesis-v100b', 'SNES', 'Little Magic (Japan) [En by Aeon Genesis v1.00B]', '1993', 'RPG', 'Altron', '1', 'Tactical RPG translated', 'Puzzle-adventure game with a full English fan translation.', 'Experience the magical bubble puzzles with English text.', 'Play Little Magic in English on the Super Nintendo.', 'The Aeon Genesis translation makes this clever 16-bit puzzler fully accessible. Help the young witch pass her exams by solving over 100 logical stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-master---nijiiro-no-maseki-japan', 'SNES', 'Little Master - Nijiiro no Maseki (Japan)', '1994', 'RPG', 'Tokai Engineering', '1', 'Turn-based JRPG', 'Tactical turn-based RPG with "chibi" character designs.', 'Lead the young knight on a quest to recover the magical gems.', 'Play Little Master: Nijiiro no Maseki on Super Famicom.', 'The third entry in the series and the first on 16-bit. Features beautiful pixel art, strategic grid-based combat, and a heartwarming fantasy story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-master---nijiiro-no-maseki-japan-en-by-sstrans-v050beta-~little-master-iii---jewels-of-the-rainbow-incomplete', 'SNES', 'Little Master - Nijiiro no Maseki (Japan) [En by SSTrans v0.50Beta] (~Little Master III - Jewels of the Rainbow) (Incomplete)', '1994', 'RPG', 'Tokai Engineering', '1', 'Turn-based JRPG translated (incomplete)', 'Tactical turn-based RPG with a partial English fan translation.', 'Command your units with English menus and dialogue.', 'Play Little Master III in English on the Super Nintendo.', 'The SSTrans translation helps navigate the tactical menus of this 16-bit gem. Experience the refined strategy and charming animations in your own language.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('live-a-live-japan', 'SNES', 'Live A Live (Japan)', '1994', 'RPG', 'Square', '1', 'Turn-based JRPG', 'Anthology-style JRPG with seven unique time periods and mechanics.', 'Complete each era to unlock the final showdown against Odio.', 'Play the legendary Live A Live on the Super Famicom.', 'A 16-bit masterpiece by Square. Each chapter features different protagonists and gameplay styles—from stealth in Edo Japan to turn-based survival in deep space.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('live-a-live-japan-en-by-aeon-genesis-v20deluxe', 'SNES', 'Live A Live (Japan) [En by Aeon Genesis v2.0Deluxe]', '1994', 'RPG', 'Square', '1', 'Turn-based JRPG translated', 'Anthology-style JRPG with a full English fan translation.', 'Experience Square''s multi-era epic with English text.', 'Play Live A Live in English on the Super Nintendo.', 'The Aeon Genesis translation makes this unique 16-bit JRPG fully accessible. Follow the intertwined fates of heroes across time in a story-rich adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lobo-usa-proto', 'SNES', 'Lobo (USA) (Proto)', '1996', 'Action', 'Ocean', '1', 'Action platformer', 'One-on-one fighting game based on the DC Comics anti-hero.', 'Win the intergalactic tournament as the Main Man.', 'Check out the unreleased Lobo Proto for the SNES.', 'A rare 16-bit prototype. Features the cigar-chomping bounty hunter in a gritty fighter with massive sprites and over-the-top special moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lock-on-usa', 'SNES', 'Lock On (USA)', '1994', 'Simulation', 'Vic Tokai', '1', 'Combat flight sim', 'Pseudo-3D flight combat simulation using Mode 7.', 'Engage in aerial dogfights and destroy ground targets.', 'Take to the skies in Lock On for the Super Nintendo.', 'Known as Super Air Infernos. Features intense 16-bit cockpit-view combat. Use missiles and cannons to complete missions across diverse 3D-scaling environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lode-runner-twin---justy-to-liberty-no-daibouken-japan', 'SNES', 'Lode Runner Twin - Justy to Liberty no Daibouken (Japan)', '1994', 'Action', 'Irem', '2', 'Action platformer', 'Puzzle-platformer with co-op focus and level editing.', 'Collect all the gold and find the exit without getting caught.', 'Experience Lode Runner Twin on the Super Famicom.', 'A vibrant 16-bit update to the classic formula. Features two-player cooperative play, colorful new environments, and a deep level editor to create your own puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lodoss-tou-senki-japan', 'SNES', 'Lodoss-tou Senki (Japan)', '1995', 'RPG', 'Angel', '1', 'Tactical JRPG', 'Tactical turn-based RPG based on the iconic fantasy anime.', 'Lead Parn and his companions to save the island of Lodoss.', 'Explore Record of Lodoss War on the Super Famicom.', 'Features deep 16-bit tactical combat and a story faithful to the "Gray Witch" arc. Manage your party''s skills and equipment in a classic high-fantasy setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lodoss-tou-senki-japan-en-by-lnf-v090-~record-of-lodoss-war-incomplete', 'SNES', 'Lodoss-tou Senki (Japan) [En by LNF v0.90] (~Record of Lodoss War) (Incomplete)', '1995', 'RPG', 'Angel', '1', 'Tactical JRPG translated (incomplete)', 'Tactical turn-based RPG with a partial English fan translation.', 'Experience the Lodoss war chronicles with English text.', 'Play Record of Lodoss War in English on the SNES.', 'The LNF translation allows you to navigate the tactical menus and core story of this 16-bit JRPG. Lead the heroes of light through strategic grid-based battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('logos-panic-goaisatsu-japan', 'SNES', 'Logos Panic Goaisatsu (Japan)', '1993', 'Action', 'Teichiku', '2', 'Arcade action', 'Unique word-based puzzle game with a Japanese aesthetic.', 'Link characters and words together to clear the board.', 'Solve the unique Logos Panic on the Super Famicom.', 'A rare 16-bit linguistic puzzler. Challenge your knowledge of Japanese characters and logic in a series of increasingly difficult word-matching stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('looney-tunes-b-ball-usa', 'SNES', 'Looney Tunes B-Ball (USA)', '1995', 'Sports', 'Konami', '4', 'Basketball arcade', 'Arcade-style 2-on-2 basketball featuring Looney Tunes characters.', 'Outscore your opponents using wacky power-ups and dunks.', 'Play Looney Tunes B-Ball for the Super Nintendo.', 'A high-energy 16-bit sports game. Use characters like Bugs Bunny and Daffy Duck to execute "Acme" powered special moves in fast-paced arcade matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('looney-tunes-basketball-europe', 'SNES', 'Looney Tunes Basketball (Europe)', '1995', 'Sports', 'Konami', '4', 'Basketball arcade', 'Arcade-style 2-on-2 basketball featuring Looney Tunes characters.', 'Win the tournament in the localized European version.', 'Experience Looney Tunes Basketball on the SNES.', 'The European release of the cartoon sports hit. Features the same addictive 16-bit gameplay, colorful animations, and hilarious character-specific special shots.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lord-monarch-japan', 'SNES', 'Lord Monarch (Japan)', '1991', 'Strategy', 'SystemSoft', '1', 'Strategy simulation', 'Strategic real-time simulation with a focus on resource management.', 'Expand your territory and defeat rival lords in a fantasy world.', 'Master strategy in Lord Monarch for the Super Famicom.', 'Developed by Nihon Falcom. A fast-paced 16-bit strategy game where you manage troop growth and bridge construction to outmaneuver your opponents.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lost-vikings-ii-the-europe-enfrde', 'SNES', 'Lost Vikings II, The (Europe) (En,Fr,De)', '1997', 'Puzzle', 'Blizzard', '2', 'Puzzle platformer', 'Puzzle-platformer sequel with three new viking abilities.', 'Guide the vikings back home through time and space.', 'Play The Lost Vikings II for the Super Nintendo.', 'Erik, Olaf, and Baleog return with 16-bit cybernetic upgrades. Features complex cooperative puzzles that require switching between all three characters to survive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lost-vikings-ii-the-usa', 'SNES', 'Lost Vikings II, The (USA)', '1997', 'Puzzle', 'Blizzard', '2', 'Puzzle platformer', 'Puzzle-platformer sequel with three new viking abilities.', 'Guide the trio through hazardous levels in North America.', 'Experience The Lost Vikings II on the SNES.', 'Master the new 16-bit mechanics like Olaf''s shrinking and Erik''s double jump. A witty and challenging adventure that rewards creative problem-solving.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lost-vikings-the-europe', 'SNES', 'Lost Vikings, The (Europe)', '1993', 'Puzzle', 'Blizzard', '2', 'Puzzle platformer', 'Cooperative puzzle-platformer featuring three unique vikings.', 'Use teamwork to navigate dangerous worlds and return home.', 'Join the adventure in The Lost Vikings for the SNES.', 'A 16-bit classic by Blizzard. Each viking has a specific skill (jump, shield, or sword). You must keep all three alive to progress through clever environmental puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lost-vikings-the-france-enfr', 'SNES', 'Lost Vikings, The (France) (En,Fr)', '1993', 'Puzzle', 'Blizzard', '2', 'Puzzle platformer', 'Cooperative puzzle-platformer with localized French text.', 'Guide the vikings to safety in the French version.', 'Jouez à The Lost Vikings en français sur le SNES.', 'The complete 16-bit puzzle-adventure with localized menus and dialogue. Experience the humor and challenge of the viking trio in French.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lost-vikings-the-germany', 'SNES', 'Lost Vikings, The (Germany)', '1993', 'Puzzle', 'Blizzard', '2', 'Puzzle platformer', 'Cooperative puzzle-platformer with localized German text.', 'Guide the vikings to safety in the German version.', 'Spielen Sie The Lost Vikings auf Deutsch für das SNES.', 'The complete 16-bit puzzle-adventure with localized German text. Solve complex logic puzzles using the unique skills of Erik, Baleog, and Olaf.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lost-vikings-the-spain', 'SNES', 'Lost Vikings, The (Spain)', '1993', 'Puzzle', 'Blizzard', '2', 'Puzzle platformer', 'Cooperative puzzle-platformer with localized Spanish text.', 'Guide the vikings to safety in the Spanish version.', 'Juega a The Lost Vikings en español para el SNES.', 'The complete 16-bit puzzle-adventure with localized Spanish text. One of the most creative and beloved strategy-platformers on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lost-vikings-the-usa', 'SNES', 'Lost Vikings, The (USA)', '1993', 'Puzzle', 'Blizzard', '2', 'Puzzle platformer', 'Cooperative puzzle-platformer featuring three unique vikings.', 'Use teamwork to navigate dangerous worlds and return home.', 'Join the adventure in The Lost Vikings for the SNES.', 'Master the 16-bit cooperation mechanics. Each level is a complex logic puzzle that tests your ability to coordinate Baleog''s combat, Olaf''s defense, and Erik''s speed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lost-vikings-the-usa-beta', 'SNES', 'Lost Vikings, The (USA) (Beta)', '1993', 'Puzzle', 'Blizzard', '2', 'Puzzle platformer', 'Cooperative puzzle-platformer featuring three unique vikings.', 'Explore early puzzle designs and viking mechanics.', 'Check out The Lost Vikings Beta for the SNES.', 'A pre-release 16-bit development build. Witness the fine-tuning of the character-switching system and early level layouts for the iconic trio.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lothar-matthaus-super-soccer-germany', 'SNES', 'Lothar Matthaus Super Soccer (Germany)', '1994', 'Sports', 'Capcom', '2', 'Soccer simulation', 'Realistic soccer simulation endorsed by the German legend.', 'Win the international cup in this specialized German sim.', 'Kick off in Lothar Matthaus Super Soccer for SNES.', 'Features deep 16-bit management options and a simulation-focused match engine. Play as or against the famous German captain in various tournament modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('love-quest-japan', 'SNES', 'Love Quest (Japan)', '1994', 'Adventure', 'Towachiki', '1', 'Romance adventure', 'Surreal JRPG with a focus on dating and modern urban life.', 'Navigate the complexities of love and combat in Tokyo.', 'Discover the unique Love Quest on the Super Famicom.', 'A bizarre 16-bit RPG where you "battle" using dialogue and charm. Explore a modern Japanese setting with a humorous and often adult-oriented narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lucky-luke-europe-enfrdees', 'SNES', 'Lucky Luke (Europe) (En,Fr,De,Es)', '1996', 'Action', 'Infogrames', '1', 'Action platformer', 'Side-scrolling action-platformer based on the famous comic.', 'Chase down the Daltons and restore order to the wild west.', 'Join the adventure in Lucky Luke for the SNES.', 'Features beautiful 16-bit pixel art faithful to the comics. Use Luke''s quick-draw skills to navigate through desert, town, and train levels in this polished adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lufia-europe', 'SNES', 'Lufia (Europe)', '1993', 'RPG', 'Neverland', '1', 'Turn-based JRPG', 'Classic turn-based RPG with a focus on a legendary war.', 'Defeat the four Sinistrals and save the world from destruction.', 'Experience the epic Lufia on the Super Nintendo.', 'The first entry in the celebrated 16-bit RPG series. Lead Maxim''s descendants through a massive world filled with random encounters, deep lore, and strategic turn-based combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lufia-germany', 'SNES', 'Lufia (Germany)', '1993', 'RPG', 'Neverland', '1', 'Turn-based JRPG', 'Classic turn-based RPG with localized German text.', 'Defeat the Sinistrals in the German version of the game.', 'Spielen Sie Lufia auf Deutsch für das SNES.', 'The complete 16-bit adventure with localized German dialogue. Experience the emotional narrative and classic JRPG mechanics in your own language.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lufia-netherlands', 'SNES', 'Lufia (Netherlands)', '1993', 'RPG', 'Neverland', '1', 'Turn-based JRPG', 'Classic turn-based RPG with localized Dutch text.', 'Defeat the Sinistrals in the Dutch version of the game.', 'Speel Lufia in het Nederlands op de SNES.', 'A rare localized 16-bit RPG experience for the Dutch market. Follow the journey of the heroes as they face the threat of the Fortress of Doom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lufia-spain', 'SNES', 'Lufia (Spain)', '1993', 'RPG', 'Neverland', '1', 'Turn-based JRPG', 'Classic turn-based RPG with localized Spanish text.', 'Derrota a los Siniestros en la versión española.', 'Juega Lufia en español para la Super Nintendo.', 'The full 16-bit JRPG experience with localized Spanish text. Navigate through dangerous dungeons and master the turn-based battle system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lufia-&-the-fortress-of-doom-usa', 'SNES', 'Lufia & The Fortress of Doom (USA)', '1993', 'RPG', 'Neverland', '1', 'Turn-based JRPG', 'Classic turn-based RPG with a focus on a legendary war.', 'Defeat the four Sinistrals and save the world from destruction.', 'Experience Lufia & The Fortress of Doom on the SNES.', 'A foundational 16-bit RPG. Features a traditional party system, a vast world map, and a story centered on the struggle against god-like beings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lufia-&-the-fortress-of-doom-usa-hack-by-d-v10-uncensored-edition', 'SNES', 'Lufia & The Fortress of Doom (USA) [Hack by D v1.0] (Uncensored Edition)', '1993', 'RPG', 'Neverland', '1', 'Turn-based JRPG hack (uncensored)', 'Classic turn-based RPG restored to its original Japanese state.', 'Experience the uncensored journey against the Sinistrals.', 'Play Lufia (Uncensored Edition) on the SNES.', 'A 16-bit fan restoration that brings back original Japanese sprites, dialogue, and references that were altered for the Western release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lufia-ii---rise-of-the-sinistrals-usa', 'SNES', 'Lufia II - Rise of the Sinistrals (USA)', '1995', 'RPG', 'Neverland', '1', 'Turn-based JRPG', 'Masterpiece JRPG featuring environmental puzzles and monster taming.', 'Stop the Sinistrals in this epic prequel to the first game.', 'Play the legendary Lufia II on the Super Nintendo.', 'Often called the best RPG on the system. Combines 16-bit turn-based combat with Zelda-style dungeon puzzles and an addictive "Ancient Cave" roguelike mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lufia-ii---rise-of-the-sinistrals-usa-hack-by-relnqshd-v10beta-fixxxer-deluxe', 'SNES', 'Lufia II - Rise of the Sinistrals (USA) [Hack by Relnqshd v1.0Beta] (Fixxxer Deluxe)', '1995', 'RPG', 'Neverland', '1', 'Turn-based JRPG hack', 'Masterpiece JRPG with numerous bug fixes and improvements.', 'Experience Lufia II with optimized gameplay and logic.', 'Play Lufia II Fixxxer Deluxe on the SNES.', 'A 16-bit fan enhancement that fixes original game-breaking bugs, improves the script, and balances the monster-taming mechanics for the definitive experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('luigi-and-the-final-year-by-karen13505', 'SNES', 'Luigi and the Final Year by karen13505', '2023', 'Platformer', 'Homebrew', '1', 'Fan-made platformer', 'Fan-made Super Mario World hack starring Luigi.', 'Guide Luigi through a challenging new set of custom levels.', 'Play Luigi and the Final Year on the SNES.', 'A creative 16-bit romhack featuring custom level designs, new music, and a high difficulty curve that tests your platforming skills with Luigi''s unique physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('luigis-adventure-ose', 'SNES', 'Luigi''s Adventure OSE', '2022', 'Platformer', 'Homebrew', '1', 'Fan-made platformer', 'Comprehensive fan-made platformer adventure starring Luigi.', 'Explore a massive new world with unique platforming mechanics.', 'Experience Luigi''s Adventure OSE on the Super Nintendo.', 'One of the most polished 16-bit SMW hacks. Features custom bosses, power-ups, and intricate level design that rivals official Nintendo releases.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lupin-sansei---densetsu-no-hihou-o-oe!-japan', 'SNES', 'Lupin Sansei - Densetsu no Hihou o Oe! (Japan)', '1994', 'Adventure', 'Asmik', '1', 'Action adventure', 'Adventure game based on the legendary gentleman thief anime.', 'Solve the mystery of the legendary treasure across Japan.', 'Join the heist in Lupin Sansei on the Super Famicom.', 'Features a unique 16-bit mix of point-and-click investigation and action mini-games. Follow Lupin, Jigen, and Goemon in a cinematic and humorous narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-94-europe', 'SNES', 'Madden NFL ''94 (Europe)', '1993', 'Sports', 'EA Sports', '2', 'American football', 'Pro football simulation with 1994 season rosters and data.', 'Win the Super Bowl with updated teams and playbooks.', 'Kick off the action in Madden NFL ''94 on SNES.', 'Features the "Flip" play mechanic and improved 16-bit passing controls. A landmark sports title that defined the era of professional football gaming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-94-usa', 'SNES', 'Madden NFL ''94 (USA)', '1993', 'Sports', 'EA Sports', '2', 'American football', 'Pro football simulation with 1994 season rosters and data.', 'Lead your favorite NFL team to the championship.', 'Experience Madden NFL ''94 on the Super Nintendo.', 'The first entry to feature the official NFL team names and logos. Offers a deep 16-bit simulation of professional football strategy and action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-95-europe', 'SNES', 'Madden NFL ''95 (Europe)', '1994', 'Sports', 'EA Sports', '2', 'American football', 'Pro football simulation with 1995 season rosters and data.', 'Master the field and claim the ring in the ''95 season.', 'Play Madden NFL ''95 for the Super Nintendo.', 'Introduces a more fluid 16-bit animation system and removes the passing windows for a more realistic and challenging gameplay experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-95-usa', 'SNES', 'Madden NFL ''95 (USA)', '1994', 'Sports', 'EA Sports', '2', 'American football', 'Pro football simulation with 1995 season rosters and data.', 'Win the Super Bowl in the localized European version.', 'Experience Madden NFL ''95 on the SNES.', 'Features the complete 1995 NFL season data. Master the "prevent" defense and the "no-huddle" offense in this 16-bit sports classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-96-usa', 'SNES', 'Madden NFL ''96 (USA)', '1995', 'Sports', 'EA Sports', '2', 'American football', 'Pro football simulation with 1996 season rosters and data.', 'Dominate the gridiron with the updated ''96 team data.', 'Play Madden NFL ''96 for the Super Nintendo.', 'Features the debut of the "Create-A-Player" mode. This 16-bit entry offers deeper customization and refined AI for more competitive matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-96-usa-sample', 'SNES', 'Madden NFL ''96 (USA) (Sample)', '1995', 'Sports', 'EA Sports', '2', 'American football (sample)', 'Pro football simulation pre-release build.', 'Explore the early gameplay and rosters of the ''96 edition.', 'Check out the Madden NFL ''96 Sample on SNES.', 'A rare 16-bit development sample. Witness the tuning of the player physics and the early implementation of the season management menus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-97-usa', 'SNES', 'Madden NFL ''97 (USA)', '1996', 'Sports', 'EA Sports', '2', 'American football', 'Pro football simulation with 1997 season rosters and data.', 'Lead your team to glory in this late-gen football sim.', 'Experience Madden NFL ''97 for the Super Nintendo.', 'Features improved 16-bit graphics and more complex playbooks. A polished entry that maximizes the SNES hardware for realistic football action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-98-usa', 'SNES', 'Madden NFL ''98 (USA)', '1997', 'Sports', 'EA Sports', '2', 'American football', 'The final 16-bit entry in the legendary Madden series.', 'Claim the ultimate victory in the definitive SNES edition.', 'Play the final Madden NFL ''98 on the Super Nintendo.', 'The most refined 16-bit Madden experience. Features the complete 1998 rosters and the most stable gameplay engine of the entire SNES run.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madou-monogatari---hanamaru-daiyouchienji-japan', 'SNES', 'Madou Monogatari - Hanamaru Daiyouchienji (Japan)', '1993', 'RPG', 'Compile', '1', 'Dungeon crawler JRPG', 'First-person dungeon crawler RPG set in the Puyo Puyo world.', 'Help Arle Nadja pass her final kindergarten exam.', 'Explore Madou Monogatari on the Super Famicom.', 'A charming 16-bit JRPG. Features unique "no-stat" combat where you judge health by character expressions and beautiful, vibrant first-person dungeons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madou-monogatari---hanamaru-daiyouchienji-japan-en-by-aeon-genesis-v101-~madou-monogatari---big-kindergarten-kids', 'SNES', 'Madou Monogatari - Hanamaru Daiyouchienji (Japan) [En by Aeon Genesis v1.01] (~Madou Monogatari - Big Kindergarten Kids)', '1993', 'RPG', 'Compile', '1', 'Dungeon crawler JRPG translated', 'First-person dungeon crawler RPG with an English fan translation.', 'Experience Arle''s cute adventure with English text.', 'Play Madou Monogatari in English on the SNES.', 'The Aeon Genesis translation makes this 16-bit dungeon crawler accessible. Follow the lighthearted story and master the magic system in your own language.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maerchen-adventure-cotton-100%-japan', 'SNES', 'Maerchen Adventure Cotton 100% (Japan)', '1994', 'Action', 'Success', '2', 'Run-and-gun platformer', 'Cute-em-up vertical shooter featuring the witch Cotton.', 'Recover the legendary Willow candy by blasting enemies.', 'Experience Cotton 100% on the Super Famicom.', 'A visually stunning 16-bit shooter. Features vibrant pastel colors, adorable character designs, and a high-energy soundtrack typical of the "cute-em-up" genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maga-man-7-player-update', 'SNES', 'Maga Man 7 Player Update', '2021', 'Action', 'Hack', '2', 'Hack update (7-player)', 'Fan-made update for Mega Man 7 featuring character swaps.', 'Play through Mega Man 7 with a second player or new moves.', 'Play Mega Man 7 Player Update on the SNES.', 'A creative 16-bit mod that enhances the original game. Features the ability to play as Protoman or other characters with modified abilities and palettes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-boy-europe', 'SNES', 'Magic Boy (Europe)', '1993', 'Action', 'Naxat Soft', '2', 'Action platformer', 'Side-scrolling platformer featuring a young wizard.', 'Clean up the world by capturing monsters in your magic bag.', 'Join the quest in Magic Boy for the Super Nintendo.', 'A colorful 16-bit platformer. Use your magic to shrink enemies and trap them. Travel through diverse worlds, from the sea to the desert, in this polished adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-boy-europe-beta', 'SNES', 'Magic Boy (Europe) (Beta)', '1993', 'Action', 'Naxat Soft', '2', 'Action platformer (beta)', 'Side-scrolling platformer featuring a young wizard.', 'Explore early level designs and monster-catching mechanics.', 'Check out the Magic Boy Beta for the SNES.', 'A pre-release 16-bit development build. Witness the fine-tuning of the character''s movement and the evolution of the vibrant environmental art.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-boy-usa', 'SNES', 'Magic Boy (USA)', '1993', 'Action', 'Naxat Soft', '2', 'Action platformer', 'Side-scrolling platformer featuring a young wizard.', 'Clean up the world by capturing monsters in your magic bag.', 'Join the quest in Magic Boy for the Super Nintendo.', 'Master the use of magical power-ups. A charming and challenging 16-bit platformer that rewards exploration and careful enemy management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-johnson-no-super-slam-dunk-japan', 'SNES', 'Magic Johnson no Super Slam Dunk (Japan)', '1994', 'Sports', 'NAMCO', '2', 'Basketball', 'Professional basketball simulation featuring Magic Johnson.', 'Win the world championship with expert coaching and play.', 'Experience Super Slam Dunk on the Super Famicom.', 'Features 16-bit Mode 7 court rotation and large, digitized player sprites. A technical sports title that focuses on the fundamentals of professional basketball.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-knight-rayearth-japan', 'SNES', 'Magic Knight Rayearth (Japan)', '1995', 'RPG', 'Tom Create', '1', 'Action RPG', 'Action-RPG based on the famous CLAMP anime and manga.', 'Save the world of Cephiro as the three legendary knights.', 'Experience Magic Knight Rayearth on Super Famicom.', 'A beautiful 16-bit JRPG. Features large, detailed character sprites and a combat system that blends traditional turn-based play with cinematic special attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-knight-rayearth-japan-en-by-lnf+rpge-v101', 'SNES', 'Magic Knight Rayearth (Japan) [En by LNF+RPGe v1.01]', '1995', 'RPG', 'Tom Create', '1', 'Action RPG', 'Action-RPG based on the famous anime with English text.', 'Follow the epic CLAMP story with a full English translation.', 'Play Magic Knight Rayearth in English on the SNES.', 'The RPGe translation allows fans to enjoy the emotional 16-bit narrative of Hikaru, Umi, and Fuu. A must-play for fans of the series and high-quality JRPGs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-sword-europe', 'SNES', 'Magic Sword (Europe)', '1995', 'Action', 'Capcom', '2', 'Arcade Action', 'Side-scrolling hack-and-slash with a massive tower climb.', 'Defeat Drokmar at the top of the 50-floor tower.', 'Climb the tower in Magic Sword for the SNES.', 'A 16-bit arcade port where you fight through 50 floors. Rescue allies like Ninjas and Wizards who fight by your side. Features massive bosses and a great variety of power-ups.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-sword-japan', 'SNES', 'Magic Sword (Japan)', '1995', 'Action', 'Capcom', '2', 'Arcade Action', 'Side-scrolling hack-and-slash with a massive tower climb.', 'Reach the summit and destroy the Black Orb.', 'Play the original Magic Sword on the Super Famicom.', 'The foundational 16-bit Japanese release. Known for its fast-paced action and the unique partner system that allows for different combat strategies on every floor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-sword-usa', 'SNES', 'Magic Sword (USA)', '1995', 'Action', 'Capcom', '2', 'Arcade Action', 'Side-scrolling hack-and-slash with a massive tower climb.', 'Defeat the dark forces and save the world.', 'Master the blade in Magic Sword for the SNES.', 'Experience the high-octane 16-bit fantasy brawler. Use magical swords and shields to survive waves of skeletons, chimeras, and dragons in this Capcom classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-drop-japan', 'SNES', 'Magical Drop (Japan)', '1995', 'Puzzle', 'Data East', '2', 'Competitive Puzzle', 'Fast-paced competitive match-3 puzzle game.', 'Clear the screen and defeat your opponent in a puzzle duel.', 'Experience the addictive Magical Drop on Super Famicom.', 'The first 16-bit entry in the legendary series. Use the "clown" to grab and throw colored spheres to create chains. A high-speed test of reflexes and logic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-drop-japan-en-by-aeon-genesis-v095', 'SNES', 'Magical Drop (Japan) [En by Aeon Genesis v0.95]', '1995', 'Puzzle', 'Data East', '2', 'Competitive Puzzle', 'Fast-paced competitive match-3 puzzle game with English text.', 'Master the puzzle chains with a full English translation.', 'Play Magical Drop in English on the Super Nintendo.', 'The Aeon Genesis translation makes the character interactions and menus accessible. Experience the frantic 16-bit puzzle action in your own language.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-drop-2-japan', 'SNES', 'Magical Drop 2 (Japan)', '1996', 'Puzzle', 'Data East', '2', 'Competitive Puzzle', 'Frantic puzzle sequel with new characters and refined mechanics.', 'Dominate the puzzle tournament in this polished sequel.', 'Play the superior Magical Drop 2 on the Super Famicom.', 'Features much faster gameplay, better graphics, and a more balanced competitive mode. One of the best 16-bit "versus" puzzle games ever made.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-popn-japan', 'SNES', 'Magical Pop''n (Japan)', '1995', 'Action', 'Polestar', '1', 'Action Platformer', 'High-energy action-platformer with a focus on agility.', 'Defeat the demon king and save the kingdom as the princess.', 'Discover the rare Magical Pop''n on Super Famicom.', 'Control Princess Pop''n in this fluid 16-bit adventure. Use a grappling hook, magic spells, and agile combat to navigate through colorful, Metroidvania-lite levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-popn-japan-en-by-aeon-genesis-v101', 'SNES', 'Magical Pop''n (Japan) [En by Aeon Genesis v1.01]', '1995', 'Action', 'Polestar', '1', 'Action Platformer', 'High-energy action-platformer with a full English translation.', 'Experience Pop''n''s magical adventure with English text.', 'Play Magical Pop''n in English on the Super Nintendo.', 'The Aeon Genesis translation allows you to follow the charming story and voice acting. A top-tier 16-bit platformer known for its responsive controls and vibrant art.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-quest-starring-mickey-mouse-the-europe', 'SNES', 'Magical Quest Starring Mickey Mouse, The (Europe)', '1994', 'Platformer', 'Capcom', '2', 'Side-scrolling Platformer', 'Disney platformer featuring an iconic costume-change mechanic.', 'Rescue Pluto and defeat Emperor Pete.', 'Join the adventure in The Magical Quest for the SNES.', 'A Capcom masterpiece. Mickey uses different outfits—like a Fireman or a Wizard—each granting unique 16-bit powers to solve puzzles and defeat bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-quest-starring-mickey-mouse-the-europe-rev-a', 'SNES', 'Magical Quest Starring Mickey Mouse, The (Europe) (Rev A)', '1994', 'Platformer', 'Capcom', '2', 'Side-scrolling Platformer', 'Disney platformer featuring an iconic costume-change mechanic.', 'Complete Mickey''s journey in this refined European revision.', 'Play The Magical Quest (Rev A) on the Super Nintendo.', 'An updated 16-bit European version that fixes minor graphical glitches and improves the stability of the costume-switching animations for a smoother experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-quest-starring-mickey-mouse-the-germany', 'SNES', 'Magical Quest Starring Mickey Mouse, The (Germany)', '1994', 'Platformer', 'Capcom', '2', 'Side-scrolling Platformer', 'Disney platformer featuring an iconic costume-change mechanic.', 'Save Pluto in the localized German version.', 'Spielen Sie Mickey''s Magical Quest auf Deutsch für das SNES.', 'The complete 16-bit Disney adventure with localized German text. Master the magical costumes and explore the vibrant world of the sorcerer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-quest-starring-mickey-mouse-the-germany-rev-a', 'SNES', 'Magical Quest Starring Mickey Mouse, The (Germany) (Rev A)', '1994', 'Platformer', 'Capcom', '2', 'Side-scrolling Platformer', 'Disney platformer featuring an iconic costume-change mechanic.', 'Save Pluto in this refined German revision.', 'Play the polished Magical Quest (Rev A) in German.', 'An updated 16-bit German revision with minor text corrections and optimized performance during the game''s more intense boss encounters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-quest-starring-mickey-mouse-the-italy', 'SNES', 'Magical Quest Starring Mickey Mouse, The (Italy)', '1994', 'Platformer', 'Capcom', '2', 'Side-scrolling Platformer', 'Disney platformer featuring an iconic costume-change mechanic.', 'Rescue Pluto in the localized Italian version.', 'Gioca a The Magical Quest in italiano sulla Super Nintendo.', 'The complete 16-bit Disney adventure with localized Italian text. One of the most beautiful and well-designed platformers of the 16-bit era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-quest-starring-mickey-mouse-the-usa', 'SNES', 'Magical Quest Starring Mickey Mouse, The (USA)', '1994', 'Platformer', 'Capcom', '2', 'Side-scrolling Platformer', 'Disney platformer featuring an iconic costume-change mechanic.', 'Rescue Pluto and defeat Emperor Pete.', 'Join the adventure in The Magical Quest for the SNES.', 'A 16-bit classic known for its lush graphics and creative level design. Switch between costumes to navigate the forest, mountains, and Pete''s castle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-quest-starring-mickey-mouse-the-usa-beta', 'SNES', 'Magical Quest Starring Mickey Mouse, The (USA) (Beta)', '1994', 'Platformer', 'Capcom', '2', 'Side-scrolling Platformer', 'Disney platformer featuring an iconic costume-change mechanic.', 'Explore early costume powers and level designs.', 'Check out The Magical Quest (Beta) for the SNES.', 'A pre-release 16-bit development build. Witness the fine-tuning of Mickey''s movement and the evolution of the iconic magical costumes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-taruruuto-kun---magic-adventure-japan', 'SNES', 'Magical Taruruuto-kun - Magic Adventure (Japan)', '1995', 'Action', 'Tose', '1', 'Action Platformer', 'Action-platformer based on the popular magical boy anime.', 'Defeat the wicked sorcerers and protect the world.', 'Join the fun in Magical Taruruuto-kun on Super Famicom.', 'A colorful 16-bit title featuring the mascot Taruruuto. Use magic and item transformations to solve puzzles and fight enemies in a vibrant, anime-inspired world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magna-braban---henreki-no-yuusha-japan', 'SNES', 'Magna Braban - Henreki no Yuusha (Japan)', '1995', 'RPG', 'Lenar', '1', 'Tactical RPG', 'Humorous JRPG that parodies traditional fantasy tropes.', 'Lead a clumsy hero on an accidental quest for glory.', 'Experience the quirky Magna Braban on Super Famicom.', 'A unique 16-bit RPG where you fight using an "automatic" battle system that requires tactical preparation. Features a funny story and beautiful pixel art.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magna-braban---henreki-no-yuusha-japan-en-by-kingmike-v10-~magna-braban---the-wandering-hero', 'SNES', 'Magna Braban - Henreki no Yuusha (Japan) [En by KingMike v1.0] (~Magna Braban - The Wandering Hero)', '1995', 'RPG', 'Lenar', '1', 'Tactical RPG', 'Humorous JRPG with a full English fan translation.', 'Follow the wandering hero''s comedy adventure in English.', 'Play Magna Braban in English on the Super Nintendo.', 'The KingMike translation makes this 16-bit parody JRPG accessible. Enjoy the witty dialogue and unique tactical combat in your own language.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-club-japan', 'SNES', 'Mahjong Club (Japan)', '1992', 'Tabletop', 'Nichibutsu', '2', 'Mahjong', 'Traditional Mahjong simulation with a focus on club play.', 'Defeat the club champions and master Mahjong strategy.', 'Play Mahjong Club on the Super Famicom.', 'A polished 16-bit Mahjong title featuring realistic AI opponents and a variety of play styles for fans of the traditional Japanese board game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-gokuu-tenjiku-japan', 'SNES', 'Mahjong Gokuu Tenjiku (Japan)', '1994', 'Tabletop', 'Nichibutsu', '2', 'Mahjong', 'Fantasy-themed Mahjong simulation based on the Journey to the West.', 'Defeat the monkey king and his rivals at the Mahjong table.', 'Experience Mahjong Gokuu Tenjiku on Super Famicom.', 'A creative 16-bit blend of Mahjong and mythology. Features characters from the classic legend and a high-quality presentation with detailed sprites.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-hanjouki-japan', 'SNES', 'Mahjong Hanjouki (Japan)', '1993', 'Tabletop', 'Nichibutsu', '2', 'Mahjong', 'Business-themed Mahjong simulation focusing on prosperity.', 'Win enough matches to grow your virtual Mahjong parlor.', 'Play Mahjong Hanjouki on the Super Famicom.', 'Combines 16-bit Mahjong gameplay with light management elements. Defeat diverse opponents to attract more customers to your business.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-sengoku-monogatari-japan', 'SNES', 'Mahjong Sengoku Monogatari (Japan)', '1992', 'Tabletop', 'Nichibutsu', '2', 'Mahjong', 'Historical Mahjong simulation set during the Warring States period.', 'Unify Japan through the power of Mahjong strategy.', 'Experience Mahjong Sengoku Monogatari on Super Famicom.', 'A unique 16-bit tactical game where Mahjong matches replace battles. Conquer provinces by defeating legendary warlords at the table.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-taikai-ii-japan', 'SNES', 'Mahjong Taikai II (Japan)', '1995', 'Tabletop', 'Nichibutsu', '2', 'Mahjong', 'Professional Mahjong simulation sequel from Koei.', 'Compete in international tournaments and win the grand prize.', 'Master the tiles in Mahjong Taikai II on Super Famicom.', 'Features deep 16-bit AI and extensive statistical tracking. A serious simulation for Mahjong enthusiasts looking for a professional-grade challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-touhaiden-the-japan', 'SNES', 'Mahjong Touhaiden, The (Japan)', '1994', 'Tabletop', 'Nichibutsu', '2', 'Mahjong', 'Dramatic Mahjong simulation with a focus on competitive intensity.', 'Defeat the rivals in this high-stakes Mahjong story.', 'Play The Mahjong Touhaiden on the Super Famicom.', 'Features a story-driven 16-bit campaign with cinematic character portraits and intense match atmospheres typical of Mahjong manga.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahou-poi-poi-poitto!-japan', 'SNES', 'Mahou Poi Poi Poitto! (Japan)', '1994', 'Action', 'Takara', '2', 'Arcade Action', 'Competitive falling-block puzzle game with a magical theme.', 'Clear the screen by matching icons in this frantic puzzler.', 'Solve the puzzles in Mahou Poi Poi Poitto on SNES.', 'A charming 16-bit puzzle game. Use magical abilities to manipulate the board and send garbage blocks to your opponent''s screen in fast-paced matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahoujin-guruguru-japan', 'SNES', 'Mahoujin Guruguru (Japan)', '1995', 'RPG', 'Enix', '1', 'Comedy RPG', 'Action-RPG with top-down exploration and turn-based battles.', 'Help Nike and Kukuri defeat the Demon King Giri.', 'Join the fun in Mahoujin Guruguru on Super Famicom.', 'Based on the parody manga/anime. A charming 16-bit RPG where you summon magical circles to fight. Features a humorous story and vibrant, colorful world-building.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahoujin-guruguru-2-japan', 'SNES', 'Mahoujin Guruguru 2 (Japan)', '1997', 'RPG', 'Enix', '1', 'Comedy RPG', 'Deeper RPG sequel with improved summon mechanics.', 'Embark on a new magical adventure to save the kingdom.', 'Experience Mahoujin Guruguru 2 on the Super Famicom.', 'Refines the 16-bit magic system and world exploration. Features better animations and a more complex narrative while maintaining the original''s trademark humor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('majin-tensei-japan', 'SNES', 'Majin Tensei (Japan)', '1994', 'Strategy RPG', 'Atlus', '1', 'Tactical RPG', 'Tactical turn-based strategy RPG in the Megami Tensei universe.', 'Recruit demons and defeat the dark forces in a grid-based war.', 'Master strategy in Majin Tensei on the Super Famicom.', 'Combines 16-bit tactical strategy with the famous demon fusion mechanics. Command armies of mythological creatures in a dark, atmospheric sci-fi setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('majin-tensei-japan-rev-a', 'SNES', 'Majin Tensei (Japan) (Rev A)', '1994', 'Strategy RPG', 'Atlus', '1', 'Tactical RPG', 'Tactical turn-based strategy RPG (Updated Revision).', 'Command your demon army in this refined tactical battle.', 'Play the updated Majin Tensei (Rev A) on Super Famicom.', 'A 16-bit revision that balances unit stats and fixes minor AI glitches for a more consistent and fair strategic experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('majin-tensei-japan-rev-b', 'SNES', 'Majin Tensei (Japan) (Rev B)', '1994', 'Strategy RPG', 'Atlus', '1', 'Tactical RPG', 'Tactical turn-based strategy RPG (Final Revision).', 'Achieve victory in the most stable version of the game.', 'Play the polished Majin Tensei (Rev B) on Super Famicom.', 'The definitive 16-bit release of the first entry. Features optimized performance and the final set of balance tweaks for the tactical combat engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('majin-tensei-ii---spiral-nemesis-english', 'SNES', 'Majin Tensei II - Spiral Nemesis (English)', '1995', 'Strategy RPG', 'Atlus', '1', 'Tactical RPG', 'Tactical strategy sequel with a massive English fan translation.', 'Navigate a branching cyberpunk story with full English text.', 'Play Majin Tensei II in English on the Super Nintendo.', 'The Spiral Nemesis translation opens up this deep 16-bit tactical JRPG. Features a dark plot, multiple endings, and a sophisticated demon recruitment system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('majin-tensei-ii---spiral-nemesis-japan', 'SNES', 'Majin Tensei II - Spiral Nemesis (Japan)', '1995', 'Strategy RPG', 'Atlus', '1', 'Tactical RPG', 'Tactical strategy sequel set in a dark cyberpunk future.', 'Determine the fate of Tokyo in this ambitious tactical epic.', 'Experience Majin Tensei II on the Super Famicom.', 'A peak 16-bit strategy title. Features isometric battle maps, an incredible soundtrack, and a complex narrative that changes based on your moral alignment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('majo-tachi-no-nemuri-japan', 'SNES', 'Majo-tachi no Nemuri (Japan)', '1996', 'Adventure', 'Human Entertainment', '1', 'Visual Novel', 'Horror-themed sound novel/visual adventure.', 'Solve the mystery of the witch''s curse in a remote mansion.', 'Survive the mystery in Majo-tachi no Nemuri on SNES.', 'A 16-bit psychological thriller. Use logic and dialogue choices to navigate a branching narrative filled with eerie atmosphere and multiple dark endings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('majuu-ou-japan', 'SNES', 'Majuu Ou (Japan)', '1995', 'Action', 'NCS', '1', 'Dark Action Platformer', 'Gritty side-scrolling action-platformer with transformations.', 'Rescue your family from hell by defeating the King of Demons.', 'Experience the intense Majuu Ou on the Super Famicom.', 'A cult classic 16-bit action game. Transform into different demonic forms to gain unique powers. Known for its dark pixel art and challenging boss fights.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('majuu-ou-japan-en-by-aeon-genesis-v101-~king-of-demons', 'SNES', 'Majuu Ou (Japan) [En by Aeon Genesis v1.01] (~King of Demons)', '1995', 'Action', 'NCS', '1', 'Dark Action Platformer', 'Gritty side-scrolling action-platformer with English text.', 'Destroy the demon lords with a full English translation.', 'Play King of Demons in English on the Super Nintendo.', 'The Aeon Genesis translation allows you to follow the dark story of Abel. A fast-paced 16-bit action title with incredible atmosphere and tight controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maka-maka-japan', 'SNES', 'Maka Maka (Japan)', '1992', 'RPG', 'Office Koukan', '1', 'Story-driven RPG', 'Surreal and humorous turn-based JRPG.', 'Defeat the strange invaders in this wacky fantasy world.', 'Discover the bizarre Maka Maka on the Super Famicom.', 'Known for its unique (and often weird) art style and humor. A 16-bit RPG that doesn''t take itself seriously, offering a memorable and eccentric adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('makeruna!-makendou-japan', 'SNES', 'Makeruna! Makendou (Japan)', '1993', 'Action', 'Takara', '2', 'Action Platformer', 'Side-scrolling action-adventure with a magical school theme.', 'Defeat the underworld monsters using Kendo and magic.', 'Join the fight in Makeruna! Makendou on Super Famicom.', 'Known as Kendo Rage in the West. Control Mai in this colorful 16-bit platformer, using spirit-powered attacks to clear wacky Japanese-inspired stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('makeruna!-makendou-2---kimero!-youkai-souridaijin-japan', 'SNES', 'Makeruna! Makendou 2 - Kimero! Youkai Souridaijin (Japan)', '1994', 'Action', 'Takara', '2', 'Action Platformer', 'One-on-one fighting game featuring a bizarre roster.', 'Win the tournament of the spirits in this fighting sequel.', 'Battle in Makeruna! Makendou 2 on the Super Famicom.', 'Shifts the series to a 2D 16-bit fighter. Features large sprites, crazy special moves, and a vibrant art style that leans into its comedic roots.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('manchester-united-championship-soccer-europe', 'SNES', 'Manchester United Championship Soccer (Europe)', '1994', 'Sports', 'Krass Studios', '2', 'Soccer', 'Realistic soccer simulation featuring the famous club.', 'Lead Manchester United to the top of the league.', 'Kick off in Manchester United Soccer for the SNES.', 'Features deep 16-bit management options and a fast-paced match engine. Play as legendary players and master the tactics of professional football.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('manchester-united-championship-soccer-europe-beta', 'SNES', 'Manchester United Championship Soccer (Europe) (Beta)', '1994', 'Sports', 'Krass Studios', '2', 'Soccer', 'Realistic soccer simulation pre-release build.', 'Test the early pitch physics and team management.', 'Check out the Manchester United Soccer Beta on SNES.', 'A rare 16-bit development build. Witness the fine-tuning of the ball control and the early implementation of the league''s statistical database.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario', 'SNES', 'MARIO', '2020', 'Experimental', 'Homebrew', '1', 'Experimental', 'Experimental romhack or technical demo of Super Mario World.', 'Explore modified Mario levels with new assets.', 'Check out the MARIO technical demo on the SNES.', 'A 16-bit romhack showcasing custom palettes and experimental level designs. Used to test the limits of the SMW engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-&-luigi---mecha-koopa-mayhem-demo-ver121', 'SNES', 'Mario & Luigi - Mecha Koopa Mayhem DEMO ver1.21', '2022', 'Platformer', 'Fan Game', '1', 'Platformer', 'Fan-made technical demo blending Mario and Luigi mechanics.', 'Test the "Mecha Koopa" mechanics in this playable demo.', 'Play the Mecha Koopa Mayhem Demo on the SNES.', 'A creative 16-bit preview of a larger project. Focuses on unique interactions with mechanical enemies and cooperative-style platforming puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-&-luigi:-kola-kingdom-quest', 'SNES', 'Mario & Luigi: Kola Kingdom Quest', '2023', 'Platformer', 'Fan Game', '1', 'Platformer', 'Full-length fan-made Mario adventure with a tropical theme.', 'Explore the Kola Kingdom and defeat Bowser in a new quest.', 'Experience Mario & Luigi: Kola Kingdom Quest on SNES.', 'A high-quality 16-bit romhack featuring custom world maps, new enemies, and intricate level design that captures the spirit of the original games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-and-friends-in:-the-ghosts-gallery', 'SNES', 'Mario and Friends in: The Ghost''s Gallery', '2021', 'Adventure', 'Fan Game', '1', 'Adventure', 'Atmospheric fan-made Mario horror adventure.', 'Navigate a haunted art gallery filled with ghostly threats.', 'Survive The Ghost''s Gallery in this Mario hack.', 'A 16-bit spooky romhack. Features custom music and atmospheric level design that turns the familiar Mario world into a survival-horror experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-eisouoku-~-illusionary-blossom-of-cranium-prayer', 'SNES', 'Mario Eisouoku ~ Illusionary Blossom of Cranium Prayer', '2022', 'Art Game', 'Fan Game', '1', 'Experimental', 'Surreal and abstract fan-made Mario platformer.', 'Navigate through dream-like and often bizarre 16-bit levels.', 'Experience the artistic Mario Eisouoku on the SNES.', 'A visually unique 16-bit romhack that uses custom graphics to create a world unlike any other Mario title, focusing on atmosphere and challenging jumps.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-forever---smw-edition-v16', 'SNES', 'Mario Forever - SMW Edition V1.6', '2019', 'Platformer', 'Fan Game', '1', 'Platformer', 'Comprehensive fan-made remake of Mario Forever.', 'Complete a massive set of levels inspired by the PC hit.', 'Play Mario Forever: SMW Edition on the SNES.', 'A technically impressive 16-bit port of the fan-game "Mario Forever" into the Super Mario World engine. Features dozens of new stages and custom assets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-game-v10', 'SNES', 'Mario Game (V1.0)', '2018', 'Platformer', 'Fan Game', '1', 'Platformer', 'Experimental fan-made platformer project.', 'Test the core platforming engine in this early build.', 'Check out Mario Game V1.0 for the Super Nintendo.', 'A foundational 16-bit romhack used to demonstrate custom physics and sprite behaviors within the Super Mario World framework.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-is-a-drug-addict', 'SNES', 'Mario is a Drug Addict', '2017', 'Experimental', 'Fan Game', '1', 'Dark Humor', 'Satirical and mature-themed Mario romhack.', 'Navigate a dark and parody-filled version of the Mushroom Kingdom.', 'Play the parody Mario is a Drug Addict on the SNES.', 'A humorous and irreverent 16-bit romhack that replaces power-ups and dialogue with adult-oriented jokes and satirical social commentary.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-kart-sx', 'SNES', 'Mario Kart SX', '2021', 'Racing', 'Fan Game', '2', 'Arcade Racing', 'Enhanced fan-made version of Super Mario Kart.', 'Race through new custom tracks with improved speed.', 'Experience Mario Kart SX on the Super Nintendo.', 'A creative 16-bit hack of the original racer. Features entirely new track layouts that challenge even the most veteran Mode 7 racers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-mania', 'SNES', 'Mario Mania', '2020', 'Platformer', 'Fan Game', '1', 'Platformer', 'Collection of modified Mario levels and challenges.', 'Test your skills against a variety of custom 16-bit stages.', 'Challenge yourself in Mario Mania on the SNES.', 'A compilation-style romhack that brings together some of the most creative and difficult fan-made levels from the early 16-bit modding community.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-rescues-4th-of-july', 'SNES', 'Mario Rescues 4th Of July', '2020', 'Platformer', 'Fan Game', '1', 'Holiday Platformer', 'Holiday-themed fan-made platformer adventure.', 'Celebrate Independence Day by rescuing the kingdom in this custom mod.', 'Play Mario Rescues 4th Of July on the SNES.', 'A festive 16-bit romhack featuring patriotic palettes, custom fireworks effects, and new level designs centered around the American holiday.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-rpg-google-translated', 'SNES', 'Mario RPG Google Translated', '2019', 'RPG', 'Fan Hack', '1', 'Comedy RPG', 'Humorous RPG parody with chaotic translated text.', 'Navigate the classic RPG story with intentionally broken translations.', 'Experience Mario RPG Google Translated on the SNES.', 'A hilarious 16-bit mod that runs the original script through multiple layers of machine translation, resulting in absurd and nonsensical dialogue.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-saves-christmas-2021', 'SNES', 'Mario Saves Christmas 2021', '2021', 'Platformer', 'Fan Game', '1', 'Holiday Platformer', 'Winter-themed fan-made platformer adventure.', 'Save the holiday season in this festive winter quest.', 'Play Mario Saves Christmas 2021 on the SNES.', 'A high-quality 16-bit romhack with snow-covered landscapes, custom holiday music, and creative levels designed to capture the Christmas spirit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-saves-easter-2023', 'SNES', 'Mario Saves Easter 2023', '2023', 'Platformer', 'Fan Game', '1', 'Holiday Platformer', 'Spring-themed fan-made platformer adventure.', 'Recover the hidden eggs and save Easter in this custom mod.', 'Experience Mario Saves Easter 2023 on the SNES.', 'A colorful 16-bit romhack featuring springtime aesthetics, custom enemy sprites, and lighthearted level design perfect for the season.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-saves-fermins-birthday', 'SNES', 'Mario Saves Fermin''s Birthday', '2022', 'Platformer', 'Fan Game', '1', 'Comedy Platformer', 'Commemorative fan-made platformer adventure.', 'Complete a special quest to celebrate Fermin''s birthday.', 'Play Mario Saves Fermin''s Birthday on the SNES.', 'A personalized 16-bit romhack featuring inside jokes, custom messages, and creative level layouts designed as a gift for a community member.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-saves-princess-peach', 'SNES', 'Mario Saves Princess Peach', '2018', 'Platformer', 'Fan Game', '1', 'Classic Platformer', 'Classic-style fan-made platformer adventure.', 'Rescue Peach from Bowser''s latest scheme in this custom quest.', 'Join the mission in Mario Saves Princess Peach on SNES.', 'A 16-bit mod that focuses on traditional platforming excellence. Features challenging new worlds and secrets that feel like a lost Mario sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-saves-princess-toadstool-2', 'SNES', 'Mario Saves Princess Toadstool 2', '2019', 'Platformer', 'Fan Game', '1', 'Classic Platformer', 'Classic-style fan-made platformer adventure.', 'Continue the rescue mission in this refined sequel mod.', 'Experience Mario Saves Princess Toadstool 2 on SNES.', 'An expanded 16-bit romhack with improved level design and custom music. Features creative boss fights and a high level of polish for Mario fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-saves-spring-break', 'SNES', 'Mario Saves Spring Break', '2020', 'Platformer', 'Fan Game', '1', 'Holiday Platformer', 'Summer-themed fan-made platformer adventure.', 'Enjoy the vacation vibes while clearing new custom levels.', 'Play Mario Saves Spring Break on the SNES.', 'A beach-themed 16-bit romhack featuring sunny palettes, water-based challenges, and a laid-back atmosphere perfect for a virtual vacation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marios-super-picross-english-translation', 'SNES', 'Mario''s Super Picross English Translation', '1995', 'Puzzle', 'Nintendo', '1', 'Picture Logic Puzzle', 'Picture logic puzzle game with a full English fan translation.', 'Solve 16-bit Nonogram puzzles with Mario and Wario.', 'Play Mario''s Super Picross in English on the SNES.', 'The fan translation makes this addictive logic puzzler accessible. Features hundreds of puzzles that reward patience and deduction with beautiful pixel art.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marisa-and-reimu-vs-c3', 'SNES', 'Marisa And Reimu VS C3', '2017', 'Action', 'Fan Hack', '2', 'Arcade Action', 'Touhou-themed fan-made crossover platformer.', 'Battle through the C3 tournament with Marisa and Reimu.', 'Experience Marisa And Reimu VS C3 on the SNES.', 'A 16-bit crossover mod that brings Touhou Project characters into the Mario engine. Features custom projectile mechanics and unique boss encounters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marisa-and-reimus-hack', 'SNES', 'Marisa And Reimu''s Hack', '2016', 'Action', 'Fan Hack', '2', 'Arcade Action', 'Touhou-themed fan-made platformer adventure.', 'Explore the Gensokyo-inspired world in this custom quest.', 'Play Marisa And Reimu''s Hack on the Super Nintendo.', 'A creative 16-bit romhack featuring custom sprites for the Touhou duo. Navigate through reimagined stages with high-quality music and unique physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marisa-and-reimus-switch-hunt', 'SNES', 'Marisa And Reimu''s Switch Hunt', '2018', 'Action', 'Fan Hack', '2', 'Arcade Action', 'Touhou-themed fan-made platformer adventure.', 'Complete the switch hunt and solve environmental puzzles.', 'Join the Switch Hunt in this Marisa and Reimu mod.', 'A 16-bit romhack focused on exploration and puzzle-solving. Use the unique abilities of the Touhou protagonists to unlock new paths and secrets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mark-davis-the-fishing-master-usa', 'SNES', 'Mark Davis'' The Fishing Master (USA)', '1995', 'Sports', 'Natsume', '1', 'Fishing Simulation', 'Realistic bass fishing simulation featuring Mark Davis.', 'Win the professional fishing circuit and catch legendary bass.', 'Go pro in Mark Davis'' The Fishing Master on SNES.', 'Features a detailed 16-bit underwater view and realistic weather effects. Manage your lures and techniques to climb the pro rankings in this technical sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('markos-magic-football-europe-enfrdees', 'SNES', 'Marko''s Magic Football (Europe) (En,Fr,De,Es)', '1994', 'Sports', 'Domark', '2', 'Soccer', 'Side-scrolling platformer featuring a soccer-playing hero.', 'Stop the corporate takeover using your magical soccer ball.', 'Play Marko''s Magic Football for the Super Nintendo.', 'A vibrant 16-bit title with fluid animations. Use soccer tricks like headers and volleys to defeat enemies and solve environmental puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marmalade-boy-japan', 'SNES', 'Marmalade Boy (Japan)', '1995', 'Adventure', 'Bandai', '1', 'Anime Adventure', 'Dating simulation/adventure based on the popular shoujo manga.', 'Navigate high school romance and find your true love.', 'Experience Marmalade Boy on the Super Famicom.', 'A charming 16-bit visual adventure. Follow Miki''s story, make key dialogue choices, and play mini-games in this faithful adaptation of the hit series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel-super-heroes---war-of-the-gems-europe', 'SNES', 'Marvel Super Heroes - War of the Gems (Europe)', '1996', 'Action', 'Capcom', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up featuring iconic Marvel heroes.', 'Recover the Infinity Gems to stop Thanos and save the universe.', 'Play Marvel Super Heroes: War of the Gems on SNES.', 'A 16-bit Capcom classic. Control Spider-Man, Iron Man, Wolverine, Hulk, and Captain America, each with unique abilities and special moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel-super-heroes---war-of-the-gems-japan', 'SNES', 'Marvel Super Heroes - War of the Gems (Japan)', '1996', 'Action', 'Capcom', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up featuring iconic Marvel heroes.', 'Collect the gems in the original Japanese version.', 'Experience Marvel Super Heroes on the Super Famicom.', 'The foundational 16-bit release. Features impressive character animations and challenging stages set in iconic Marvel locations across the globe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel-super-heroes---war-of-the-gems-usa', 'SNES', 'Marvel Super Heroes - War of the Gems (USA)', '1996', 'Action', 'Capcom', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up featuring iconic Marvel heroes.', 'Recover the Infinity Gems to stop Thanos and save the universe.', 'Play Marvel Super Heroes: War of the Gems on SNES.', 'Master the 16-bit combat and gem-power system. A high-quality action title that combines platforming with intense superhero brawling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvelous---mouhitotsu-no-takarajima-japan', 'SNES', 'Marvelous - Mouhitotsu no Takarajima (Japan)', '1996', 'Adventure', 'Nintendo', '1', 'Story Adventure', 'Action-adventure RPG featuring three protagonists and puzzles.', 'Explore the island and find the treasure through teamwork.', 'Discover the brilliant Marvelous on the Super Famicom.', 'The directorial debut of Eiji Aonuma. Features 16-bit Zelda-style exploration, clever teamwork-based puzzles, and a charming, cinematic narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvelous---mouhitotsu-no-takarajima-japan-english-translation', 'SNES', 'Marvelous - Mouhitotsu no Takarajima (Japan) (English Translation)', '1996', 'Adventure', 'Nintendo', '1', 'Story Adventure', 'Action-adventure RPG with a full English fan translation.', 'Experience the island mystery with full English text.', 'Play Marvelous in English on the Super Nintendo.', 'The English translation makes this 16-bit masterpiece accessible. Control Dion, Max, and Jack to solve environmental puzzles and uncover ancient secrets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mary-shelleys-frankenstein-usa', 'SNES', 'Mary Shelley''s Frankenstein (USA)', '1994', 'Action', 'Bits Studios', '1', 'Action Platformer', 'Action-platformer based on the classic horror film.', 'Defeat the vengeful monster as the doctor or survive as the beast.', 'Experience Mary Shelley''s Frankenstein on the SNES.', 'A dark and atmospheric 16-bit title. Features cinematic cutscenes and a mix of combat and exploration inspired by the gothic horror novel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mary-shelleys-frankenstein-usa-beta', 'SNES', 'Mary Shelley''s Frankenstein (USA) (Beta)', '1994', 'Action', 'Bits Studios', '1', 'Action Platformer', 'Action-platformer based on the classic horror film.', 'Test early level designs and combat mechanics in this beta.', 'Check out Mary Shelley''s Frankenstein (Beta) on SNES.', 'A pre-release 16-bit development build. Witness the evolution of the dark environments and the balancing of the challenging combat sequences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mask-the-europe', 'SNES', 'Mask, The (Europe)', '1995', 'Action', 'Ocean Software', '1', 'Comic Platformer', 'Hyper-kinetic action-platformer based on the hit movie.', 'Stop the criminal syndicate using the mask''s chaotic powers.', 'Sssmokin''! Play The Mask for the Super Nintendo.', 'Features incredible 16-bit animations faithful to the film. Use crazy powers like the mallet, the horn, and the tornado to clear stages in Style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mask-the-japan', 'SNES', 'Mask, The (Japan)', '1995', 'Action', 'Ocean Software', '1', 'Comic Platformer', 'Hyper-kinetic action-platformer based on the hit movie.', 'Defeat the villains in the original Japanese version.', 'Experience The Mask on the Super Famicom.', 'The 16-bit Japanese release featuring the same high-energy slapstick action and vibrant graphics that capture the spirit of Jim Carrey''s performance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mask-the-usa', 'SNES', 'Mask, The (USA)', '1995', 'Action', 'Ocean Software', '1', 'Comic Platformer', 'Hyper-kinetic action-platformer based on the hit movie.', 'Stop the criminal syndicate using the mask''s chaotic powers.', 'Sssmokin''! Play The Mask for the Super Nintendo.', 'Master the 16-bit platforming and special attacks. A visually stunning and humorous title that is widely considered one of the best movie tie-ins on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mask-the-usa-beta', 'SNES', 'Mask, The (USA) (Beta)', '1995', 'Action', 'Ocean Software', '1', 'Comic Platformer', 'Hyper-kinetic action-platformer based on the hit movie.', 'Explore early slapstick animations and level layouts.', 'Check out The Mask (Beta) on the Super Nintendo.', 'A pre-release 16-bit development build. Witness the fine-tuning of Stanley Ipkiss''s transformations and the development of the colorful urban environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maten-densetsu---senritsu-no-ooparts-japan', 'SNES', 'Maten Densetsu - Senritsu no Ooparts (Japan)', '1996', 'RPG', 'ASCII', '1', 'Dark RPG', 'Atmospheric turn-based JRPG with a modern occult theme.', 'Investigate supernatural events and ancient Ooparts in Tokyo.', 'Explore the dark Maten Densetsu on the Super Famicom.', 'A unique 16-bit RPG set in modern-day Japan. Features a gritty atmosphere, demon-like enemies, and a narrative focused on archaeological mysteries.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('math-blaster---episode-one-usa', 'SNES', 'Math Blaster - Episode One (USA)', '1994', 'Educational', 'Davidson', '1', 'Educational', 'Educational action game focused on mathematics.', 'Solve math problems to defeat the invaders and save the day.', 'Learn and play in Math Blaster: Episode One on SNES.', 'A creative 16-bit blend of arcade action and education. Improve your math skills while navigating through space-themed levels and shooting targets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('matsukata-hiroki-no-super-trolling-japan', 'SNES', 'Matsukata Hiroki no Super Trolling (Japan)', '1994', 'Sports', 'Sega', '1', 'Fishing Simulation', 'Realistic deep-sea fishing simulation featuring Hiroki Matsukata.', 'Catch giant marlin and tuna in professional tournaments.', 'Go big-game fishing in Super Trolling on Super Famicom.', 'Features impressive 16-bit boat physics and a technical reeling system. Travel to international waters to prove you are the master of the open ocean.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('matsumura-kuni-hiroden---saikyou-no-rekishi-o-nurikaero!-japan', 'SNES', 'Matsumura Kuni Hiroden - Saikyou no Rekishi o Nurikaero! (Japan)', '1993', 'Strategy', 'ASCII', '1', 'Historical Strategy', 'Humorous one-on-one fighting game featuring a bizarre roster.', 'Win the tournament in this comedy-focused brawler.', 'Battle in Matsumura Kuni Hiroden on the Super Famicom.', 'Features digitized characters and a satirical tone. A unique 16-bit fighter that focuses more on humor and over-the-top animations than technical combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maui-mallard-in-cold-shadow-usa', 'SNES', 'Maui Mallard in Cold Shadow (USA)', '1995', 'Platformer', 'Disney Interactive', '1', 'Action Platformer', 'Action-adventure platformer starring Donald Duck''s alter ego.', 'Recover the missing idol as the ninja Maui Mallard.', 'Experience Maui Mallard in Cold Shadow on the SNES.', 'A 16-bit visual masterpiece. Switch between Donald and his ninja persona, mastering the staff combat and acrobatic platforming in a dark, atmospheric world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mazinger-z-japan-3d7f', 'SNES', 'Mazinger Z (Japan) [3D7F]', '1993', 'Action', 'Bandai', '1', 'Anime Action', 'Side-scrolling action game featuring the iconic mecha.', 'Defeat the Mechanical Beasts and stop Dr. Hell.', 'Pilot Mazinger Z on the Super Famicom.', 'Features large 16-bit sprites and iconic special moves like the Rocket Punch. A must-play for fans of the legendary Go Nagai anime series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mazinger-z-japan-7144', 'SNES', 'Mazinger Z (Japan) [7144]', '1993', 'Action', 'Bandai', '1', 'Anime Action', 'Side-scrolling action game featuring the iconic mecha.', 'Defeat the Mechanical Beasts and stop Dr. Hell.', 'Pilot Mazinger Z on the Super Famicom.', 'Experience the high-octane 16-bit combat of the original mecha hero. Use the Breast Fire and Rust Hurricane to decimate enemy forces.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mecarobot-golf-usa', 'SNES', 'Mecarobot Golf (USA)', '1994', 'Sports', 'Mindscape', '1', 'Golf Simulation', 'Sci-fi golf simulation featuring a robotic protagonist.', 'Win the futuristic golf tournament using mechanical precision.', 'Play the unique Mecarobot Golf on the SNES.', 'A 16-bit golf game with a twist. Use your robot''s sensors and power settings to master the fairways in a high-tech sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mechwarrior-europe', 'SNES', 'Mechwarrior (Europe)', '1993', 'Simulation', 'FASA Interactive', '1', 'Mech Simulation', 'First-person mech combat simulation using Mode 7 scaling.', 'Pilot your BattleMech to complete mercenary contracts.', 'Experience Mechwarrior''s 3D combat on the SNES.', 'A technical marvel for its time. Navigate a 16-bit cockpit, manage heat levels, and customize your mech''s weaponry for intense tactical missions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mechwarrior-france', 'SNES', 'Mechwarrior (France)', '1993', 'Simulation', 'FASA Interactive', '1', 'Mech Simulation', 'First-person mech combat simulation with localized French text.', 'Complete missions in the French version of the game.', 'Jouez à Mechwarrior en français sur le SNES.', 'The complete 16-bit mech simulation with localized menus and mission briefings. Pilot heavy armor and destroy targets across the galaxy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mechwarrior-germany', 'SNES', 'Mechwarrior (Germany)', '1993', 'Simulation', 'FASA Interactive', '1', 'Mech Simulation', 'First-person mech combat simulation with localized German text.', 'Complete missions in the German version of the game.', 'Spielen Sie Mechwarrior auf Deutsch für das SNES.', 'Strategic 16-bit combat featuring deep customization. Experience the iconic Battletech universe with localized German text and high-octane action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mechwarrior-spain', 'SNES', 'Mechwarrior (Spain)', '1993', 'Simulation', 'FASA Interactive', '1', 'Mech Simulation', 'First-person mech combat simulation with localized Spanish text.', 'Completa misiones tácticas en la versión española.', 'Juega Mechwarrior en español para la Super Nintendo.', 'Domina el campo de batalla desde la cabina de tu robot. Una simulación de combate en 16 bits que lleva la tecnología Mode 7 al límite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mechwarrior-usa', 'SNES', 'Mechwarrior (USA)', '1993', 'Simulation', 'FASA Interactive', '1', 'Mech Simulation', 'First-person mech combat simulation using Mode 7 scaling.', 'Pilot your BattleMech to complete mercenary contracts.', 'Experience Mechwarrior''s 3D combat on the SNES.', 'Master the controls of a walking tank. Features a non-linear campaign where you earn money to upgrade your weapons and chassis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mechwarrior-3050-europe', 'SNES', 'Mechwarrior 3050 (Europe)', '1996', 'Action', 'FASA Interactive', '1', 'Mech Shooter', 'Isometric action-strategy game featuring heavy mechs.', 'Stop the Clan invasion by destroying their forward bases.', 'Battle through Mechwarrior 3050 for the Super Nintendo.', 'A shift to an isometric 16-bit perspective. Control a Timber Wolf mech in high-stakes missions that require both firepower and careful movement.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mechwarrior-3050-usa', 'SNES', 'Mechwarrior 3050 (USA)', '1996', 'Action', 'FASA Interactive', '1', 'Mech Shooter', 'Isometric action-strategy game featuring heavy mechs.', 'Stop the Clan invasion by destroying their forward bases.', 'Battle through Mechwarrior 3050 for the Super Nintendo.', 'Features intense 2-player cooperative play where one pilots and the other aims. A challenging 16-bit entry in the Battletech saga.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-kart-retro', 'SNES', 'Mega Kart Retro', '2021', 'Racing', 'Fan Game', '1', 'Arcade Kart Racing', 'Fan-made Mario Kart hack with retro-themed tracks and assets.', 'Win the retro cup in this customized racing mod.', 'Play Mega Kart Retro on the Super Nintendo.', 'A creative 16-bit romhack that redesigns tracks and sprites to evoke an 8-bit aesthetic while maintaining the smooth Mode 7 gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-lo-mania---jikuu-daisenryaku-japan', 'SNES', 'Mega lo Mania - Jikuu Daisenryaku (Japan)', '1992', 'Strategy', 'Sensible Software', '2', 'Real-Time Strategy', 'Real-time strategy and god game with a focus on evolution.', 'Lead your tribe through the ages and conquer your rivals.', 'Master history in Mega lo Mania on Super Famicom.', 'A unique 16-bit RTS. Research new technologies, manage resources, and engage in tactical warfare across different historical eras.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-lo-mania-europe-enfrde', 'SNES', 'Mega lo Mania (Europe) (En,Fr,De)', '1991', 'Strategy', 'Sensible Software', '2', 'Real-Time Strategy', 'Real-time strategy and god game with a focus on evolution.', 'Conquer the islands in the localized European version.', 'Experience Mega lo Mania for the Super Nintendo.', 'Known for its digitized voice acting and deep strategy. Manage four different tribes and guide them from the stone age to the future.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-lo-mania-europe-enfrde-beta', 'SNES', 'Mega lo Mania (Europe) (En,Fr,De) (Beta)', '1991', 'Strategy', 'Sensible Software', '2', 'Real-Time Strategy', 'Real-time strategy and god game pre-release build.', 'Test the early research trees and combat balancing.', 'Check out the Mega lo Mania Beta on the SNES.', 'A rare 16-bit development build. Witness the fine-tuning of the resource management mechanics and early menu layouts for this cult classic RTS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-7---nerfed-spikes', 'SNES', 'Mega Man 7 - Nerfed Spikes', '2018', 'Platformer', 'Fan Hack', '1', 'Challenge Platformer', 'Gameplay modification for Mega Man 7 that balances difficulty.', 'Survive the levels with less punishing environmental hazards.', 'Play Mega Man 7: Nerfed Spikes on the SNES.', 'A 16-bit hack that makes instant-death spikes less frequent or lethal, allowing for a more accessible experience of the classic action-platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-7-refit', 'SNES', 'Mega Man 7 Refit', '2019', 'Platformer', 'Fan Hack', '1', 'Refined Platformer', 'Visual and mechanical overhaul of Mega Man 7.', 'Experience the 7th entry with improved sprites and palettes.', 'Play Mega Man 7 Refit on the Super Nintendo.', 'A polished 16-bit mod that adjusts the graphics to more closely match the style of the Mega Man X series, including color and sprite tweaks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x---complete-edition', 'SNES', 'Mega Man X - Complete Edition', '2020', 'Action', 'Fan Hack', '1', 'Enhanced Action Platformer', 'A comprehensive mod that combines various Mega Man X fixes.', 'Play the definitive version of X''s first adventure.', 'Experience Mega Man X: Complete Edition on SNES.', 'A 16-bit "Quality of Life" hack that fixes bugs, improves text, and adds minor features to provide the ultimate X1 experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x---debug-menu', 'SNES', 'Mega Man X - Debug Menu', '2017', 'Action', 'Fan Hack', '1', 'Debug Utility', 'Technical tool for exploring Mega Man X mechanics.', 'Access hidden game data and test room features.', 'Check out the Mega Man X Debug Menu on SNES.', 'A 16-bit utility that unlocks the original development tools, allowing players to manipulate sprites, levels, and item flags in real-time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x---hard-type', 'SNES', 'Mega Man X - Hard Type', '2016', 'Action', 'Fan Hack', '1', 'Difficulty Hack', 'High-difficulty overhaul of the original Mega Man X.', 'Test your skills against revamped enemies and level hazards.', 'Challenge Mega Man X: Hard Type on the SNES.', 'A brutal 16-bit redesign. Every stage and boss has been modified to provide an extreme challenge for veteran Maverick Hunters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x---new-order', 'SNES', 'Mega Man X - New Order', '2019', 'Action', 'Fan Hack', '1', 'Rebalanced Action', 'Thematic and mechanical overhaul of the Mega Man X engine.', 'Explore a "New Order" of levels and challenges.', 'Play Mega Man X: New Order on the Super Nintendo.', 'A 16-bit total conversion hack featuring new level layouts, custom enemy placement, and a fresh take on the classic X1 gameplay loop.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x---project-zero', 'SNES', 'Mega Man X - Project Zero', '2018', 'Action', 'Fan Hack', '1', 'Story Expansion', 'Expansion mod that focuses on Zero as a playable character.', 'Play through the first game as the legendary Red Hunter.', 'Experience Project Zero for Mega Man X on SNES.', 'A sophisticated 16-bit mod that integrates Zero as a fully playable character with his own move set, sabre combat, and animations within the first game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x---xtra-power', 'SNES', 'Mega Man X - Xtra Power', '2017', 'Action', 'Fan Hack', '1', 'Power-Up Enhancement', 'Power-up modification for Mega Man X.', 'Dominate the Mavericks with enhanced armor and weapon stats.', 'Play Mega Man X: Xtra Power on the Super Nintendo.', 'A 16-bit hack that tweaks X''s base power and weapon energy, making the character significantly more powerful for a faster, arcade-style run.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x---zero-playable-canonical-sprites', 'SNES', 'Mega Man X - Zero Playable Canonical Sprites', '2018', 'Action', 'Fan Hack', '1', 'Character Mod', 'Visual overhaul for Zero in Mega Man X.', 'Play as Zero with sprites that match his later game appearances.', 'Play Mega Man X: Zero Canonical Sprites on SNES.', 'A 16-bit aesthetic mod that replaces the original Zero sprites with more detailed, high-fidelity art consistent with the X2 and X3 designs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x-randomizer', 'SNES', 'Mega Man X Randomizer', '2021', 'Action', 'Fan Tool', '1', 'Randomizer', 'Programmatic level and item shuffler for Mega Man X.', 'Survive a randomized journey where every item is a surprise.', 'Try the Mega Man X Randomizer on the SNES.', 'A 16-bit logic-based hack that shuffles boss locations, items, and upgrades, ensuring a unique and unpredictable experience every play-through.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x-zero-playable---text-fix', 'SNES', 'Mega Man X Zero Playable - Text Fix', '2019', 'Action', 'Fan Hack', '1', 'Text Fix', 'Technical fix for the Zero playable mod in Mega Man X.', 'Enjoy Zero''s gameplay with corrected story and menu text.', 'Play the Mega Man X Zero Text Fix on SNES.', 'A 16-bit refinement that ensures the game''s narrative makes sense while playing as Zero, fixing dialogue glitches from earlier character-swap mods.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x1:-proto-edition', 'SNES', 'Mega Man X1: Proto Edition', '2017', 'Action', 'Fan Hack', '1', 'Prototype Restoration', 'Fan-made total conversion inspired by Proto Man.', 'Play through Mega Man X as the mysterious Proto Man.', 'Experience Mega Man X1: Proto Edition on SNES.', 'A 16-bit overhaul featuring a playable Proto Man with his iconic shield and dash mechanics, reimagined within the Maverick Hunter world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x2---4th-armor-hack', 'SNES', 'Mega Man X2 - 4th Armor Hack', '2019', 'Action', 'Fan Hack', '1', 'Armor Modification', 'Gameplay tweak for Mega Man X2 focusing on armor abilities.', 'Unlock the full potential of the 4th armor set in X2.', 'Play the Mega Man X2: 4th Armor Hack on SNES.', 'A 16-bit mod that brings forward armor abilities from later games into the X2 engine, offering new ways to traverse stages and defeat bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x2---proto-edition-v11', 'SNES', 'Mega Man X2 - Proto Edition v1.1', '2018', 'Action', 'Fan Hack', '1', 'Prototype Restoration', 'Fan-made Proto Man mod for Mega Man X2.', 'Master the stages of X2 using Proto Man''s unique skills.', 'Play Mega Man X2: Proto Edition v1.1 on SNES.', 'An early 16-bit version of the Proto Man conversion, featuring custom sprites and modified physics to suit the legendary character''s playstyle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x2---proto-edition-v12', 'SNES', 'Mega Man X2 - Proto Edition v1.2', '2019', 'Action', 'Fan Hack', '1', 'Prototype Restoration', 'Refined fan-made Proto Man mod for Mega Man X2.', 'Experience a more polished Proto Man adventure in X2.', 'Play Mega Man X2: Proto Edition v1.2 on SNES.', 'An updated 16-bit revision with better sprite animations and balanced projectile damage for the playable Proto Man character.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x2---xtra-power', 'SNES', 'Mega Man X2 - Xtra Power', '2017', 'Action', 'Fan Hack', '1', 'Power-Up Enhancement', 'Power-up modification for Mega Man X2.', 'Steamroll the Mavericks with boosted stats and abilities.', 'Play Mega Man X2: Xtra Power on the Super Nintendo.', 'A 16-bit hack designed for pure action, giving X increased fire rate and mobility to breeze through the game''s challenging levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x2---zero-playable', 'SNES', 'Mega Man X2 - Zero Playable', '2016', 'Action', 'Fan Hack', '1', 'Character Mod', 'Character swap mod for Mega Man X2.', 'Tear through the X2 Mavericks using Zero''s Z-Saber.', 'Play Mega Man X2: Zero Playable on the SNES.', 'A 16-bit mod that swaps X for Zero. Features basic sabre animations and adjusted physics to allow Zero to navigate the X2 stage designs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x2---zero-playable-with-triple-attack-clasic', 'SNES', 'Mega Man X2 - Zero Playable with Triple Attack (Clasic)', '2016', 'Action', 'Fan Hack', '1', 'Character Mod', 'Advanced Zero mod for Mega Man X2 with triple attack.', 'Master the classic 3-hit combo in the X2 engine.', 'Experience Zero Triple Attack (Classic) on SNES.', 'A 16-bit technical hack that implements Zero''s signature three-hit sabre combo, providing a much more authentic Zero gameplay experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x2---zero-playable-with-triple-attack-fake', 'SNES', 'Mega Man X2 - Zero Playable with Triple Attack (Fake)', '2016', 'Action', 'Fan Hack', '1', 'Character Mod', 'Experimental Zero mod for Mega Man X2 with a modified attack.', 'Test a unique custom combo system for Zero.', 'Play Zero Triple Attack (Fake) on the SNES.', 'A 16-bit variation of the triple attack mod featuring different frame data and animation timing for players looking for a different combat feel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x2-zero-playable---graphic-and-text-fix', 'SNES', 'Mega Man X2 Zero Playable - Graphic and Text Fix', '2017', 'Action', 'Fan Hack', '1', 'Graphics Fix', 'Refined character swap mod for Mega Man X2.', 'Enjoy playing as Zero with corrected visuals and dialogue.', 'Play X2 Zero Playable (Graphic/Text Fix) on SNES.', 'A 16-bit polish mod that ensures Zero''s sprites look perfect and the game''s text correctly references him instead of X during key scenes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x3---shadow-armor', 'SNES', 'Mega Man X3 - Shadow Armor', '2018', 'Action', 'Fan Hack', '1', 'Armor Modification', 'Armor modification for Mega Man X3.', 'Equip the legendary Shadow Armor for a new way to play.', 'Play Mega Man X3: Shadow Armor on the SNES.', 'A 16-bit hack that imports the fan-favorite Shadow Armor from X6 into the X3 engine, including its unique invulnerabilities and attack patterns.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x3---tsuraranoma-2011', 'SNES', 'Mega Man X3 - Tsuraranoma (2011)', '2011', 'Action', 'Fan Hack', '1', 'Experimental Hack', 'Rare Japanese fan-made level pack for Mega Man X3.', 'Conquer a series of highly difficult custom challenge rooms.', 'Play Mega Man X3: Tsuraranoma on the SNES.', 'A 16-bit romhack from the Japanese scene that focuses on extreme precision platforming and expert-level boss encounters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x3---zero-project-v41', 'SNES', 'Mega Man X3 - Zero Project V4.1', '2019', 'Action', 'Fan Hack', '1', 'Character Expansion', 'Comprehensive playable Zero overhaul for Mega Man X3.', 'Play as Zero with a full move set and custom story.', 'Experience Zero Project V4.1 for Mega Man X3.', 'The definitive 16-bit Zero experience. V4.1 introduced the ability to switch characters instantly and use the sabre as a primary weapon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x3---zero-project-v44', 'SNES', 'Mega Man X3 - Zero Project V4.4', '2020', 'Action', 'Fan Hack', '1', 'Character Expansion', 'Comprehensive playable Zero overhaul for Mega Man X3.', 'Experience improved stability and new animations for Zero.', 'Explore Zero Project V4.4 for Mega Man X3.', 'An updated 16-bit revision of the project, focusing on fixing sprite flickering and balancing Zero''s damage output compared to X.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x3---zero-project-v46', 'SNES', 'Mega Man X3 - Zero Project V4.6', '2021', 'Action', 'Fan Hack', '1', 'Character Expansion', 'Comprehensive playable Zero overhaul for Mega Man X3.', 'Play through X3 with the most polished Zero mechanics.', 'Discover Zero Project V4.6 for Mega Man X3.', 'Features refined 16-bit code for smoother character switching and improved compatibility with the original game''s special effects and power-ups.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x3---zero-project-v48', 'SNES', 'Mega Man X3 - Zero Project V4.8', '2022', 'Action', 'Fan Hack', '1', 'Character Expansion', 'The peak version of the Zero playable overhaul for X3.', 'Enjoy the ultimate Zero experience with full features.', 'Play Zero Project V4.8 for Mega Man X3.', 'The most stable 16-bit version of the mod. Includes full dialogue support for Zero, corrected ending sequences, and perfected combat mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x3:-proto-edition', 'SNES', 'Mega Man X3: Proto Edition', '2018', 'Action', 'Fan Hack', '1', 'Prototype Restoration', 'Fan-made total conversion for Mega Man X3 starring Proto Man.', 'Complete the X3 trilogy as the red shield-bearer.', 'Experience Mega Man X3: Proto Edition on SNES.', 'A high-quality 16-bit mod that finishes the "Proto Edition" trilogy, bringing custom physics and sprites to the most complex game in the SNES series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megaman-7-proto-edition', 'SNES', 'Megaman 7 Proto Edition', '2017', 'Platformer', 'Fan Hack', '1', 'Prototype Restoration', 'Fan-made total conversion for Mega Man 7.', 'Play through the 16-bit classic as the mysterious Proto Man.', 'Experience Mega Man 7: Proto Edition on the SNES.', 'A creative 16-bit overhaul that replaces Mega Man with Proto Man. Features custom shield mechanics, modified slide-dashes, and a revamped UI to match the Red Hunter''s aesthetic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megaman-bass', 'SNES', 'Megaman Bass', '1998', 'Action', 'Capcom', '1', 'Action Platformer', 'Action-platformer crossover (SNES demake/hack).', 'Choose between Mega Man or Bass to stop Wily''s latest plan.', 'Play Mega Man & Bass on the Super Nintendo.', 'A 16-bit project that brings the GBA/Super Famicom classic to the standard SNES engine. Master Bass''s rapid-fire and double-jump or Mega Man''s classic charged shot.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megaman-vii-europe', 'SNES', 'Megaman VII (Europe)', '1995', 'Action', 'Capcom', '1', 'Action Platformer', 'Action-platformer with large sprites and vibrant colors.', 'Defeat the 8 Robot Masters and infiltrate Wily''s fortress.', 'Play Mega Man 7 for the Super Nintendo.', 'The only core Mega Man entry for the SNES. Features a 16-bit upgrade to the classic formula, introducing Rush searches, a shop system, and a secret versus mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megaman-vii-usa', 'SNES', 'Megaman VII (USA)', '1995', 'Action', 'Capcom', '1', 'Action Platformer', 'Action-platformer with large sprites and vibrant colors.', 'Defeat the 8 Robot Masters and infiltrate Wily''s fortress.', 'Play Mega Man 7 for the Super Nintendo.', 'Master the 16-bit combat and weapon acquisition. A highly polished action title featuring some of the largest and most detailed character sprites in the entire franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megaman-x---generation-dashfix', 'SNES', 'Megaman X - Generation (dashfix)', '2014', 'Action', 'Fan Hack', '1', 'Movement Enhancement', 'Gameplay modification for Mega Man X focusing on movement.', 'Experience the first X game with a refined dash mechanic.', 'Play Mega Man X: Generation (Dashfix) on SNES.', 'A "Quality of Life" 16-bit hack that adjusts the dash delay and physics. Provides a snappier, more modern feel to X''s movement, closer to the speed of Mega Man X2 and X3.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megaman-x-europe', 'SNES', 'Megaman X (Europe)', '1993', 'Action', 'Capcom', '1', 'Action Platformer', 'Side-scrolling action-platformer and evolution of the series.', 'Hunt down the Maverick revolters led by Sigma.', 'Experience the legendary Mega Man X on the SNES.', 'A 16-bit masterpiece. Introduced the wall-jump, dash, and hidden armor capsules. A faster, more aggressive take on the blue bomber that defined the 90s action genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megaman-x-usa', 'SNES', 'Megaman X (USA)', '1993', 'Action', 'Capcom', '1', 'Action Platformer', 'Side-scrolling action-platformer and evolution of the series.', 'Hunt down the Maverick revolters led by Sigma.', 'Experience the legendary Mega Man X on the SNES.', 'Discover the 16-bit world of 21XX. Master the boss weaknesses and find the hidden Hadouken in one of the most perfectly paced action games ever made.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megaman-x-usa-rev-a', 'SNES', 'Megaman X (USA) (Rev A)', '1993', 'Action', 'Capcom', '1', 'Action Platformer', 'Side-scrolling action-platformer (Updated Revision).', 'Defeat Sigma in this refined North American version.', 'Play the polished Mega Man X (Rev A) on the SNES.', 'An updated 16-bit revision that fixes minor graphical glitches and several well-known bugs (like the Boomerang Kuwanger skip) for a more stable experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megaman-x:-capsule-remix', 'SNES', 'Megaman X: Capsule Remix', '2019', 'Action', 'Fan Hack', '1', 'Remix Hack', 'Gameplay modification that reorders the armor upgrades.', 'Discover a new path by finding armor parts in different locations.', 'Play Mega Man X: Capsule Remix on the SNES.', 'A creative 16-bit romhack that shuffles the locations of the leg, arm, head, and body capsules, forcing players to rethink their stage completion order.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megaman-x2---ultimate-armor', 'SNES', 'Megaman X2 - Ultimate Armor', '2018', 'Action', 'Fan Hack', '1', 'Armor Modification', 'Gameplay modification that grants X the final armor from the start.', 'Steamroll the Mavericks with the most powerful armor set.', 'Play Mega Man X2: Ultimate Armor on the SNES.', 'A 16-bit power-fantasy mod. Start the game with the full Giga Armor, allowing for infinite dashes and massive damage output from the first stage.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megaman-x2-europe', 'SNES', 'Megaman X2 (Europe)', '1995', 'Action', 'Capcom', '1', 'Action Platformer', 'Side-scrolling action-platformer featuring the Cx4 chip.', 'Stop the "X-Hunters" and rebuild your fallen ally, Zero.', 'Experience Mega Man X2 for the Super Nintendo.', 'Utilizes the 16-bit Cx4 chip for wireframe 3D effects. Features faster gameplay, the air-dash, and epic showdowns against Serges, Agile, and Violen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megaman-x2-usa', 'SNES', 'Megaman X2 (USA)', '1995', 'Action', 'Capcom', '1', 'Action Platformer', 'Side-scrolling action-platformer featuring the Cx4 chip.', 'Stop the "X-Hunters" and rebuild your fallen ally, Zero.', 'Experience Mega Man X2 for the Super Nintendo.', 'A technical and gameplay marvel. Master the double-charge shot and the Giga Crush in this high-speed 16-bit sequel that pushes the SNES to its limits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megaman-x3-europe', 'SNES', 'Megaman X3 (Europe)', '1995', 'Action', 'Capcom', '1', 'Action Platformer', 'Side-scrolling action-platformer and final 16-bit X entry.', 'Defeat the Doppler army and stop Sigma''s viral evolution.', 'Play Mega Man X3 for the Super Nintendo.', 'The largest 16-bit X game. Features the ability to play as Zero, four different Ride Armors, and multiple endings based on which bosses you defeat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megaman-x3-usa', 'SNES', 'Megaman X3 (USA)', '1995', 'Action', 'Capcom', '1', 'Action Platformer', 'Side-scrolling action-platformer and final 16-bit X entry.', 'Defeat the Doppler army and stop Sigma''s viral evolution.', 'Play Mega Man X3 for the Super Nintendo.', 'Master the chip upgrades and the Z-Saber. A deep 16-bit action-adventure that offers the most customization and secret content in the SNES trilogy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megamans-soccer-usa', 'SNES', 'Megaman''s Soccer (USA)', '1994', 'Sports', 'Capcom', '4', 'Arcade Sports', 'Sports-action hybrid featuring characters from the Mega Man series.', 'Win the soccer tournament using special character shots.', 'Kick off in Mega Man''s Soccer for the SNES.', 'A wacky 16-bit sports title. Assemble a team of Robot Masters like Wood Man or Fire Man and use their signature weapons as special soccer moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('melfand-stories-japan', 'SNES', 'Melfand Stories (Japan)', '1994', 'RPG', 'Sting', '1', 'Tactical RPG', 'Side-scrolling beat ''em up with a fantasy setting and multiple paths.', 'Navigate the kingdom and stop the evil uprising as a hero duo.', 'Discover the vibrant Melfand Stories on Super Famicom.', 'A charming 16-bit brawler. Choose from four different characters and enjoy branching paths, beautiful pixel art, and a lighthearted tone rare for the genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-combat---falcons-revenge-europe', 'SNES', 'Metal Combat - Falcon''s Revenge (Europe)', '1994', 'Action', 'Intelligent Systems', '1', 'Mech Action', 'First-person mecha light-gun shooter and sequel to Battle Clash.', 'Pilot the Falcon and defeat the battle-suit champions.', 'Take aim in Metal Combat: Falcon''s Revenge on SNES.', 'A 16-bit masterpiece for the Super Scope. Features massive, detailed mechs and a deep tactical shooting system where you target specific weak points on enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-combat---falcons-revenge-usa', 'SNES', 'Metal Combat - Falcon''s Revenge (USA)', '1994', 'Action', 'Intelligent Systems', '1', 'Mech Action', 'First-person mecha light-gun shooter and sequel to Battle Clash.', 'Pilot the Falcon and defeat the battle-suit champions.', 'Take aim in Metal Combat: Falcon''s Revenge on SNES.', 'The pinnacle of 16-bit light-gun gaming. Experience intense mecha duels with destructible parts and a cinematic sci-fi story that expands the Battle Clash lore.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-marines-europe', 'SNES', 'Metal Marines (Europe)', '1993', 'Strategy', 'Namco', '1', 'Real-Time Strategy', 'Real-time strategy game with a focus on base building and defense.', 'Conquer the island chains and destroy the enemy commander.', 'Master strategy in Metal Marines for the SNES.', 'A unique 16-bit RTS. Manage resources to build missile silos and giant robots while defending your base in split-screen tactical warfare.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-marines-usa', 'SNES', 'Metal Marines (USA)', '1993', 'Strategy', 'Namco', '1', 'Real-Time Strategy', 'Real-time strategy game with a focus on base building and defense.', 'Conquer the island chains and destroy the enemy commander.', 'Master strategy in Metal Marines for the SNES.', 'Features intense 16-bit tactical gameplay. Launch devastating ICBMs and deploy your Metal Marines to seize enemy territory in this high-stakes military sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-max-2-japan', 'SNES', 'Metal Max 2 (Japan)', '1993', 'RPG', 'Data East', '1', 'Post-Apocalyptic RPG', 'Open-world turn-based RPG in a post-apocalyptic wasteland.', 'Hunt outlaws and customize your tanks to survive the desert.', 'Explore the gritty Metal Max 2 on the Super Famicom.', 'A 16-bit cult classic. Features a non-linear world where you can spend hours customizing your tanks'' engines, cannons, and armor to survive the harsh outlands.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-max-returns-japan', 'SNES', 'Metal Max Returns (Japan)', '1995', 'RPG', 'Data East', '1', 'Remake RPG', 'Remake of the original Famicom RPG with 16-bit technology.', 'Travel the wasteland and become the world''s greatest hunter.', 'Discover Metal Max Returns on the Super Famicom.', 'A massive 16-bit graphical and mechanical overhaul. Features a deep tank-customization system and a quirky, open-ended world filled with bizarre enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-max-returns-japan-en-by-aeon-genesis-v10', 'SNES', 'Metal Max Returns (Japan) [En by Aeon Genesis v1.0]', '1995', 'RPG', 'Data East', '1', 'Remake RPG', 'Remake of the original Famicom RPG with a full English translation.', 'Experience the post-apocalyptic tank RPG with English text.', 'Play Metal Max Returns in English on the SNES.', 'The Aeon Genesis translation makes this 16-bit gem accessible. Hunt bounty targets and build the ultimate garage of tanks in a world that feels like a 16-bit "Fallout."');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-morph-usa', 'SNES', 'Metal Morph (USA)', '1993', 'Action', 'Origin Systems', '1', 'Isometric Action', 'Side-scrolling action game with mecha-morphing mechanics.', 'Infiltrate the enemy base and transform your suit to adapt.', 'Fight through the levels of Metal Morph on the SNES.', 'A 16-bit action title where you switch between a humanoid walker and a jet-like flyer. Navigate through industrial stages and engage in challenging boss fights.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-slader-glory---directors-cut-japan-np', 'SNES', 'Metal Slader Glory - Director''s Cut (Japan) (NP)', '2000', 'RPG', 'HAL Laboratory', '1', 'Story-Driven RPG', 'Cinematic visual novel and adventure game (Director''s Cut).', 'Solve the space mystery and stop the mechanical threat.', 'Experience Metal Slader Glory on the Super Famicom.', 'Originally an NP (Nintendo Power) flash release. Features some of the best 16-bit pixel art ever created, with cinematic cutscenes and a deep sci-fi narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-warriors-usa', 'SNES', 'Metal Warriors (USA)', '1995', 'Action', 'LucasArts', '2', 'Run and Gun', 'Side-scrolling mecha action-platformer with pilot-ejection.', 'Lead the resistance and pilot various mechs in a civil war.', 'Master the mechs in Metal Warriors for the SNES.', 'A 16-bit masterpiece by LucasArts. Eject from your mech to hijack others, master 6 different robot types, and enjoy one of the best multiplayer modes on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('michael-andrettis-indycar-challenge-japan', 'SNES', 'Michael Andretti''s IndyCar Challenge (Japan)', '1994', 'Racing', 'Papyrus Design Group', '1', 'Racing Simulation', 'Mode 7-based open-wheel racing simulation.', 'Win the IndyCar championship across diverse international tracks.', 'Race to the finish in Michael Andretti''s IndyCar Challenge.', 'A technical 16-bit racer that utilizes the SNES''s rotation effects for a smooth cockpit view. Features real-world tracks and professional tuning options for your car.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('michael-andrettis-indycar-challenge-usa', 'SNES', 'Michael Andretti''s IndyCar Challenge (USA)', '1994', 'Racing', 'Papyrus Design Group', '1', 'Racing Simulation', 'Mode 7-based open-wheel racing simulation.', 'Climb the standings and win the season as Michael Andretti.', 'Master the track in Michael Andretti''s IndyCar Challenge.', 'Features a high-speed frame rate and a unique "spotter" voice system. A realistic 16-bit simulation of professional IndyCar racing with challenging AI and pit-stop strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('michael-jordan---chaos-in-the-windy-city-europe', 'SNES', 'Michael Jordan - Chaos in the Windy City (Europe)', '1994', 'Action', 'Beam Software', '1', 'Action Platformer', 'Side-scrolling action-platformer starring the NBA legend.', 'Rescue your teammates from a subterranean prison using basketballs.', 'Join the action in Michael Jordan: Chaos in the Windy City.', 'Control Jordan in a 16-bit adventure where you use various power-up basketballs (ice, fire, bomb) to defeat enemies and solve environmental puzzles in Chicago.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('michael-jordan---chaos-in-the-windy-city-usa', 'SNES', 'Michael Jordan - Chaos in the Windy City (USA)', '1994', 'Action', 'Beam Software', '1', 'Action Platformer', 'Side-scrolling action-platformer starring the NBA legend.', 'Rescue your teammates from a subterranean prison using basketballs.', 'Join the action in Michael Jordan: Chaos in the Windy City.', 'Features smooth animations and a massive amount of secret rooms. A creative 16-bit licensed title that blends sports themes with traditional platforming action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mick-&-mack-as-the-global-gladiators-usa-proto-1829', 'SNES', 'Mick & Mack as the Global Gladiators (USA) (Proto) [1829]', '1992', 'Action', 'Virgin Interactive', '2', 'Platformer', 'Action-platformer with an environmental message (Prototype).', 'Navigate a world of pollution and defeat the toxic slime monsters.', 'Check out the Global Gladiators Prototype on the SNES.', 'A rare 16-bit development build of the McDonald''s licensed game. Features fluid animations and projectile-based combat in a vibrant, message-driven world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mick-&-mack-as-the-global-gladiators-usa-proto-71ab', 'SNES', 'Mick & Mack as the Global Gladiators (USA) (Proto) [71AB]', '1992', 'Action', 'Virgin Interactive', '2', 'Platformer', 'Action-platformer with an environmental message (Prototype).', 'Test early level layouts and sprite physics in this beta build.', 'Explore the Global Gladiators (71AB) Proto on the SNES.', 'An early look at the 16-bit platformer''s development. Witness the fine-tuning of the "Goo" weapon and the evolution of the slime-filled environmental stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-mania---the-timeless-adventures-of-mickey-mouse-europe', 'SNES', 'Mickey Mania - The Timeless Adventures of Mickey Mouse (Europe)', '1994', 'Action', 'Traveller''s Tales', '1', 'Cinematic Platformer', 'Cinematic platformer celebrating Mickey''s animation history.', 'Journey through Mickey''s most famous cartoons to defeat Pete.', 'Play the stunning Mickey Mania for the Super Nintendo.', 'A visual masterpiece. Levels are based on "Steamboat Willie," "The Lonesome Ghosts," and more. Features 16-bit graphics that look like actual hand-drawn cells.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-mania---the-timeless-adventures-of-mickey-mouse-japan', 'SNES', 'Mickey Mania - The Timeless Adventures of Mickey Mouse (Japan)', '1994', 'Action', 'Traveller''s Tales', '1', 'Cinematic Platformer', 'Cinematic platformer celebrating Mickey''s animation history.', 'Relive Mickey''s classic cartoons in the Japanese version.', 'Experience Mickey Mania on the Super Famicom.', 'The original 16-bit Japanese release. Known for its incredible attention to detail, rotoscoped animations, and challenging levels that replicate the history of Disney.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-mania---the-timeless-adventures-of-mickey-mouse-usa', 'SNES', 'Mickey Mania - The Timeless Adventures of Mickey Mouse (USA)', '1994', 'Action', 'Traveller''s Tales', '1', 'Cinematic Platformer', 'Cinematic platformer celebrating Mickey''s animation history.', 'Journey through Mickey''s most famous cartoons to defeat Pete.', 'Play the stunning Mickey Mania for the Super Nintendo.', 'Master the 16-bit platforming in "The Mad Doctor" and "The Prince and the Pauper." A nostalgic and technically impressive tribute to the world''s most famous mouse.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-no-magical-adventure-japan', 'SNES', 'Mickey no Magical Adventure (Japan)', '1992', 'Action', 'Capcom', '1', 'Action Platformer', 'Disney platformer featuring an iconic costume-change mechanic.', 'Rescue Pluto and defeat Emperor Pete in the Japanese version.', 'Play Mickey no Magical Adventure on the Super Famicom.', 'The original release of the Capcom classic. Switch between a wizard, fireman, and mountain climber to use 16-bit magical powers and navigate vibrant stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-no-magical-adventure-japan-rev-a', 'SNES', 'Mickey no Magical Adventure (Japan) (Rev A)', '1992', 'Action', 'Capcom', '1', 'Action Platformer', 'Disney platformer featuring an iconic costume-change mechanic.', 'Save Pluto in this refined Japanese revision.', 'Play the polished Magical Adventure (Rev A) on SNES.', 'An updated 16-bit revision that fixes minor hit-detection bugs and optimizes the costume-switching speed for a more fluid gameplay experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-no-tokyo-disneyland-daibouken-english', 'SNES', 'Mickey no Tokyo Disneyland Daibouken (English)', '1994', 'Action', 'Capcom', '1', 'Theme Park Platformer', 'Side-scrolling platformer set in the famous theme park.', 'Explore Tokyo Disneyland and stop Pete''s disruptive scheme.', 'Play Mickey no Tokyo Disneyland Daibouken in English.', 'A fan-translated 16-bit gem. Use a unique "balloon" mechanic to float, attack, and solve puzzles across meticulously recreated park attractions like Space Mountain.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-no-tokyo-disneyland-daibouken-japan', 'SNES', 'Mickey no Tokyo Disneyland Daibouken (Japan)', '1994', 'Action', 'Capcom', '1', 'Theme Park Platformer', 'Side-scrolling platformer set in the famous theme park.', 'Navigate through the attractions of Tokyo Disneyland.', 'Experience Mickey no Tokyo Disneyland Daibouken on SNES.', 'A Japan-exclusive 16-bit title with incredible graphics. Use water and gas balloons to traverse levels based on real Disney park locations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-to-donald---magical-adventure-3-japan', 'SNES', 'Mickey to Donald - Magical Adventure 3 (Japan)', '1995', 'Action', 'Capcom', '2', 'Action Platformer', 'Cooperative action-platformer featuring Mickey and Donald.', 'Save the triplets and defeat Baron Pete in this epic sequel.', 'Discover Mickey to Donald: Magical Adventure 3 on SNES.', 'The final entry in the 16-bit trilogy. Features 2-player co-op and unique costumes like the Knight (Mickey) and the Barrel (Donald) with distinct abilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-to-donald---magical-adventure-3-japan-en-by-rpgone-v11-~mickey-&-donald---magical-adventure-3', 'SNES', 'Mickey to Donald - Magical Adventure 3 (Japan) [En by RPGOne v1.1] (~Mickey & Donald - Magical Adventure 3)', '1995', 'Action', 'Capcom', '2', 'Action Platformer', 'Cooperative action-platformer with a full English translation.', 'Play the best Magical Adventure entry with English text.', 'Play Magical Adventure 3 in English on the Super Nintendo.', 'The RPGOne translation makes this 16-bit Capcom masterpiece fully accessible. Enjoy the witty dialogue and master the creative costume powers in English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-to-minnie---magical-adventure-2-japan', 'SNES', 'Mickey to Minnie - Magical Adventure 2 (Japan)', '1994', 'Action', 'Capcom', '2', 'Action Platformer', 'Cooperative action-platformer featuring Mickey and Minnie.', 'Rescue the children and stop the Great Circus mystery.', 'Play Mickey to Minnie: Magical Adventure 2 on SNES.', 'Known as The Great Circus Mystery in the West. A beautiful 16-bit title featuring 2-player co-op and costumes like the Sweeper and the Safari outfit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickeys-playtown-adventure---a-day-of-discovery!-usa-proto', 'SNES', 'Mickey''s Playtown Adventure - A Day of Discovery! (USA) (Proto)', '1994', 'Educational', 'Disney Interactive', '1', 'Educational Adventure', 'Educational adventure for young children (Prototype).', 'Explore the town and complete simple tasks with Mickey and friends.', 'Check out Mickey''s Playtown Adventure Proto on SNES.', 'A rare 16-bit educational title that was never officially released. Features colorful graphics and mini-games designed to teach basic logic and coordination.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickeys-ultimate-challenge-usa', 'SNES', 'Mickey''s Ultimate Challenge (USA)', '1994', 'Puzzle', 'Disney Interactive', '1', 'Logic Puzzle', 'Puzzle-adventure game featuring various logic challenges.', 'Win the tournament of the castle by solving all the puzzles.', 'Challenge your mind in Mickey''s Ultimate Challenge on SNES.', 'A 16-bit collection of brain-teasers, memory games, and sliding puzzles. Perfect for younger players looking for a non-violent Disney adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('micro-machines-europe', 'SNES', 'Micro Machines (Europe)', '1993', 'Racing', 'Codemasters', '2', 'Top-Down Racing', 'Top-down arcade racer with miniature vehicles.', 'Win the desk-top and garden races in this European hit.', 'Race the tiny cars in Micro Machines for the SNES.', 'A 16-bit classic featuring diverse "tracks" like breakfast tables and pool tables. Master the handling of tanks, sports cars, and boats in fast-paced matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('micro-machines-usa', 'SNES', 'Micro Machines (USA)', '1993', 'Racing', 'Codemasters', '2', 'Top-Down Racing', 'Top-down arcade racer with miniature vehicles.', 'Outrun your rivals and stay on the screen to win.', 'Play the addictive Micro Machines on the Super Nintendo.', 'Features incredible 16-bit couch multiplayer action. Choose from a roster of quirky characters and survive the household hazards in every race.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('micro-machines-2---turbo-tournament-europe', 'SNES', 'Micro Machines 2 - Turbo Tournament (Europe)', '1994', 'Racing', 'Codemasters', '4', 'Top-Down Racing', 'Expanded top-down racer sequel with more vehicles and tracks.', 'Win the Turbo Tournament and claim the miniature trophy.', 'Experience Micro Machines 2 for the Super Nintendo.', 'Features updated 16-bit physics and a massive roster of new vehicles, including hovercrafts and monster trucks. A peak multiplayer experience on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('might-and-magic---book-two-japan', 'SNES', 'Might and Magic - Book Two (Japan)', '1992', 'RPG', 'New World Computing', '1', 'First-Person RPG', 'First-person dungeon-crawling RPG (Remake of the classic).', 'Explore the land of Cron and defeat the ancient evil.', 'Play Might and Magic: Book Two on the Super Famicom.', 'A 16-bit Japanese remake of the western classic. Features improved graphics, a sophisticated party system, and hundreds of hours of deep dungeon-crawling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('might-and-magic-ii---gates-to-another-world-europe', 'SNES', 'Might and Magic II - Gates to Another World (Europe)', '1993', 'RPG', 'New World Computing', '1', 'First-Person RPG', 'First-person dungeon-crawling RPG set in a massive world.', 'Stop the Mega Dragon and save the world from destruction.', 'Experience Might and Magic II for the Super Nintendo.', 'A complex 16-bit RPG that rewards mapping and strategy. Manage a party of up to six characters and navigate a vast, non-linear fantasy landscape.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('might-and-magic-ii---gates-to-another-world-germany', 'SNES', 'Might and Magic II - Gates to Another World (Germany)', '1993', 'RPG', 'New World Computing', '1', 'First-Person RPG', 'First-person dungeon-crawling RPG with localized German text.', 'Explore the gates to another world in the German version.', 'Spielen Sie Might and Magic II auf Deutsch für das SNES.', 'The complete 16-bit western RPG experience with localized German text. Features deep character customization and challenging turn-based tactical combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('might-and-magic-iii---isles-of-terra-usa', 'SNES', 'Might and Magic III - Isles of Terra (USA)', '1995', 'RPG', 'New World Computing', '1', 'First-Person RPG', 'First-person dungeon-crawling RPG with enhanced 16-bit tech.', 'Explore the Isles of Terra and stop the space-faring Sheltem.', 'Discover Might and Magic III for the Super Nintendo.', 'A late-gen 16-bit port featuring a much-improved interface and vibrant graphics. A must-play for fans of traditional, deep western role-playing games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('might-and-magic-iii---isles-of-terra-usa-beta', 'SNES', 'Might and Magic III - Isles of Terra (USA) (Beta)', '1995', 'RPG', 'New World Computing', '1', 'First-Person RPG', 'First-person dungeon-crawling RPG (Pre-release build).', 'Test the early party mechanics and dungeon layouts.', 'Check out the Might and Magic III Beta on the SNES.', 'A rare 16-bit development build. Witness the fine-tuning of the encounter rates and the evolution of the Isles of Terra''s environmental art.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mighty-max-europe', 'SNES', 'Mighty Max (Europe)', '1994', 'Action', 'WJS Design', '1', 'Action Platformer', 'Action-platformer based on the popular toy line and cartoon.', 'Defeat Skullmaster by traveling through magical portals.', 'Join the hunt in Mighty Max for the Super Nintendo.', 'Control Max in a 16-bit adventure across diverse dimensions. Use gadgets and help from Norman and Virgil to stop the ultimate evil.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mighty-max-usa', 'SNES', 'Mighty Max (USA)', '1994', 'Action', 'WJS Design', '1', 'Action Platformer', 'Action-platformer based on the popular toy line and cartoon.', 'Stop Skullmaster across various isometric and 2D stages.', 'Experience the adventure of Mighty Max on the SNES.', 'Features a mix of combat and exploration. A challenging 16-bit title that captures the dark-yet-adventurous tone of the animated series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mighty-max-usa-beta', 'SNES', 'Mighty Max (USA) (Beta)', '1994', 'Action', 'WJS Design', '1', 'Action Platformer', 'Action-platformer (Pre-release build).', 'Explore early level designs and portal mechanics in this beta.', 'Check out the Mighty Max Beta on the Super Nintendo.', 'A rare 16-bit development look at the game''s mechanics. Features early sprite work and unpolished level segments from the toy-based adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mighty-morphin-power-rangers---the-fighting-edition-europe', 'SNES', 'Mighty Morphin Power Rangers - The Fighting Edition (Europe)', '1995', 'Fighting', 'Natsume', '2', 'Competitive Fighting', 'One-on-one giant robot fighting game based on the show.', 'Defeat the monstrous guardians and Ivan Ooze in giant mecha duels.', 'Pilot the Megazord in Power Rangers: Fighting Edition.', 'A polished 16-bit fighter featuring massive sprites. Control the Megazord, Dragonzord, or even Lord Zedd in intense duels with a unique energy-gauge system for special attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mighty-morphin-power-rangers---the-fighting-edition-usa', 'SNES', 'Mighty Morphin Power Rangers - The Fighting Edition (USA)', '1995', 'Fighting', 'Natsume', '2', 'Competitive Fighting', 'One-on-one giant robot fighting game based on the show.', 'Master the Megazord''s moves to win the interstellar tournament.', 'Experience Power Rangers: Fighting Edition on the SNES.', 'Features incredible mecha pixel art and fluid animations. Use powerful combos and screen-filling finishing moves in this high-octane 16-bit tribute to the Sentai series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mighty-morphin-power-rangers---the-movie-europe', 'SNES', 'Mighty Morphin Power Rangers - The Movie (Europe)', '1995', 'Action', 'Gray Matter', '1', 'Beat ''em Up', 'Side-scrolling beat ''em up based on the 1995 feature film.', 'Fight through Angel Grove to stop the menace of Ivan Ooze.', 'Play Power Rangers: The Movie for the Super Nintendo.', 'A cinematic 16-bit brawler. Fight as the Rangers in their civilian forms before morphing. Features 2-player co-op and levels inspired by the movie''s key locations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mighty-morphin-power-rangers---the-movie-usa', 'SNES', 'Mighty Morphin Power Rangers - The Movie (USA)', '1995', 'Action', 'Gray Matter', '1', 'Beat ''em Up', 'Side-scrolling beat ''em up based on the 1995 feature film.', 'Team up to defeat the Ooze and save the city.', 'Join the action in Power Rangers: The Movie on SNES.', 'Master the 16-bit combat across two planes of action (foreground and background). A fast-paced licensed title with great music and satisfying superhero combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mighty-morphin-power-rangers-europe', 'SNES', 'Mighty Morphin Power Rangers (Europe)', '1994', 'Action', 'Natsume', '1', 'Action Platformer', 'Side-scrolling action-platformer based on the first season.', 'Defeat Rita Repulsa''s monsters and protect Earth.', 'Become a Ranger in Mighty Morphin Power Rangers on SNES.', 'The classic 16-bit action game. Play as your favorite Ranger, fight Putty Patrollers, and engage in epic boss battles that conclude with a giant Megazord fight.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mighty-morphin-power-rangers-japan', 'SNES', 'Mighty Morphin Power Rangers (Japan)', '1994', 'Action', 'Natsume', '1', 'Action Platformer', 'Side-scrolling action-platformer based on the first season.', 'Experience the original Japanese release of the Ranger saga.', 'Play Kyuuryuu Sentai Zyuranger style on Super Famicom.', 'The foundational 16-bit release of the Power Rangers hit. Features bright, colorful graphics and a difficulty curve that is perfect for fans of the iconic TV show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mighty-morphin-power-rangers-usa', 'SNES', 'Mighty Morphin Power Rangers (USA)', '1994', 'Action', 'Natsume', '1', 'Action Platformer', 'Side-scrolling action-platformer based on the first season.', 'Defeat Rita Repulsa''s monsters and protect Earth.', 'Become a Ranger in Mighty Morphin Power Rangers on SNES.', 'Master each Ranger''s unique weapon. A definitive 16-bit action title that captures the spirit of the show with great sprites and an iconic rock-infused soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('milandra-japan', 'SNES', 'Milandra (Japan)', '1997', 'RPG', 'ASCII', '1', 'Turn-Based RPG', 'Roguelike-style dungeon crawler with puzzle elements.', 'Navigate the mysterious tower and find the legendary treasure.', 'Explore the dungeons of Milandra on the Super Famicom.', 'A 16-bit tactical RPG where every step counts. Manage your resources and equipment while exploring randomly generated floors filled with traps and dangerous creatures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('militia-japan', 'SNES', 'Militia (Japan)', '1997', 'Strategy', 'ASCII', '1', 'Tactical Strategy', 'Tactical grid-based strategy game with a military theme.', 'Deploy your units to capture enemy bases and win the war.', 'Master strategy in Militia on the Super Famicom.', 'A deep 16-bit tactical sim. Manage tanks, infantry, and air support in turn-based battles that require careful positioning and resource management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mini-yonku-lets-&-go!!---power-wgp-2-japan', 'SNES', 'Mini Yonku Let''s & Go!! - Power WGP 2 (Japan)', '1997', 'Racing', 'Atelier Double', '2', 'Slot Car Racing', 'Mini-4WD racing simulation and RPG adventure.', 'Build the ultimate racing car and win the World Grand Prix 2.', 'Race for glory in Mini Yonku Let''s & Go!! on SNES.', 'A 16-bit racing sim based on the popular anime. Customize your car''s motor, tires, and chassis to dominate the high-speed tracks in this technical sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mini-yonku-shining-scorpion---lets-&-go!!-japan', 'SNES', 'Mini Yonku Shining Scorpion - Let''s & Go!! (Japan)', '1996', 'Racing', 'Atelier Double', '2', 'Slot Car Racing', 'Mini-4WD racing simulation featuring the Shining Scorpion car.', 'Customize your racer to win the national championships.', 'Experience Mini Yonku Shining Scorpion on Super Famicom.', 'Features deep 16-bit customization options. Balance speed and stability to survive the loops and jumps of professional Mini-4WD racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minor-fixes-for-mortal-kombat-ii', 'SNES', 'Minor fixes for Mortal Kombat II', '1994', 'Fighting', 'Midway', '2', 'Competitive Fighting', 'Technical romhack fixing bugs in the original Mortal Kombat II.', 'Enjoy a more balanced and bug-free version of the arcade hit.', 'Play Mortal Kombat II (Minor Fixes) on the SNES.', 'A 16-bit "Quality of Life" hack that corrects character palettes, fixes move-priority glitches, and polishes the overall gameplay for a smoother experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('miracle-casino-paradise-japan', 'SNES', 'Miracle Casino Paradise (Japan)', '1994', 'Gambling', 'Marionette', '1', 'Casino Simulation', 'Casino simulation featuring a wide variety of gambling games.', 'Build your fortune and become the king of the virtual casino.', 'Test your luck in Miracle Casino Paradise on Super Famicom.', 'Features 16-bit renditions of Slots, Roulette, and Baccarat. Includes a story mode where you navigate the casino world and build your reputation as a high-roller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('miracle-girls-japan', 'SNES', 'Miracle Girls (Japan)', '1993', 'Adventure', 'Now Production', '1', 'Visual Novel', 'Puzzle-platformer based on the shoujo anime and manga.', 'Use magical powers to rescue your friends and clear levels.', 'Join the adventure in Miracle Girls on the Super Famicom.', 'A charming 16-bit platformer starring twin sisters Tomomi and Mikage. Use magical candies to transform and overcome obstacles in a colorful, whimsical world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('miracle-girls-japan-en-by-rpgone-v10', 'SNES', 'Miracle Girls (Japan) [En by RPGOne v1.0]', '1993', 'Adventure', 'Now Production', '1', 'Visual Novel', 'Puzzle-platformer with a full English fan translation.', 'Experience the Miracle Girls'' journey with English text.', 'Play Miracle Girls in English on the Super Nintendo.', 'The RPGOne translation makes this 16-bit gem accessible. Follow the lighthearted story and master the sisters'' unique abilities in your own language.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('miracle-piano-teaching-system-the-usa', 'SNES', 'Miracle Piano Teaching System, The (USA)', '1991', 'Educational', 'The Learning Company', '1', 'Music Education', 'Educational music software for learning the piano.', 'Learn to play real music using the SNES and the Miracle keyboard.', 'Learn piano with The Miracle Piano Teaching System on SNES.', 'A unique 16-bit educational tool. Combined with a special MIDI keyboard, it provides interactive lessons and games to teach rhythm, notes, and music theory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('miyaji-shachou-no-pachinko-fan---shouri-sengen-2-japan', 'SNES', 'Miyaji Shachou no Pachinko Fan - Shouri Sengen 2 (Japan)', '1996', 'Gambling', 'KSS', '1', 'Pachinko Simulation', 'Pachinko simulation featuring diverse machines and themes.', 'Master the art of Pachinko to win big and please the boss.', 'Play Pachinko Fan: Shouri Sengen 2 on Super Famicom.', 'A realistic 16-bit simulation of Japanese Pachinko parlors. Features multiple machines with different payout rates and colorful, animated mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mizuki-shigeru-no-youkai-hyakkiyakou-japan', 'SNES', 'Mizuki Shigeru no Youkai Hyakkiyakou (Japan)', '1994', 'Action', 'Soft Vision', '1', 'Action Adventure', 'Traditional board game simulation based on Japanese folklore.', 'Navigate the world of Youkai and collect legendary creatures.', 'Discover Mizuki Shigeru no Youkai Hyakkiyakou on SNES.', 'A 16-bit digital board game based on the art of Shigeru Mizuki. Learn about Japanese mythology while competing against rivals in a colorful, supernatural world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mlbpa-baseball-usa', 'SNES', 'MLBPA Baseball (USA)', '1994', 'Sports', 'EA Sports', '2', 'Baseball Simulation', 'Realistic baseball simulation featuring MLBPA players.', 'Lead your favorite team to victory with licensed player data.', 'Play MLBPA Baseball on the Super Nintendo.', 'Features the full 1994 MLBPA roster. A solid 16-bit sports title with smooth pitching and batting mechanics and comprehensive seasonal statistics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mohawk-&-headphone-jack-europe', 'SNES', 'Mohawk & Headphone Jack (Europe)', '1995', 'Action', 'Sculptured Software', '1', 'Run and Gun', 'High-speed 360-degree rotating platformer.', 'Recover your lost CDs and navigate the morphing environments.', 'Experience the trippy Mohawk & Headphone Jack on SNES.', 'A 16-bit technical showcase. The entire world rotates around the character, creating a dizzying and unique platforming experience with a heavy focus on speed and music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mohawk-&-headphone-jack-usa', 'SNES', 'Mohawk & Headphone Jack (USA)', '1995', 'Action', 'Sculptured Software', '1', 'Run and Gun', 'High-speed 360-degree rotating platformer.', 'Recover your lost CDs and navigate the morphing environments.', 'Experience the trippy Mohawk & Headphone Jack on SNES.', 'Master the 16-bit gravity-defying jumps and transformations. Use power-ups to morph your character and survive the psychedelic, fast-paced levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moltov-mario-world', 'SNES', 'Moltov Mario World', '2019', 'Platformer', 'Fanmade', '1', 'ROM Hack Platformer', 'Challenging fan-made Super Mario World romhack.', 'Survive a series of punishing levels in this "Kaizo-lite" quest.', 'Challenge Moltov Mario World on the Super Nintendo.', 'A 16-bit romhack designed for veteran players. Features creative platforming obstacles, custom palettes, and a high difficulty curve that rewards precision.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('momotarou-dentetsu-happy-japan', 'SNES', 'Momotarou Dentetsu Happy (Japan)', '1996', 'Board Game', 'Hudson Soft', '4', 'Party Board Game', 'Railway-themed digital board game and business sim.', 'Build the most successful train empire across Japan.', 'Play Momotarou Dentetsu Happy on the Super Famicom.', 'The ultimate 16-bit family board game. Buy properties, manage your finances, and avoid the God of Poverty in this colorful and addictive business simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monopoly-japan', 'SNES', 'Monopoly (Japan)', '1992', 'Board Game', 'Tonkin House', '4', 'Digital Board Game', 'The classic property-trading board game for the SNES.', 'Bankrupt your opponents and own the most famous Japanese cities.', 'Play Monopoly on the Super Famicom.', 'A 16-bit digital version of the world''s most famous board game. Features localized Japanese properties and smooth animations for a fun family experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monopoly-usa', 'SNES', 'Monopoly (USA)', '1992', 'Board Game', 'Tonkin House', '4', 'Digital Board Game', 'The classic property-trading board game for the SNES.', 'Buy, sell, and trade your way to a total monopoly.', 'Play the classic Monopoly on the Super Nintendo.', 'Features colorful 16-bit graphics and customizable house rules. Play against the AI or up to four friends in this faithful digital adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monopoly-usa-rev-a', 'SNES', 'Monopoly (USA) (Rev A)', '1992', 'Board Game', 'Tonkin House', '4', 'Digital Board Game', 'The classic property-trading board game (Updated Revision).', 'Master the market in this refined 16-bit version.', 'Play Monopoly (Rev A) for the Super Nintendo.', 'An updated 16-bit revision that fixes minor UI bugs and improves the AI''s trading logic for a more competitive and fair gaming experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monopoly-game-2-the-japan', 'SNES', 'Monopoly Game 2, The (Japan)', '1995', 'Board Game', 'Tonkin House', '4', 'Digital Board Game', 'Expanded digital board game sequel with more features.', 'Build your real estate empire in this polished sequel.', 'Experience The Monopoly Game 2 on the Super Famicom.', 'Features improved 16-bit graphics and new character avatars. Offers more complex AI and a wider variety of board events for a fresh take on the classic formula.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monstania-japan', 'SNES', 'Monstania (Japan)', '1992', 'Action', 'Riverhillsoft', '1', 'Action RPG', 'Isometric tactical RPG with a focus on speed and puzzles.', 'Lead Fron and Tia to save the world in this fast-paced epic.', 'Discover the beautiful Monstania on the Super Famicom.', 'A 16-bit tactical gem. Features unique grid-based combat where movement and strategy are key. Known for its gorgeous pixel art and emotional storytelling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monstania-japan-en-by-aeon-genesis-v103', 'SNES', 'Monstania (Japan) [En by Aeon Genesis v1.03]', '1992', 'Action', 'Riverhillsoft', '1', 'Action RPG', 'Isometric tactical RPG with a full English fan translation.', 'Experience the story of Monstania with English text.', 'Play Monstania in English on the Super Nintendo.', 'The Aeon Genesis translation makes this 16-bit tactical RPG accessible. Master the strategic combat and enjoy the heartwarming narrative in your own language.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-maker-iii---hikari-no-majutsushi-japan', 'SNES', 'Monster Maker III - Hikari no Majutsushi (Japan)', '1993', 'RPG', 'Soft Vision', '1', 'Turn-Based RPG', 'Traditional turn-based JRPG based on the card game series.', 'Stop the dark sorcerer and master the art of monster summoning.', 'Explore Monster Maker III on the Super Famicom.', 'A polished 16-bit RPG featuring a unique card-inspired magic system. Build your party with diverse fantasy races and explore a vibrant world filled with dungeons and secrets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-maker-kids---ousama-ni-naritai-japan', 'SNES', 'Monster Maker Kids - Ousama ni Naritai (Japan)', '1994', 'RPG', 'Soft Vision', '1', 'Child-Friendly RPG', 'Strategy-RPG spinoff with a focus on younger audiences.', 'Help the young heroes complete trials to become the new king.', 'Play Monster Maker Kids on the Super Famicom.', 'A charming 16-bit tactical RPG. Features simplified mechanics, bright "chibi" art style, and engaging turn-based battles perfect for fans of the Monster Maker universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat---red-blood-and-easy-moves', 'SNES', 'Mortal Kombat - Red Blood and Easy Moves', '1993', 'Fighting', 'Midway', '2', 'Competitive Fighting', 'Action-heavy fighting game with restored blood and simplified inputs.', 'Defeat Shang Tsung with maximum gore and easier combos.', 'Play Mortal Kombat: Red Blood Edition on the SNES.', 'A 16-bit fan hack that fixes the "sweat" censorship of the original SNES port. Restores red blood and fatalities while making special moves easier to execute.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat---shinken-kourin-densetsu-japan', 'SNES', 'Mortal Kombat - Shinken Kourin Densetsu (Japan)', '1993', 'Fighting', 'Midway', '2', 'Competitive Fighting', 'One-on-one fighting game with digitized sprites (Japanese release).', 'Win the Shaolin tournament in the official Japanese version.', 'Experience Mortal Kombat on the Super Famicom.', 'The 16-bit Japanese port of the arcade phenomenon. Known for its realistic digitized fighters and the unique "sweat" effects used to pass local censorship boards.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-europe', 'SNES', 'Mortal Kombat (Europe)', '1993', 'Fighting', 'Midway', '2', 'Competitive Fighting', 'One-on-one fighting game that defined the 90s arcade scene.', 'Defeat the Outworld sorcerer Shang Tsung to save Earthrealm.', 'Play the legendary Mortal Kombat for the SNES.', 'A landmark 16-bit title. Master the moves of Scorpion, Sub-Zero, and Rayden. Features smooth animations and the iconic (though censored) finishing moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-europe-beta', 'SNES', 'Mortal Kombat (Europe) (Beta)', '1993', 'Fighting', 'Midway', '2', 'Competitive Fighting', 'One-on-one fighting game (Early European build).', 'Test the initial character balancing and move sets.', 'Check out the Mortal Kombat Beta on the SNES.', 'A rare 16-bit development build. Witness the fine-tuning of the projectile speeds and the early implementation of the background stages from the arcade.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-europe-rev-a', 'SNES', 'Mortal Kombat (Europe) (Rev A)', '1993', 'Fighting', 'Midway', '2', 'Competitive Fighting', 'One-on-one fighting game (Updated European Revision).', 'Defeat Goro in this polished 16-bit revision.', 'Play Mortal Kombat (Rev A) on the Super Nintendo.', 'An updated 16-bit version that fixes minor graphical glitches and improves the AI behavior for a more consistent challenge compared to the initial release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-usa', 'SNES', 'Mortal Kombat (USA)', '1993', 'Fighting', 'Midway', '2', 'Competitive Fighting', 'One-on-one fighting game featuring digitized martial artists.', 'Enter the tournament and master the secret "Fatality" moves.', 'Experience Mortal Kombat on the Super Nintendo.', 'The game that sparked a revolution. While censored for blood, it features superior sound and graphics compared to other 16-bit ports of the era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-3---redux', 'SNES', 'Mortal Kombat 3 - Redux', '1995', 'Fighting', 'Midway', '2', 'Competitive Fighting', 'Enhanced fan-made version of the third Mortal Kombat entry.', 'Experience a more arcade-accurate version of MK3.', 'Play Mortal Kombat 3: Redux on the SNES.', 'A 16-bit overhaul that adds missing frames of animation, improves character palettes, and balances the gameplay to feel closer to the Ultimate arcade experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-3-europe', 'SNES', 'Mortal Kombat 3 (Europe)', '1995', 'Fighting', 'Midway', '2', 'Competitive Fighting', 'Fast-paced fighting game introducing the "Run" button and combos.', 'Defeat Shao Kahn''s invasion forces in the European version.', 'Battle in Mortal Kombat 3 for the Super Nintendo.', 'Features a massive roster including Cyrax, Sektor, and Sheeva. This 16-bit port is remarkably faithful to the arcade, including the complex "Dial-a-combo" system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-3-europe-beta', 'SNES', 'Mortal Kombat 3 (Europe) (Beta)', '1995', 'Fighting', 'Midway', '2', 'Competitive Fighting', 'Fast-paced fighting game (Early European build).', 'Explore early stage designs and character combos.', 'Check out the Mortal Kombat 3 Beta on the SNES.', 'A pre-release 16-bit look at the third entry. Witness the evolution of the urban stages and the balancing of the new robotic ninja characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-3-jul-13-1995-prototype', 'SNES', 'Mortal Kombat 3 (Jul 13, 1995 prototype)', '1995', 'Fighting', 'Midway', '2', 'Competitive Fighting', 'Fast-paced fighting game (Rare mid-development build).', 'Test the mechanics from the July 1995 prototype.', 'Explore the MK3 July Prototype on the SNES.', 'An insightful 16-bit development slice. Features unpolished menus, incomplete sound sets, and experimental timing for the newly introduced run mechanic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-3-usa', 'SNES', 'Mortal Kombat 3 (USA)', '1995', 'Fighting', 'Midway', '2', 'Competitive Fighting', 'Fast-paced fighting game introducing the "Run" button and combos.', 'Stop Shao Kahn from merging Earthrealm with Outworld.', 'Experience Mortal Kombat 3 on the Super Nintendo.', 'Master the 16-bit fatalities and the new "Animalities." A high-energy fighter that pushed the SNES hardware with large sprites and multi-layered backgrounds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-3-usa-beta', 'SNES', 'Mortal Kombat 3 (USA) (Beta)', '1995', 'Fighting', 'Midway', '2', 'Competitive Fighting', 'Fast-paced fighting game (Early North American build).', 'Test the "Kombat Kodes" and character finishers.', 'Check out the Mortal Kombat 3 Beta on the SNES.', 'A 16-bit development build focused on bug-testing the secret codes and the interactive stage transitions that allowed players to uppercut through ceilings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-champion-edition', 'SNES', 'Mortal Kombat Champion Edition', '1993', 'Fighting', 'Midway', '2', 'Competitive Fighting', 'Fan-made "best of" edition of the Mortal Kombat series.', 'Fight with an expanded roster and unlocked secrets.', 'Play Mortal Kombat: Champion Edition on SNES.', 'A 16-bit fan project that aims to create the ultimate MK experience. Features modified character stats, unlocked sub-bosses, and various gameplay refinements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-ii---hidden-characters-playable', 'SNES', 'Mortal Kombat II - Hidden Characters Playable', '1994', 'Fighting', 'Midway', '2', 'Competitive Fighting', 'Gameplay modification allowing play as non-selectable fighters.', 'Play as Jade, Smoke, and Noob Saibot in the main game.', 'Play as hidden characters in Mortal Kombat II on SNES.', 'A 16-bit hack that makes the legendary "secret" opponents fully playable. Features unique move sets for the hidden ninjas within the standard MK2 roster.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-ii---kyuukyoku-shinken-japan', 'SNES', 'Mortal Kombat II - Kyuukyoku Shinken (Japan)', '1994', 'Fighting', 'Midway', '2', 'Competitive Fighting', 'One-on-one fighting game (Japanese release of the sequel).', 'Defeat Shao Kahn in the official Japanese version.', 'Experience Mortal Kombat II on the Super Famicom.', 'The 16-bit Japanese port. Unlike the first game, this version features full red blood and all the gruesome fatalities that made the sequel an international hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-ii-europe', 'SNES', 'Mortal Kombat II (Europe)', '1994', 'Fighting', 'Midway', '2', 'Competitive Fighting', 'One-on-one fighting game widely considered the series'' peak.', 'Travel to Outworld to defeat the emperor Shao Kahn.', 'Play Mortal Kombat II for the Super Nintendo.', 'A 16-bit masterpiece. Features more characters, multi-layered fatalities (Friendships and Babalities), and some of the best digitized graphics on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-ii-europe-rev-a', 'SNES', 'Mortal Kombat II (Europe) (Rev A)', '1994', 'Fighting', 'Midway', '2', 'Competitive Fighting', 'One-on-one fighting game (Updated European Revision).', 'Master the Outworld tournament in this refined version.', 'Play Mortal Kombat II (Rev A) on the SNES.', 'An updated 16-bit revision that fixes several infinite combo glitches and polishes the sound effects for a more arcade-perfect experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-ii-usa', 'SNES', 'Mortal Kombat II (USA)', '1994', 'Fighting', 'Midway', '2', 'Competitive Fighting', 'One-on-one fighting game widely considered the series'' peak.', 'Travel to Outworld to defeat the emperor Shao Kahn.', 'Play Mortal Kombat II for the Super Nintendo.', 'The definitive 16-bit fighting experience for many. Features a rich roster, atmospheric stages, and the perfected Mortal Kombat combat loop.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-ii-usa-rev-a', 'SNES', 'Mortal Kombat II (USA) (Rev A)', '1994', 'Fighting', 'Midway', '2', 'Competitive Fighting', 'One-on-one fighting game (Updated North American Revision).', 'Defeat the Kintaro and Shao Kahn in this polished version.', 'Play Mortal Kombat II (Rev A) on the SNES.', 'The final 16-bit US revision. Fixes several stability issues and adjusts the difficulty of the AI opponents to be more challenging and fair.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-ii-characters-secrets', 'SNES', 'Mortal Kombat II Characters Secrets', '1997', 'Action', 'Midway', '1', 'Action Adventure', 'Technical guide and cheat menu modification for MK2.', 'Quickly access all character fatalities and secret moves.', 'Discover Mortal Kombat II Secrets on the SNES.', 'A 16-bit utility hack that adds an in-game menu or modified screens to help players execute the complex inputs for every character''s hidden moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-mythologies-gold-2000', 'SNES', 'Mortal Kombat Mythologies Gold 2000', '2000', 'Action', 'Midway', '1', 'Action Adventure', 'Unofficial "demake" or pirate-style fighting game.', 'Battle through a unique 16-bit interpretation of Sub-Zero''s story.', 'Experience MK Mythologies Gold 2000 on the SNES.', 'A rare and bizarre 16-bit pirate title. Attempts to bring the 3D action of Mythologies into a 2D fighting engine, resulting in a unique (if unpolished) gameplay experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mother-2---gyiyg-no-gyakushuu-japan', 'SNES', 'Mother 2 - Gyiyg no Gyakushuu (Japan)', '1994', 'RPG', 'Ape Inc. / HAL Laboratory', '1', 'Turn-Based RPG', 'Modern-day turn-based JRPG with a quirky and emotional story.', 'Lead Ness and his friends to stop the alien threat of Giygas.', 'Experience the legendary Mother 2 on the Super Famicom.', 'The Japanese original of EarthBound. A 16-bit masterpiece known for its psychedelic battle backgrounds, satirical humor, and a heartwarming adventure across a modern world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mother-2-deluxe-20', 'SNES', 'Mother 2 Deluxe 2.0', '2023', 'RPG', 'Fan Project', '1', 'Enhanced RPG', 'Enhanced fan-made overhaul of EarthBound.', 'Play through a rebalanced and expanded version of Ness''s quest.', 'Experience Mother 2 Deluxe 2.0 on the SNES.', 'A massive 16-bit "definitive edition" mod. Features expanded dialogue, rebalanced difficulty, new items, and bug fixes that enhance the classic EarthBound experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('motoko-chan-no-wonder-kitchen-japan', 'SNES', 'Motoko-chan no Wonder Kitchen (Japan)', '1993', 'Action', 'Athena', '1', 'Action Puzzle', 'Educational cooking simulation sponsored by Ajinomoto.', 'Learn real-world cooking tips and trivia with Motoko-chan.', 'Discover Motoko-chan no Wonder Kitchen on the SNES.', 'A rare 16-bit promotional title. Point and click to interact with kitchen appliances and ingredients while learning about the history of food in a cute, animated setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('motteke-oh!-dorobou-japan', 'SNES', 'Motteke Oh! Dorobou (Japan)', '1993', 'Action', 'Data East', '1', 'Action Platformer', 'Multiplayer board-game and action hybrid with a thievery theme.', 'Outsmart your rivals and steal the most treasure to win.', 'Play the quirky Motteke Oh! Dorobou on Super Famicom.', 'A fast-paced 16-bit party game. Compete against friends to navigate maps, set traps, and pull off heists in a vibrant and humorous cartoon world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mountain-bike-rally-usa', 'SNES', 'Mountain Bike Rally (USA)', '1991', 'Racing', 'Visual Concepts', '2', 'Arcade Racing', 'Mountain bike racing simulation using Mode 7 for 3D effects.', 'Win the cross-country rally and upgrade your mountain bike.', 'Race the trails in Mountain Bike Rally for the SNES.', 'Also known as Cannondale Cup. Features 16-bit terrain scaling, stamina management, and diverse outdoor tracks ranging from forests to rocky mountains.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mouryou-senki-madara-2-japan', 'SNES', 'Mouryou Senki Madara 2 (Japan)', '1994', 'Action', 'KONAMI', '1', 'Action RPG', 'Top-down turn-based JRPG based on the popular manga/anime.', 'Defeat the demon army and reclaim your stolen body parts.', 'Explore the dark Mouryou Senki Madara 2 on SNES.', 'A visually impressive 16-bit RPG. Features an automated battle system with tactical input and a mature, dark fantasy story accompanied by a stellar soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-nutz-europe-enfr', 'SNES', 'Mr Nutz (Europe) (En,Fr)', '1993', 'Platformer', 'Ocean', '2', 'Cute Platformer', 'Vibrant side-scrolling platformer starring a red squirrel.', 'Stop the evil Yeti from freezing the world.', 'Join the adventure in Mr. Nutz for the Super Nintendo.', 'A polished 16-bit platformer with lush forest and winter backgrounds. Use your tail-spin attack and jump on enemies to save the world from an eternal ice age.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-nutz-japan', 'SNES', 'Mr Nutz (Japan)', '1993', 'Platformer', 'Ocean', '2', 'Cute Platformer', 'Vibrant side-scrolling platformer starring a red squirrel.', 'Defeat the Yeti in the original Japanese version.', 'Experience Mr. Nutz on the Super Famicom.', 'Known for its incredibly detailed 16-bit pixel art and catchy music. A classic "mascot" platformer that rewards exploration and precise jumping.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-nutz-usa-enfr', 'SNES', 'Mr Nutz (USA) (En,Fr)', '1993', 'Platformer', 'Ocean', '2', 'Cute Platformer', 'Vibrant side-scrolling platformer starring a red squirrel.', 'Stop the evil Yeti from freezing the world.', 'Join the adventure in Mr. Nutz for the Super Nintendo.', 'Master the 16-bit platforming challenges. Features multiple themed worlds, challenging boss fights, and some of the most colorful graphics of the era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-nutz-usa-enfr-beta', 'SNES', 'Mr Nutz (USA) (En,Fr) (Beta)', '1993', 'Platformer', 'Ocean', '2', 'Cute Platformer', 'Vibrant side-scrolling platformer (Pre-release build).', 'Explore early level designs and squirrel animations.', 'Check out the Mr. Nutz Beta on the Super Nintendo.', 'A rare 16-bit development build. Witness the fine-tuning of the physics and the evolution of the vibrant environmental assets before the final release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-do!-europe', 'SNES', 'Mr. Do! (Europe)', '1992', 'Arcade', 'Namco', '2', 'Classic Arcade', 'Arcade-style puzzle game featuring a clown and falling fruits.', 'Clear each level by digging tunnels and dropping apples on enemies.', 'Play the classic Mr. Do! on the Super Nintendo.', 'A faithful 16-bit port of the arcade legend. Use your power ball to defeat monsters and collect all the cherries to advance through increasingly difficult stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-do!-japan', 'SNES', 'Mr. Do! (Japan)', '1992', 'Arcade', 'Namco', '2', 'Classic Arcade', 'Arcade-style puzzle game featuring a clown and falling fruits.', 'Collect cherries and clear the board in the Japanese version.', 'Experience Mr. Do! on the Super Famicom.', 'Features the same addictive 16-bit gameplay that made the arcade version a hit. Strategy is key as you time your apple drops to crush multiple enemies at once.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-do!-usa', 'SNES', 'Mr. Do! (USA)', '1992', 'Arcade', 'Namco', '2', 'Classic Arcade', 'Arcade-style puzzle game featuring a clown and falling fruits.', 'Clear each level by digging tunnels and dropping apples on enemies.', 'Play the classic Mr. Do! on the Super Nintendo.', 'A colorful 16-bit reimagining of the classic. Includes a variety of stages and the famous "EXTRA" monster mechanic for bonus lives.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-tuff-europe-enfrdeesit-proto-1994-12-05', 'SNES', 'Mr. Tuff (Europe) (En,Fr,De,Es,It) (Proto) (1994-12-05)', '1994', 'Platformer', 'Ocean', '2', 'Action Platformer', 'Action-platformer starring a powerful construction robot (Prototype).', 'Stop the army of rogue robots in this unreleased 16-bit epic.', 'Check out the Mr. Tuff Proto for the Super Nintendo.', 'A high-quality 16-bit prototype. Features large sprites and a variety of gadgets for the protagonist to use in a polished industrial world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-tuff-usa-enfrde-proto-1994-07-12', 'SNES', 'Mr. Tuff (USA) (En,Fr,De) (Proto) (1994-07-12)', '1994', 'Platformer', 'Ocean', '2', 'Action Platformer', 'Action-platformer starring a powerful construction robot (Prototype).', 'Test early level layouts and robot physics in this North American build.', 'Explore the Mr. Tuff Beta on the SNES.', 'A pre-release 16-bit look at a game that was nearly finished. Features impressive environmental destruction and smooth robot animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ms-pac-man-europe', 'SNES', 'Ms. Pac-Man (Europe)', '1996', 'Arcade', 'Namco', '2', 'Classic Arcade', 'Arcade-perfect maze-chase game featuring the iconic heroine.', 'Eat all the dots while avoiding the four colorful ghosts.', 'Play Ms. Pac-Man for the Super Nintendo.', 'A 16-bit update to the arcade classic. Features multiple maze layouts, improved graphics, and the same addictive gameplay that made the original a legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ms-pac-man-namco-for-snes-europe', 'SNES', 'Ms. Pac-Man (Namco) for SNES (Europe)', '1996', 'Arcade', 'Namco', '2', 'Classic Arcade', 'Arcade-perfect maze-chase game (Namco specialized version).', 'Clear the mazes in this high-quality Namco-published port.', 'Experience Namco''s Ms. Pac-Man on the SNES.', 'A polished 16-bit rendition featuring smooth movement and vibrant colors. Master the patterns of the ghosts and use power pellets to turn the tables.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ms-pac-man-namco-for-snes-usa', 'SNES', 'Ms. Pac-Man (Namco) for SNES (USA)', '1996', 'Arcade', 'Namco', '2', 'Classic Arcade', 'Arcade-perfect maze-chase game (Namco specialized version).', 'Clear the mazes and achieve the highest possible score.', 'Experience Namco''s Ms. Pac-Man on the SNES.', 'Includes various game modes and speed settings. A definitive 16-bit way to experience the world''s most famous female gaming icon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ms-pac-man-usa', 'SNES', 'Ms. Pac-Man (USA)', '1996', 'Arcade', 'Namco', '2', 'Classic Arcade', 'Arcade-perfect maze-chase game featuring the iconic heroine.', 'Eat all the dots while avoiding the four colorful ghosts.', 'Play Ms. Pac-Man for the Super Nintendo.', 'Features the classic Intermission scenes and iconic 16-bit sound effects. A nostalgic and perfectly executed port for fans of the golden age of arcades.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('muhammad-ali-heavyweight-boxing-usa-proto', 'SNES', 'Muhammad Ali Heavyweight Boxing (USA) (Proto)', '1993', 'Sports', 'Razorsoft', '1', 'Boxing Simulation', 'Realistic heavyweight boxing simulation (Prototype).', 'Climb the rankings and win the title as Muhammad Ali.', 'Check out the Muhammad Ali Boxing Proto on SNES.', 'A 16-bit sports prototype featuring large character sprites and a focus on tactical punching. Experience an unreleased take on the "Greatest of All Time."');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mujintou-monogatari-japan', 'SNES', 'Mujintou Monogatari (Japan)', '1996', 'RPG', 'Chunsoft', '1', 'Survival RPG', 'Island survival adventure and management simulation.', 'Lead a group of survivors to escape the deserted island.', 'Survive in Mujintou Monogatari on the Super Famicom.', 'A unique 16-bit simulation. Manage resources, explore the terrain, and build tools to ensure the survival of your team in a challenging island environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('multi-play-volleyball-japan', 'SNES', 'Multi Play Volleyball (Japan)', '1994', 'Sports', 'Human Entertainment', '2', 'Arcade Sports', 'Fast-paced volleyball simulation with a focus on multiplayer.', 'Win the national volleyball tournament through teamwork.', 'Kick off the action in Multi Play Volleyball on SNES.', 'Features smooth 16-bit animations and responsive controls. Play with up to four players in intense matches that require perfect timing for spikes and blocks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('muscle-bomber---the-body-explosion-japan', 'SNES', 'Muscle Bomber - The Body Explosion (Japan)', '1993', 'Fighting', 'Capcom', '2', 'Competitive Fighting', 'Arcade-style wrestling game featuring Capcom''s iconic characters.', 'Win the CWA world title in this high-octane brawler.', 'Experience Muscle Bomber on the Super Famicom.', 'Known as Saturday Night Slam Masters in the West. Features 16-bit character designs by Tetsuo Hara and a unique blend of wrestling and fighting game mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('musya-usa', 'SNES', 'Musya (USA)', '1992', 'Action', 'Sigma Enterprises', '1', 'Run and Gun', 'Atmospheric side-scrolling action game with a Kabuki theme.', 'Descend into the underworld to rescue your beloved and defeat demons.', 'Play the dark action-platformer Musya on the SNES.', 'A 16-bit title with a unique Japanese horror aesthetic. Control a spear-wielding hero through eerie caves and temples, fighting folklore-inspired monsters with magical scrolls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-qldc-level-qldc-2023', 'SNES', 'My QLDC Level (QLDC 2023)', '2023', 'Platformer', 'Fan Project', '1', 'Custom Level', 'Fan-made Mario World level compilation from the 2023 contest.', 'Navigate through the most creative custom levels of the year.', 'Play the QLDC 2023 Level pack on the SNES.', 'A modern 16-bit romhack showcasing high-level design from the Quest Level Design Contest. Features custom music, innovative mechanics, and challenging platforming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mystery-circle-japan', 'SNES', 'Mystery Circle (Japan)', '1994', 'RPG', 'Use', '1', 'Turn-Based RPG', 'Unique strategy-puzzle game with a sci-fi board game feel.', 'Clear the board by strategically moving pieces and solving puzzles.', 'Experience Mystery Circle on the Super Famicom.', 'A rare 16-bit logic game. Navigate circular boards and outmaneuver the AI or a friend in this minimalist yet deep strategic puzzle experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mystic-ark-japan', 'SNES', 'Mystic Ark (Japan)', '1995', 'RPG', 'Produce!', '1', 'Turn-Based RPG', 'Deep turn-based RPG with an emphasis on atmosphere and puzzles.', 'Recover the seven Arks to restore your world and identity.', 'Explore the mysterious Mystic Ark on the Super Famicom.', 'The spiritual successor to The 7th Saga. Features beautiful 16-bit pixel art, a somber tone, and a unique system where you possess statues to build your party.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mystic-ark-japan-en-by-aeon-genesis-v101', 'SNES', 'Mystic Ark (Japan) [En by Aeon Genesis v1.01]', '1995', 'RPG', 'Produce!', '1', 'Turn-Based RPG', 'Deep turn-based RPG with a full English fan translation.', 'Experience the haunting story of Mystic Ark with English text.', 'Play Mystic Ark in English on the Super Nintendo.', 'The Aeon Genesis translation makes this late-gen 16-bit masterpiece accessible. Solve environmental puzzles and survive tough battles in a beautifully desolate world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mystic-ark-japan-en-by-dynamic-designs-v10', 'SNES', 'Mystic Ark (Japan) [En by Dynamic Designs v1.0]', '1995', 'RPG', 'Produce!', '1', 'Turn-Based RPG', 'Deep turn-based RPG with an alternative English fan translation.', 'Experience the world of Arks with the Dynamic Designs script.', 'Play Mystic Ark in English on the Super Nintendo.', 'An alternative 16-bit translation that offers a different take on the game''s poetic and mysterious dialogue. Perfect for fans of deep, story-driven JRPGs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mystic-quest-legend-europe', 'SNES', 'Mystic Quest Legend (Europe)', '1992', 'RPG', 'Square', '1', 'Action RPG', 'Entry-level JRPG featuring simplified mechanics and a great OST.', 'Defeat the Dark King and restore the crystals of the world.', 'Play Mystic Quest Legend for the Super Nintendo.', 'Known as Final Fantasy Mystic Quest in the US. A 16-bit adventure designed for beginners, featuring visible enemies on the map and a rock-heavy soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mystic-quest-legend-france', 'SNES', 'Mystic Quest Legend (France)', '1992', 'RPG', 'Square', '1', 'Action RPG', 'Entry-level JRPG with localized French text.', 'Save the world from the Dark King in the French version.', 'Jouez à Mystic Quest Legend en français sur le SNES.', 'The complete 16-bit RPG experience with localized French dialogue. Explore dungeons using tools like the axe and hookshot in this accessible adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mystic-quest-legend-germany', 'SNES', 'Mystic Quest Legend (Germany)', '1992', 'RPG', 'Square', '1', 'Action RPG', 'Entry-level JRPG with localized German text.', 'Restore the crystals in the official German version.', 'Spielen Sie Mystic Quest Legend auf Deutsch für das SNES.', 'One of the first 16-bit RPGs to be fully localized for the German market. Features a simplified battle system and a memorable quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nage-libre---seijaku-no-suishin-japan', 'SNES', 'Nage Libre - Seijaku no Suishin (Japan)', '1997', 'Adventure', 'Visit', '1', 'Visual Novel', 'Tactical strategy RPG featuring a cast of female pilots.', 'Lead your team to victory in grid-based futuristic combat.', 'Master strategy in Nage Libre on the Super Famicom.', 'A 16-bit tactical game with an anime aesthetic. Manage your units'' stats and equipment to overcome challenging scenarios in a post-apocalyptic world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nakajima-satoru-kanshuu-f-1-hero-94-japan', 'SNES', 'Nakajima Satoru Kanshuu F-1 Hero ''94 (Japan)', '1994', 'Racing', 'Varie', '1', 'Formula Racing', 'Professional F-1 racing simulation endorsed by Satoru Nakajima.', 'Win the world championship with realistic car tuning.', 'Experience F-1 Hero ''94 on the Super Famicom.', 'Features 16-bit Mode 7 scaling for high-speed racing. Includes real drivers and tracks from the 1994 season with a focus on technical simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nakano-kouichi-kanshuu---keirin-ou-japan', 'SNES', 'Nakano Kouichi Kanshuu - Keirin Ou (Japan)', '1993', 'Sports', 'Varie', '1', 'Cycling Simulation', 'Keirin bicycle racing simulation and betting game.', 'Master the track and win big on bicycle race wagering.', 'Play Keirin Ou on the Super Famicom.', 'A unique 16-bit sports title focusing on the Japanese sport of Keirin. Manage your stamina during races or try your luck in the comprehensive betting mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naki-no-ryuu---mahjong-hishouden-japan', 'SNES', 'Naki no Ryuu - Mahjong Hishouden (Japan)', '1992', 'Tabletop', 'Video System', '4', 'Mahjong', 'Mahjong simulation based on the high-stakes gambling manga.', 'Defeat the underworld masters at the Mahjong table.', 'Play Naki no Ryuu on the Super Famicom.', 'Features the iconic 16-bit art style of the manga. Experience intense, dramatic matches with high-stakes tension and character-driven storylines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('namcot-open-japan', 'SNES', 'Namcot Open (Japan)', '1991', 'Sports', 'Namco', '4', 'Golf Simulation', 'Professional golf simulation from the creators at Namco.', 'Master the 18-hole course and win the Namcot Open.', 'Tee off in Namcot Open on the Super Famicom.', 'A polished 16-bit golf game. Features smooth ball physics, varying wind conditions, and a variety of clubs to master across beautiful digital fairways.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nangoku-shounen-papuwa-kun-japan', 'SNES', 'Nangoku Shounen Papuwa-kun (Japan)', '1994', 'Action', 'Enix', '1', 'Action Platformer', 'Wacky action-platformer based on the comedic island anime.', 'Explore the island and defeat the bizarre invaders as Papuwa.', 'Join the fun in Nangoku Shounen Papuwa-kun on SNES.', 'A vibrant 16-bit title filled with surreal humor. Use your animal friends to overcome obstacles and fight eccentric bosses in a tropical setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nangoku-shounen-papuwa-kun-japan-en-by-fh-v10beta-incomplete', 'SNES', 'Nangoku Shounen Papuwa-kun (Japan) [En by FH v1.0Beta] (Incomplete)', '1994', 'Action', 'Enix', '1', 'Action Platformer', 'Wacky action-platformer with a partial English translation.', 'Experience the island comedy with English menus and text.', 'Play Papuwa-kun in English on the Super Nintendo.', 'A 16-bit fan translation project that helps navigate the menus and dialogue of this quirky and colorful Japanese action-adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruhodo!-the-world-japan', 'SNES', 'Naruhodo! The World (Japan)', '1995', 'Adventure', 'Taito', '1', 'Quiz Game', 'Trivia and board game based on the Japanese variety show.', 'Travel the world and answer questions to become the champion.', 'Play Naruhodo! The World on the Super Famicom.', 'A 16-bit digital board game that tests your global knowledge. Features mini-games and trivia based on the long-running television program.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('natsuki-crisis-battle-japan', 'SNES', 'Natsuki Crisis Battle (Japan)', '1992', 'Fighting', 'Taito', '2', 'Arcade Fighting', 'One-on-one fighting game based on the high school martial arts manga.', 'Win the tournament in this fast-paced school brawler.', 'Experience Natsuki Crisis Battle on the Super Famicom.', 'A hidden 16-bit gem. Features fluid animations, a unique stamina system, and a story mode that follows the manga''s intense martial arts battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('natsume-championship-wrestling-usa', 'SNES', 'Natsume Championship Wrestling (USA)', '1994', 'Wrestling', 'Natsume', '2', 'Sports Fighting', 'Professional wrestling game with a focus on technical grappling.', 'Win the championship belt with custom wrestlers and moves.', 'Enter the ring in Natsume Championship Wrestling on SNES.', 'A 16-bit wrestling sim known for its deep move sets and high difficulty. Master the timing-based grappling system to dominate your opponents.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-all-star-challenge-europe', 'SNES', 'NBA All-Star Challenge (Europe)', '1992', 'Sports', 'LGS', '4', 'Basketball Arcade', 'One-on-one and skill-based basketball challenges.', 'Win the All-Star events and prove your dominance on the court.', 'Play NBA All-Star Challenge on the Super Nintendo.', 'Features the stars of the early 90s. Compete in 1-on-1 matches, free throw contests, and three-point shootouts in this 16-bit sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-all-star-challenge-japan', 'SNES', 'NBA All-Star Challenge (Japan)', '1992', 'Sports', 'LGS', '4', 'Basketball Arcade', 'One-on-one and skill-based basketball challenges.', 'Win the All-Star events in the original Japanese version.', 'Experience NBA All-Star Challenge on the Super Famicom.', 'A focused 16-bit basketball experience. Test your skills with the NBA''s top players in a variety of specialized mini-games and head-to-head matchups.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-all-star-challenge-usa', 'SNES', 'NBA All-Star Challenge (USA)', '1992', 'Sports', 'LGS', '4', 'Basketball Arcade', 'One-on-one and skill-based basketball challenges.', 'Win the All-Star events and prove your dominance on the court.', 'Play NBA All-Star Challenge on the Super Nintendo.', 'Master the 16-bit shooting mechanics. A perfect title for quick basketball sessions, focusing on individual player skill rather than full team play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-give-n-go-europe', 'SNES', 'NBA Give ''n Go (Europe)', '1995', 'Sports', 'KONAMI', '4', 'Basketball Arcade', 'High-octane 5-on-5 basketball with a cinematic "behind-the-back" view.', 'Outscore your rivals in this fast-paced arcade simulation.', 'Experience NBA Give ''n Go on the Super Nintendo.', 'Features large, detailed sprites and a unique perspective. A 16-bit port of the arcade hit that emphasizes dunks and high-speed transitions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-give-n-go-usa', 'SNES', 'NBA Give ''n Go (USA)', '1995', 'Sports', 'KONAMI', '4', 'Basketball Arcade', 'High-octane 5-on-5 basketball with a cinematic "behind-the-back" view.', 'Lead your NBA team to victory in this arcade-style sim.', 'Play NBA Give ''n Go for the Super Nintendo.', 'A technical 16-bit achievement. Experience the intensity of professional basketball with a camera angle that puts you right in the middle of the action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-hang-time-europe', 'SNES', 'NBA Hang Time (Europe)', '1996', 'Sports', 'Midway', '4', 'Basketball Arcade', 'The official sequel to NBA Jam with 2-on-2 arcade action.', 'Defeat all NBA teams and achieve legendary status.', 'Play the high-flying NBA Hang Time on the SNES.', 'Features "Create-a-Player" and spectacular multi-player dunks. A 16-bit classic that perfected the over-the-top arcade basketball formula.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-hang-time-usa', 'SNES', 'NBA Hang Time (USA)', '1996', 'Sports', 'Midway', '4', 'Basketball Arcade', 'The official sequel to NBA Jam with 2-on-2 arcade action.', 'Dominate the court with outrageous dunks and power-ups.', 'Experience NBA Hang Time on the Super Nintendo.', 'Master the team-fire and double-dunk mechanics. A must-play 16-bit sports title for fans of fast-paced, irreverent arcade action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-jam---tournament-edition-europe', 'SNES', 'NBA Jam - Tournament Edition (Europe)', '1995', 'Sports', 'Midway', '4', 'Basketball Arcade', 'Enhanced arcade basketball with real rosters and secret characters.', 'Go "on fire" and win the tournament in this definitive edition.', 'Play NBA Jam: Tournament Edition on the SNES.', 'The pinnacle of 16-bit arcade sports. Features updated rosters, more secret players, and new power-ups that make the "Boom-shakalaka" action better than ever.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-jam---tournament-edition-japan', 'SNES', 'NBA Jam - Tournament Edition (Japan)', '1995', 'Sports', 'Midway', '4', 'Basketball Arcade', 'Enhanced arcade basketball with real rosters and secret characters.', 'Defeat the NBA''s best in the official Japanese version.', 'Experience NBA Jam: Tournament Edition on the Super Famicom.', 'A perfect 16-bit arcade port. Includes the iconic announcer, massive dunks, and the legendary 2-player competitive mode that defined a generation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-jam---tournament-edition-usa', 'SNES', 'NBA Jam - Tournament Edition (USA)', '1995', 'Sports', 'Midway', '4', 'Basketball Arcade', 'Enhanced arcade basketball with real rosters and secret characters.', 'Go "on fire" and win the tournament in this definitive edition.', 'Play the high-flying NBA Jam: T.E. on the SNES.', 'The peak of 16-bit arcade hoops. Featuring expanded rosters, injury stats, and more secret characters. Master the "Boom-shakalaka" dunks in the most polished version of the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-jam---tournament-edition-usa-beta', 'SNES', 'NBA Jam - Tournament Edition (USA) (Beta)', '1995', 'Sports', 'Midway', '4', 'Basketball Arcade', 'Enhanced arcade basketball (Pre-release build).', 'Explore early character stats and court designs in this beta.', 'Check out the NBA Jam: T.E. Beta on the SNES.', 'A rare 16-bit development look at the Tournament Edition. Witness the fine-tuning of player attributes and early implementations of the legendary power-up icons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-jam-europe', 'SNES', 'NBA Jam (Europe)', '1993', 'Sports', 'Midway', '4', 'Arcade Basketball', 'Over-the-top 2-on-2 arcade basketball featuring NBA stars.', 'Defeat all NBA teams to become the world champion.', 'Experience the original NBA Jam on the Super Nintendo.', 'The game that changed sports titles forever. Features gravity-defying dunks, the iconic "He''s on fire!" mechanic, and intense 2-player competitive 16-bit action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-jam-europe-rev-a', 'SNES', 'NBA Jam (Europe) (Rev A)', '1993', 'Sports', 'Midway', '4', 'Arcade Basketball', 'Over-the-top 2-on-2 arcade basketball (Updated Revision).', 'Dominate the court in this refined European version.', 'Play the polished NBA Jam (Rev A) on the SNES.', 'An updated 16-bit revision that fixes minor AI bugs and optimizes the sprite scaling for a smoother arcade experience on the Super Nintendo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-jam-japan', 'SNES', 'NBA Jam (Japan)', '1993', 'Sports', 'Midway', '4', 'Arcade Basketball', 'Over-the-top 2-on-2 arcade basketball featuring NBA stars.', 'Win the tournament in the official Japanese version.', 'Experience NBA Jam on the Super Famicom.', 'The 16-bit Japanese release of the arcade hit. Includes the full roster of early 90s legends and the frantic, high-scoring gameplay that made it a global phenomenon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-jam-usa', 'SNES', 'NBA Jam (USA)', '1993', 'Sports', 'Midway', '4', 'Arcade Basketball', 'Over-the-top 2-on-2 arcade basketball featuring NBA stars.', 'Defeat every team in the league to unlock secret players.', 'Play the legendary NBA Jam for the Super Nintendo.', 'A foundational 16-bit sports game. Use Turbo to pull off spectacular dunks and shove opponents out of the way in this lawless and addictive basketball classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-jam-usa-rev-a', 'SNES', 'NBA Jam (USA) (Rev A)', '1993', 'Sports', 'Midway', '4', 'Arcade Basketball', 'Over-the-top 2-on-2 arcade basketball (Updated Revision).', 'Master the court in the most stable North American version.', 'Play NBA Jam (Rev A) on the Super Nintendo.', 'The final 16-bit US revision. Improves the sound quality of the iconic announcer and fixes rare crashes during the end-game statistical screens.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-jam-2k20:-tournament-edition', 'SNES', 'NBA Jam 2K20: Tournament Edition', '2020', 'Sports', 'Community', '4', 'Arcade Basketball Mod', 'Modern fan-made update for NBA Jam: Tournament Edition.', 'Play with 2020 NBA rosters in the classic 16-bit engine.', 'Experience NBA Jam 2K20 on the Super Nintendo.', 'A massive 16-bit romhack that updates the game with modern stars like LeBron James and Steph Curry. Features new logos, colors, and adjusted stats for the modern era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-jikkyou-basket-winning-dunk-japan', 'SNES', 'NBA Jikkyou Basket Winning Dunk (Japan)', '1994', 'Sports', 'A-Max', '4', 'Simulation Basketball', 'Arcade-style 5-on-5 basketball with enthusiastic Japanese commentary.', 'Lead your team to the championship with "Winning Dunks."', 'Play NBA Jikkyou Basket on the Super Famicom.', 'Known for its digitized voice acting and energetic atmosphere. A fast-paced 16-bit basketball title that bridges the gap between arcade and simulation styles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-live-95-europe', 'SNES', 'NBA Live ''95 (Europe)', '1994', 'Sports', 'EA Sports', '2', 'Simulation Basketball', 'Isometric professional basketball simulation.', 'Win the NBA championship with the new 1995 rosters.', 'Experience the revolutionary NBA Live ''95 on SNES.', 'A landmark 16-bit sports title. Introduced the iconic 30-degree isometric view, allowing for better court vision, deeper playbooks, and more realistic player movements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-live-95-japan-rev-0a', 'SNES', 'NBA Live ''95 (Japan) (Rev 0A)', '1994', 'Sports', 'EA Sports', '2', 'Simulation Basketball', 'Isometric professional basketball simulation (Updated Japanese version).', 'Master the 1995 season in the refined Japanese release.', 'Play NBA Live ''95 (Rev 0A) on the Super Famicom.', 'The polished 16-bit Japanese revision. Features localized menus and minor gameplay balances to the shooting mechanics and defensive AI.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-live-95-usa', 'SNES', 'NBA Live ''95 (USA)', '1994', 'Sports', 'EA Sports', '2', 'Simulation Basketball', 'Isometric professional basketball simulation.', 'Lead your team to the NBA Finals in the definitive ''95 edition.', 'Play the classic NBA Live ''95 on the Super Nintendo.', 'Widely considered the best basketball sim on the system. Features a deep season mode, comprehensive player trades, and a high-octane 16-bit engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-live-96-europe', 'SNES', 'NBA Live ''96 (Europe)', '1995', 'Sports', 'EA Sports', '2', 'Simulation Basketball', 'Professional basketball simulation with 1996 season data.', 'Defeat your rivals with updated rosters and new mechanics.', 'Experience NBA Live ''96 on the Super Nintendo.', 'Features the "Create-a-Player" mode and improved 16-bit animations. A solid sequel that refined the isometric gameplay and added more tactical depth to the offense.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-live-96-usa', 'SNES', 'NBA Live ''96 (USA)', '1995', 'Sports', 'EA Sports', '2', 'Simulation Basketball', 'Professional basketball simulation with 1996 season data.', 'Win the championship with the stars of the ''96 season.', 'Play NBA Live ''96 for the Super Nintendo.', 'Includes the 1995 expansion teams, the Raptors and Grizzlies. Master the 16-bit post moves and updated three-point shooting in this polished simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-live-97-europe', 'SNES', 'NBA Live ''97 (Europe)', '1996', 'Sports', 'EA Sports', '2', 'Simulation Basketball', 'Professional basketball simulation with 1997 season data.', 'Claim the trophy in this late-gen 16-bit sports classic.', 'Experience NBA Live ''97 for the Super Nintendo.', 'Features even more detailed 16-bit player sprites and a faster gameplay pace. A refined entry that maximizes the SNES hardware for realistic sports action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-live-97-usa', 'SNES', 'NBA Live ''97 (USA)', '1996', 'Sports', 'EA Sports', '2', 'Simulation Basketball', 'Professional basketball simulation with 1997 season data.', 'Lead your team to glory with the updated ''97 rosters.', 'Play NBA Live ''97 for the Super Nintendo.', 'The North American release featuring the full 1997 season data. Offers deep strategy, realistic foul calls, and a comprehensive 16-bit management system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-live-98-usa', 'SNES', 'NBA Live ''98 (USA)', '1997', 'Sports', 'EA Sports', '2', 'Simulation Basketball', 'The final 16-bit entry in the legendary NBA Live series.', 'Win the ultimate victory in the definitive SNES edition.', 'Play the final NBA Live ''98 on the Super Nintendo.', 'The most refined 16-bit basketball simulation. Features the complete 1998 rosters and the most stable gameplay engine of the entire SNES run.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-pro-basketball---bulls-vs-blazers-japan', 'SNES', 'NBA Pro Basketball - Bulls vs Blazers (Japan)', '1992', 'Sports', 'Electronic Arts', '2', 'Simulation Basketball', 'Early 16-bit basketball simulation focusing on the iconic ''91 finals.', 'Recreate the Bulls vs. Blazers showdown on the court.', 'Play NBA Pro Basketball on the Super Famicom.', 'Known as Bulls vs. Blazers in the West. A foundational 16-bit basketball game featuring "Signature Moves" for star players and a slower, more tactical pace.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-pro-basketball-94---bulls-vs-suns-japan', 'SNES', 'NBA Pro Basketball ''94 - Bulls vs Suns (Japan)', '1994', 'Sports', 'Electronic Arts', '2', 'Simulation Basketball', '16-bit basketball simulation featuring the 1993 finals matchup.', 'Lead the Bulls or the Suns to victory in this specialized sim.', 'Experience Bulls vs. Suns on the Super Famicom.', 'Features improved 16-bit graphics and smoother passing compared to its predecessor. A focused sports title that captures the rivalry of the early 90s.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-showdown-usa', 'SNES', 'NBA Showdown (USA)', '1993', 'Sports', 'Electronic Arts', '2', 'Simulation Basketball', 'Professional basketball simulation and precursor to the Live series.', 'Win the playoffs with deep tactical play and rosters.', 'Experience NBA Showdown on the Super Nintendo.', 'A 16-bit title that paved the way for modern sims. Features full NBA licenses, realistic season tracking, and a challenging gameplay engine for the time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-showdown-usa-beta', 'SNES', 'NBA Showdown (USA) (Beta)', '1993', 'Sports', 'Electronic Arts', '2', 'Simulation Basketball', 'Professional basketball simulation (Pre-release build).', 'Test the early player physics and menu layouts.', 'Check out the NBA Showdown Beta on the SNES.', 'A rare 16-bit development build. Witness the fine-tuning of the free-throw mechanics and the early implementation of the seasonal statistical database.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ncaa-basketball-usa', 'SNES', 'NCAA Basketball (USA)', '1993', 'Sports', 'Sculptured Software', '2', 'Simulation Basketball', 'Revolutionary Mode 7 basketball simulation with a 3D perspective.', 'Win the national college championship with your favorite team.', 'Experience the 3D-style NCAA Basketball on the SNES.', 'The first 16-bit basketball game to use Mode 7 for a rotating 3D court. Provides an immersive perspective and fluid player movement for a realistic college hoops experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ncaa-basketball-usa-beta', 'SNES', 'NCAA Basketball (USA) (Beta)', '1993', 'Sports', 'Sculptured Software', '2', 'Simulation Basketball', 'Revolutionary Mode 7 basketball simulation (Pre-release build).', 'Test the early 3D camera angles and player physics.', 'Check out the NCAA Basketball Beta on the SNES.', 'A rare 16-bit development build. Witness the early implementation of the rotating Mode 7 court and the tuning of the high-speed camera transitions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ncaa-basketball-usa-rev-a', 'SNES', 'NCAA Basketball (USA) (Rev A)', '1993', 'Sports', 'Sculptured Software', '2', 'Simulation Basketball', 'Revolutionary Mode 7 basketball simulation (Updated Revision).', 'Lead your college team to glory in this polished version.', 'Play the refined NCAA Basketball (Rev A) on the SNES.', 'An updated 16-bit revision that fixes minor texture glitches on the court and improves the AI logic during the final minutes of close tournament games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ncaa-final-four-basketball-usa', 'SNES', 'NCAA Final Four Basketball (USA)', '1994', 'Sports', 'Bitmasters', '2', 'Simulation Basketball', 'College basketball simulation with a focus on the final tournament.', 'Reach the Final Four and win the national title.', 'Play NCAA Final Four Basketball on the Super Nintendo.', 'Features deep college rosters and authentic tournament play. A solid 16-bit sports title that focuses on the high-energy atmosphere of collegiate athletics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ncaa-football-usa', 'SNES', 'NCAA Football (USA)', '1994', 'Sports', 'Electronic Arts', '2', 'Simulation Football', 'Deep college football simulation with authentic teams and plays.', 'Win the national championship and the Heisman trophy.', 'Kick off the action in NCAA Football for the SNES.', 'Features dozens of college teams and unique playbooks. A comprehensive 16-bit simulation that captures the strategy and pageantry of American college football.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nekketsu-tairiku-burning-heroes-japan', 'SNES', 'Nekketsu Tairiku Burning Heroes (Japan)', '1995', 'RPG', 'Enix', '1', 'Action RPG', 'Traditional turn-based JRPG with multiple protagonist paths.', 'Choose your hero and prevent a world-ending catastrophe.', 'Explore Nekketsu Tairiku Burning Heroes on Super Famicom.', 'A polished 16-bit RPG featuring high-quality pixel art and a branching narrative. Choose from different characters, each with their own unique story and combat specialties.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('network-q-rally-usa-proto', 'SNES', 'Network Q Rally (USA) (Proto)', '1992', 'Racing', 'Namco', '2', 'Top-Down Rally', 'Realistic rally racing simulation (Unreleased Prototype).', 'Compete in international rally stages and master the terrain.', 'Check out the Network Q Rally Proto on the SNES.', 'A rare 16-bit racing prototype. Features technical driving mechanics, diverse weather conditions, and a focus on realistic rally physics for the time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('neugier---umi-to-kaze-no-kodou-japan', 'SNES', 'Neugier - Umi to Kaze no Kodou (Japan)', '1993', 'RPG', 'Telenet Japan', '1', 'Action RPG', 'Fast-paced action-RPG with a top-down perspective.', 'Stop the pirate invasion and uncover the mystery of the island.', 'Discover the dynamic Neugier on the Super Famicom.', 'A short but intense 16-bit action-adventure. Features fluid combat, environmental puzzles, and a unique "grappling chain" mechanic used for both platforming and combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('neugier---umi-to-kaze-no-kodou-japan-en-by-haeleth-v20', 'SNES', 'Neugier - Umi to Kaze no Kodou (Japan) [En by Haeleth v2.0]', '1993', 'RPG', 'Telenet Japan', '1', 'Action RPG', 'Fast-paced action-RPG with a full English fan translation.', 'Experience the story of Neugier with full English text.', 'Play Neugier in English on the Super Nintendo.', 'The Haeleth translation makes this 16-bit Wolf Team gem accessible. Follow the cinematic story and master the agile combat system in your own language.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-super-mario-land-demo', 'SNES', 'New Super Mario Land (Demo)', '2019', 'Platformer', 'Fanmade', '1', 'Classic Platformer', 'Modern fan-made remake of the Game Boy classic.', 'Rescue Princess Daisy in this high-fidelity 16-bit remake.', 'Play New Super Mario Land Demo on the SNES.', 'An incredible modern homebrew. Reimagines the 1989 classic with 16-bit graphics and music inspired by the "New" series, featuring 4-player cooperative play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-yatterman---nandai-kandai-yajirobee-japan', 'SNES', 'New Yatterman - Nandai Kandai Yajirobee (Japan)', '1994', 'Action', 'Tatsunoko Production', '2', 'Arcade Action', 'Board game and action hybrid based on the classic anime.', 'Outsmart the Doronbo gang in this wacky digital board game.', 'Join the fun in New Yatterman on the Super Famicom.', 'Features a variety of 16-bit mini-games and comedic cutscenes. Navigate the board and engage in tactical battles using iconic Yatterman mechs and gadgets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('newman-haas-indycar-racing-featuring-nigel-mansell-europe', 'SNES', 'Newman-Haas IndyCar Racing featuring Nigel Mansell (Europe)', '1994', 'Racing', 'Konami', '2', 'Simulation Racing', 'Professional IndyCar racing simulation with Nigel Mansell.', 'Win the world championship with expert driving and tuning.', 'Race in Newman-Haas IndyCar Racing for the SNES.', 'Features high-speed 16-bit Mode 7 graphics. Master the nuances of professional racing with Nigel Mansell''s guidance and realistic car physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('newman-haas-indycar-racing-featuring-nigel-mansell-japan', 'SNES', 'Newman-Haas IndyCar Racing featuring Nigel Mansell (Japan)', '1994', 'Racing', 'Konami', '2', 'Simulation Racing', 'Professional IndyCar racing simulation with Nigel Mansell.', 'Claim the championship in the official Japanese version.', 'Experience Newman-Haas IndyCar on the Super Famicom.', 'The 16-bit Japanese release of the acclaimed racer. Features deep car customization, realistic pit stops, and intense open-wheel racing action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('newman-haas-indycar-racing-featuring-nigel-mansell-usa', 'SNES', 'Newman-Haas IndyCar Racing featuring Nigel Mansell (USA)', '1994', 'Racing', 'Konami', '2', 'Simulation Racing', 'Professional IndyCar racing simulation with Nigel Mansell.', 'Master the tracks and outrun your rivals in the USA edition.', 'Play Newman-Haas IndyCar Racing for the SNES.', 'A technical 16-bit achievement. Use the "slipstream" mechanic and manage your tire wear to win across a variety of real-world international circuits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nfl-football-europe', 'SNES', 'NFL Football (Europe)', '1991', 'Sports', 'Nintendo', '2', 'Simulation Football', 'Foundational professional football simulation with NFL licensing.', 'Lead your team to the Super Bowl and claim the ring.', 'Play the original NFL Football on the Super Nintendo.', 'A foundational 16-bit football title featuring official team logos and rosters. Offers a balanced mix of arcade action and strategic play-calling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nfl-football-europe-proto', 'SNES', 'NFL Football (Europe) (Proto)', '1991', 'Sports', 'Nintendo', '2', 'Simulation Football', 'Professional football simulation (Unreleased European Prototype).', 'Test the early pitch mechanics and localized menus.', 'Explore the NFL Football Europe Proto on the SNES.', 'A rare 16-bit development look at an unreleased European version. Witness the fine-tuning of the player sprites and the early playbook implementations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nfl-football-japan', 'SNES', 'NFL Football (Japan)', '1991', 'Sports', 'Nintendo', '2', 'Simulation Football', 'Professional football simulation (Official Japanese release).', 'Win the championship in the refined Japanese version.', 'Experience NFL Football on the Super Famicom.', 'Features the complete NFL license for the Japanese market. A solid 16-bit simulation with smooth animations and a comprehensive seasonal mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nfl-football-usa', 'SNES', 'NFL Football (USA)', '1991', 'Sports', 'Nintendo', '2', 'Simulation Football', 'Professional football simulation with official NFL licensing.', 'Master the playbook and win the Super Bowl.', 'Experience NFL Football on the Super Nintendo.', 'The definitive 16-bit start to the series. Features realistic weather effects, a variety of defensive schemes, and the stars of the early 90s NFL.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nfl-pro-football-94-japan', 'SNES', 'NFL Pro Football ''94 (Japan)', '1994', 'Sports', 'EA Sports', '2', 'Simulation Football', 'Professional football simulation with 1994 season rosters.', 'Lead your team to victory in this localized Japanese edition.', 'Play NFL Pro Football ''94 on the Super Famicom.', 'An updated 16-bit version featuring the 1994 NFL data. Master the offensive timing and defensive coverage in this polished sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nfl-quarterback-club-96-europe', 'SNES', 'NFL Quarterback Club ''96 (Europe)', '1995', 'Sports', 'Iguana Entertainment', '2', 'Simulation Football', 'Advanced football simulation with 1996 rosters and multi-view.', 'Win the Super Bowl in this late-gen 16-bit football sim.', 'Play NFL Quarterback Club ''96 for the Super Nintendo.', 'Features improved 16-bit graphics and a massive variety of play options. Known for its realistic player attributes and more fluid passing mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nfl-quarterback-club-96-japan', 'SNES', 'NFL Quarterback Club ''96 (Japan)', '1995', 'Sports', 'Iguana Entertainment', '2', 'Simulation Football', 'Advanced football simulation (Japanese release of the ''96 edition).', 'Defeat your rivals in the official Japanese version.', 'Experience NFL Quarterback Club ''96 on Super Famicom.', 'The 16-bit Japanese release featuring the same deep simulation and 1996 team data that made the series a favorite for sports fans worldwide.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nfl-quarterback-club-96-usa', 'SNES', 'NFL Quarterback Club ''96 (USA)', '1995', 'Sports', 'Iguana Entertainment', '2', 'Simulation Football', 'Advanced football simulation with 1996 rosters and multi-view.', 'Lead your team to glory in the definitive ''96 edition.', 'Play NFL Quarterback Club ''96 for the Super Nintendo.', 'Introduces more complex AI and a wider range of motion for player sprites. A peak 16-bit football experience with deep seasonal management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nfl-quarterback-club-96-usa-beta', 'SNES', 'NFL Quarterback Club ''96 (USA) (Beta)', '1995', 'Sports', 'Iguana Entertainment', '2', 'Simulation Football', 'Advanced football simulation (Pre-release build).', 'Test the early ''96 season rosters and gameplay tweaks.', 'Check out the NFL Quarterback Club ''96 Beta on SNES.', 'A rare 16-bit development build. Witness the fine-tuning of the passing windows and the evolution of the detailed stadium graphics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nfl-quarterback-club-europe', 'SNES', 'NFL Quarterback Club (Europe)', '1994', 'Sports', 'Iguana Entertainment', '2', 'Simulation Football', 'Professional football simulation and rival to the Madden series.', 'Compete in the Quarterback Challenge or the full season.', 'Play NFL Quarterback Club on the Super Nintendo.', 'A unique 16-bit title that features both traditional football games and specialized QB skill challenges. Master the accuracy and distance drills to build your stats.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nfl-quarterback-club-japan', 'SNES', 'NFL Quarterback Club (Japan)', '1994', 'Sports', 'Iguana Entertainment', '2', 'Simulation Football', 'Professional football simulation (Official Japanese release).', 'Win the championship in the refined Japanese version.', 'Experience NFL Quarterback Club on the Super Famicom.', 'The 16-bit Japanese debut of the series. Features high-quality sound effects, detailed player sprites, and a comprehensive look at professional football strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nfl-quarterback-club-usa', 'SNES', 'NFL Quarterback Club (USA)', '1994', 'Sports', 'Iguana Entertainment', '2', 'Simulation Football', 'Professional football simulation and rival to the Madden series.', 'Master the playbook and claim the Super Bowl trophy.', 'Experience NFL Quarterback Club on the Super Nintendo.', 'Known for its impressive 16-bit visuals and the specialized "Quarterback Challenge" mode. Offers a more arcade-leaning alternative to the Madden series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nfl-quarterback-club-usa-beta', 'SNES', 'NFL Quarterback Club (USA) (Beta)', '1994', 'Sports', 'Iguana Entertainment', '2', 'Simulation Football', 'Professional football simulation (Pre-release build).', 'Explore the early gameplay mechanics and skill challenges.', 'Check out the NFL Quarterback Club Beta on the SNES.', 'A rare 16-bit development slice. Witness the initial implementation of the QB drills and the tuning of the on-field player physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nhl-94-europe', 'SNES', 'NHL ''94 (Europe)', '1993', 'Sports', 'EA Sports', '2', 'Simulation Hockey', 'Fast-paced ice hockey simulation with official NHL licensing.', 'Win the Stanley Cup in the definitive 16-bit hockey game.', 'Play the legendary NHL ''94 on the Super Nintendo.', 'Widely considered the best sports game of its era. Features the iconic "one-timer" shot, manual goalie control, and incredible 16-bit gameplay that remains perfectly balanced and addictive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nhl-stanley-cup-usa-enfr', 'SNES', 'NHL Stanley Cup (USA) (En,Fr)', '1993', 'Sports', 'Sculptured Software', '2', 'Simulation Hockey', 'Mode 7-based 3D ice hockey simulation.', 'Master the rotating rink to win the Stanley Cup.', 'Experience NHL Stanley Cup''s 3D action on SNES.', 'Uses the SNES''s Mode 7 to create a unique "into the screen" perspective. Features fast skating and a 16-bit physics engine that emphasizes physical play and slapshots.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nhlpa-hockey-93-europe', 'SNES', 'NHLPA Hockey ''93 (Europe)', '1992', 'Sports', 'EA Sports', '2', 'Simulation Hockey', 'Realistic ice hockey featuring the Players'' Association license.', 'Lead your team to victory with 1993''s professional rosters.', 'Play NHLPA Hockey ''93 for the Super Nintendo.', 'The predecessor to NHL ''94. Known for its grit and the inclusion of player-specific stats and the infamous 16-bit "fighting" mechanic on the ice.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nhlpa-hockey-93-usa', 'SNES', 'NHLPA Hockey ''93 (USA)', '1992', 'Sports', 'EA Sports', '2', 'Simulation Hockey', 'Realistic ice hockey featuring the Players'' Association license.', 'Outscore your rivals in this classic 16-bit sports title.', 'Play NHLPA Hockey ''93 for the Super Nintendo.', 'Experience the high-speed action and deep seasonal play that made this 16-bit title a staple for hockey fans before the full NHL license was integrated.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nice-de-shot-japan', 'SNES', 'Nice de Shot (Japan)', '1992', 'Sports', 'Nichibutsu', '2', 'Arcade Sports', 'Professional golf simulation with a Japanese flair.', 'Master the 18-hole course with precision strokes.', 'Tee off in Nice de Shot on the Super Famicom.', 'A polished 16-bit golf game. Features diverse terrains, realistic wind physics, and a variety of clubs to help you achieve the perfect score in this relaxing simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nichibutsu-arcade-classics-japan', 'SNES', 'Nichibutsu Arcade Classics (Japan)', '1995', 'Compilation', 'Nichibutsu', '2', 'Arcade Compilation', 'Compilation of classic arcade titles from Nichibutsu.', 'Achieve the highest scores in several retro arcade hits.', 'Play Nichibutsu Arcade Classics on Super Famicom.', 'Includes pixel-perfect 16-bit ports of "Frisky Tom," "Moon Cresta," and "Crazy Climber." A nostalgic collection for fans of the golden age of arcade gaming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nichibutsu-arcade-classics-2---heiankyou-alien-japan', 'SNES', 'Nichibutsu Arcade Classics 2 - Heiankyou Alien (Japan)', '1995', 'Compilation', 'Nichibutsu', '2', 'Arcade Compilation', 'Strategy-puzzle arcade game featuring the cult classic.', 'Trap the aliens by digging holes in this retro revival.', 'Play Heiankyou Alien on the Super Famicom.', 'A 16-bit update to the legendary 1979 game. Use strategy and timing to bury invaders in this addictive and historically significant arcade title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nichibutsu-collection-1-japan', 'SNES', 'Nichibutsu Collection 1 (Japan)', '1994', 'Compilation', 'Nichibutsu', '2', 'Arcade Compilation', 'Compilation of diverse arcade and board games.', 'Master a collection of classic Japanese parlor games.', 'Explore Nichibutsu Collection 1 on Super Famicom.', 'A 16-bit anthology featuring a mix of Mahjong and arcade-style challenges. Features improved graphics and sound for these traditional Japanese gaming staples.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nichibutsu-collection-2-japan', 'SNES', 'Nichibutsu Collection 2 (Japan)', '1994', 'Compilation', 'Nichibutsu', '2', 'Arcade Compilation', 'Compilation of diverse arcade and board games.', 'Win at the tables in this second volume of classics.', 'Experience Nichibutsu Collection 2 on Super Famicom.', 'Expands the 16-bit library of Nichibutsu titles, focusing heavily on polished Mahjong simulations and high-stakes virtual gambling for the Japanese market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nickelodeon-guts-usa', 'SNES', 'Nickelodeon GUTS (USA)', '1994', 'Sports', 'Viacom New Media', '2', 'Game Show Sports', 'Action-platformer based on the extreme sports game show.', 'Complete the obstacle courses and climb the Aggro Crag.', 'Play Nickelodeon GUTS for the Super Nintendo.', 'Control an athlete in 16-bit versions of the show''s events. Features hurdles, swimming, and the final climb to the summit in a fun, competitive sports format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nigel-mansell-f-1-challenge-japan', 'SNES', 'Nigel Mansell F-1 Challenge (Japan)', '1992', 'Racing', 'Gremlin Graphics', '2', 'Formula Racing', 'Formula One racing simulation with Nigel Mansell.', 'Win the F-1 world championship in the Japanese edition.', 'Race in Nigel Mansell F-1 Challenge on Super Famicom.', 'Features 16-bit Mode 7 graphics. Master the world''s most famous tracks with expert advice from Nigel Mansell and realistic car tuning options.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nigel-mansells-world-championship-europe-gremlins-license', 'SNES', 'Nigel Mansell''s World Championship (Europe) (Gremlins License)', '1993', 'Racing', 'Gremlin Graphics', '2', 'Formula Racing', 'Formula One racing simulation featuring the world champion.', 'Claim the trophy in this localized F-1 experience.', 'Play Nigel Mansell''s World Championship on SNES.', 'A technical 16-bit racer. Use the "slipstream" mechanic and manage your pit-stop strategy to win across international circuits in the 1992 season.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nigel-mansells-world-championship-racing-europe', 'SNES', 'Nigel Mansell''s World Championship Racing (Europe)', '1993', 'Racing', 'Gremlin Graphics', '2', 'Formula Racing', 'Formula One racing simulation with Mode 7 scaling.', 'Defeat your rivals and become the F-1 world champion.', 'Experience Nigel Mansell''s World Championship on SNES.', 'Features incredibly fast 16-bit scaling and rotation. Provides a realistic sense of speed and a deep career mode where every second on the track counts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nigel-mansells-world-championship-racing-europe-rev-a', 'SNES', 'Nigel Mansell''s World Championship Racing (Europe) (Rev A)', '1993', 'Racing', 'Gremlin Graphics', '2', 'Formula Racing', 'Formula One racing simulation (Updated Revision).', 'Master the tracks in this refined 16-bit version.', 'Play the polished World Championship (Rev A) on SNES.', 'An updated 16-bit revision that optimizes frame rates during rainy weather conditions and fixes minor graphical glitches on the cockpit display.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nigel-mansells-world-championship-racing-usa', 'SNES', 'Nigel Mansell''s World Championship Racing (USA)', '1993', 'Racing', 'Gremlin Graphics', '2', 'Formula Racing', 'Formula One racing simulation featuring the world champion.', 'Defeat your rivals and become the F-1 world champion.', 'Experience Nigel Mansell''s World Championship on SNES.', 'A top-tier 16-bit simulation. Features real tracks, weather effects, and an advanced car-damage system that requires careful and precise driving.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nightmare-busters-world-unl', 'SNES', 'Nightmare Busters (World) (Unl)', '1994', 'Action', 'Atelier Double', '2', 'Run and Gun', 'Fast-paced run-and-gun action-platformer (Unreleased/Homebrew).', 'Defeat the dream-world monsters in this high-octane epic.', 'Play the intense Nightmare Busters on the SNES.', 'Originally cancelled and released years later. This 16-bit title features some of the best graphics on the system, with massive bosses and frantic projectile combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-gaiden-trilogy-usa', 'SNES', 'Ninja Gaiden Trilogy (USA)', '1995', 'Action', 'Tecmo', '2', 'Action Compilation', 'Compilation of the legendary NES Ninja Gaiden trilogy.', 'Stop the demon invasion in three classic action titles.', 'Play the Ninja Gaiden Trilogy on the SNES.', 'A 16-bit remaster of the 8-bit classics. Features updated graphics, refined music, and the same legendary difficulty that defined Ryu Hayabusa''s adventures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-ryuukenden-tomoe-japan', 'SNES', 'Ninja Ryuukenden Tomoe (Japan)', '1995', 'Action', 'Tecmo', '2', 'Action Platformer', 'Remastered Ninja Gaiden trilogy for the Japanese market.', 'Experience Ryu''s saga with enhanced 16-bit visuals.', 'Play Ninja Ryuukenden Tomoe on the Super Famicom.', 'A high-quality 16-bit compilation. Features localized text and improved cinematic cutscenes (Tecmo Theater) for all three original NES adventures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninjawarriors-again-the-japan', 'SNES', 'Ninjawarriors Again, The (Japan)', '1994', 'Action', 'Natsume', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up featuring three cybernetic ninjas.', 'Overthrow the dictatorship of Banglar in this cult classic.', 'Experience the intense Ninja Warriors Again on SNES.', 'A 16-bit masterpiece. Control Kunoichi, Ninja, or Kamaitachi, each with unique combat styles. Features incredible sprites, heavy-hitting combos, and a fantastic soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninjawarriors-the-europe', 'SNES', 'Ninjawarriors, The (Europe)', '1994', 'Action', 'Natsume', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up with a cinematic sci-fi theme.', 'Stop the evil regime in this polished European brawler.', 'Play The Ninja Warriors on the Super Nintendo.', 'Known for its smooth 16-bit combat and detailed urban environments. A must-play for fans of the genre, offering a satisfying and deep fighting experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninjawarriors-the-usa', 'SNES', 'Ninjawarriors, The (USA)', '1994', 'Action', 'Natsume', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up featuring three cybernetic ninjas.', 'Destroy the enemy army in this 16-bit action classic.', 'Play The Ninja Warriors on the Super Nintendo.', 'Master the diverse move-sets of the robotic protagonists. A highly technical 16-bit brawler that rewards timing, crowd control, and strategic special moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintama-rantarou---ninjutsu-gakuen-puzzle-taikai-no-dan-japan', 'SNES', 'Nintama Rantarou - Ninjutsu Gakuen Puzzle Taikai no Dan (Japan)', '1993', 'Puzzle', 'Culture Brain', '2', 'Puzzle', 'Puzzle-logic game based on the ninja anime series.', 'Win the puzzle tournament with Rantarou and friends.', 'Solve the Nintama Rantarou Puzzles on Super Famicom.', 'A charming 16-bit puzzle game. Use logic and speed to clear the board and defeat your classmates in a colorful world based on the long-running anime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintama-rantarou-japan', 'SNES', 'Nintama Rantarou (Japan)', '1993', 'Action', 'Culture Brain', '2', 'Action Platformer', 'Action-platformer based on the "Ninjaboy Rantarou" anime.', 'Complete the ninja academy''s trials and stop the villains.', 'Join the adventure in Nintama Rantarou on Super Famicom.', 'A colorful 16-bit title featuring 2-player co-op. Use ninja tools and agility to navigate levels filled with humor and vibrant Japanese-inspired art.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintama-rantarou-2-japan', 'SNES', 'Nintama Rantarou 2 (Japan)', '1994', 'Action', 'Culture Brain', '2', 'Action Platformer', 'Action-platformer sequel with more characters and stages.', 'Rescue the master and complete the new ninja missions.', 'Play Nintama Rantarou 2 on the Super Famicom.', 'Refines the 16-bit platforming of the original. Features more playable characters, diverse mini-games, and a lighthearted story faithful to the source material.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintama-rantarou-3-japan', 'SNES', 'Nintama Rantarou 3 (Japan)', '1995', 'Action', 'Culture Brain', '2', 'Action Platformer', 'Action-platformer featuring the three young ninja students.', 'Explore the world and defeat the rival schools.', 'Experience Nintama Rantarou 3 on the Super Famicom.', 'An expanded 16-bit adventure with better graphics and more complex level design. Features a great variety of items and special attacks for each ninja.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintama-rantarou-special-japan', 'SNES', 'Nintama Rantarou Special (Japan)', '1995', 'Action', 'Culture Brain', '2', 'Action Platformer', 'Special edition of the ninja adventure with extra content.', 'Complete the ultimate ninja challenge in this special version.', 'Play Nintama Rantarou Special on the Super Famicom.', 'A 16-bit compilation-style release that brings together the best levels and mini-games from the series with improved performance and new secrets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendo-scope-6-europe', 'SNES', 'Nintendo Scope 6 (Europe)', '1992', 'Shooter', 'Nintendo', '2', 'Light Gun Shooter', 'Light-gun shooting gallery and mini-game collection.', 'Master the Super Scope across six different game modes.', 'Blast away in Nintendo Scope 6 for the SNES.', 'The pack-in title for the 16-bit light gun. Includes "Blast Risers," "Mole Patrol," and "Lazer Blazer," offering a variety of tactical and speed-based shooting games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nishijin-pachinko-3-japan', 'SNES', 'Nishijin Pachinko 3 (Japan)', '1993', 'Gambling', 'Nichibutsu', '1', 'Pachinko Simulation', 'Pachinko simulation featuring the Nishijin brand machines.', 'Win the jackpot on a variety of digital Pachinko machines.', 'Play Nishijin Pachinko 3 on the Super Famicom.', 'A realistic 16-bit parlor simulation. Features detailed machine physics, colorful bonus screens, and multiple tables with different winning probabilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nishijin-pachinko-monogatari-japan', 'SNES', 'Nishijin Pachinko Monogatari (Japan)', '1993', 'Gambling', 'Nichibutsu', '1', 'Pachinko Simulation', 'Story-driven Pachinko simulation and adventure game.', 'Navigate the world of professional Pachinko to win big.', 'Experience Nishijin Pachinko Monogatari on SNES.', 'Combines 16-bit Pachinko gameplay with an adventure-style narrative. Interact with characters and manage your winnings to become a parlor legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nishijin-pachinko-monogatari-2-japan', 'SNES', 'Nishijin Pachinko Monogatari 2 (Japan)', '1994', 'Gambling', 'Nichibutsu', '1', 'Pachinko Simulation', 'Story-driven Pachinko simulation sequel.', 'Climb the rankings in the world of competitive Pachinko.', 'Play Nishijin Pachinko Monogatari 2 on Super Famicom.', 'Features improved 16-bit graphics and more complex machine mechanics. A deeper simulation for fans of the Japanese gambling culture.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nitropunks---might-heads-japan', 'SNES', 'Nitropunks - Might Heads (Japan)', '1993', 'Action', 'Nichibutsu', '2', 'Run and Gun', 'Humorous side-scrolling action-platformer (The Combatribes-lite).', 'Defeat the wacky punks and save the city as a hero duo.', 'Discover Nitropunks: Might Heads on Super Famicom.', 'A bizarre and fun 16-bit action game. Use your detachable head as a weapon and navigate through colorful, surreal stages filled with eccentric enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('no-escape-usa', 'SNES', 'No Escape (USA)', '1994', 'Action', 'Data East', '2', 'Beat ''em Up', 'Action-adventure based on the 1994 cinematic film.', 'Survive the hostile island and escape from the penal colony.', 'Play the intense No Escape on the Super Nintendo.', 'A 16-bit title focused on survival and item-crafting. Navigate dangerous jungles and traps while using stealth and improvised weapons to stay alive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nobunaga-no-yabou---haouden-japan', 'SNES', 'Nobunaga no Yabou - Haouden (Japan)', '1992', 'Strategy', 'Koei', '1', 'Turn-Based Strategy', 'Grand strategy simulation set in feudal Japan.', 'Conquer the warring provinces to unify Japan as a Great Lord.', 'Master strategy in Nobunaga no Yabou: Haouden on SNES.', 'A deep 16-bit historical sim. Manage your clan''s economy, diplomacy, and military strength. Features detailed siege battles and a complex political system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nobunaga-no-yabou---haouden-japan-rev-a', 'SNES', 'Nobunaga no Yabou - Haouden (Japan) (Rev A)', '1992', 'Strategy', 'Koei', '1', 'Turn-Based Strategy', 'Grand strategy simulation (Updated Revision).', 'Unify the Sengoku era in this refined strategic release.', 'Play the polished Haouden (Rev A) on Super Famicom.', 'An updated 16-bit revision that balances clan AI and optimizes the menu interface for smoother management of your growing empire.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nobunaga-no-yabou---tenshouki-japan', 'SNES', 'Nobunaga no Yabou - Tenshouki (Japan)', '1994', 'Strategy', 'Koei', '1', 'Turn-Based Strategy', 'Advanced grand strategy with a focus on officer growth.', 'Develop your generals and conquer Japan in this epic sequel.', 'Experience Nobunaga no Yabou: Tenshouki on SNES.', 'One of the most complex 16-bit strategy games. Features a deep "skill" system for officers and massive scale battles across the Japanese islands.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nobunagas-ambition---lord-of-darkness-usa', 'SNES', 'Nobunaga''s Ambition - Lord of Darkness (USA)', '1990', 'Strategy', 'Koei', '1', 'Turn-Based Strategy', 'Grand strategy simulation with a dark, atmospheric tone.', 'Rise from a minor lord to the supreme Shogun of Japan.', 'Play Nobunaga''s Ambition: Lord of Darkness on SNES.', 'Also known as "Busou Gehouden." A 16-bit tactical sim that blends historical conquest with high-stakes resource management and political intrigue.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nobunagas-ambition-usa', 'SNES', 'Nobunaga''s Ambition (USA)', '1989', 'Strategy', 'Koei', '1', 'Turn-Based Strategy', 'The classic grand strategy game that started the franchise.', 'Unify Japan through military force and shrewd diplomacy.', 'Play the original Nobunaga''s Ambition on the SNES.', 'A foundational 16-bit strategy title. Balance your peasant happiness, crop yields, and samurai loyalty to dominate the warring states.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nolan-ryans-baseball-usa', 'SNES', 'Nolan Ryan''s Baseball (USA)', '1991', 'Sports', 'Romstar', '2', 'Baseball Simulation', 'Realistic baseball simulation endorsed by the legendary pitcher.', 'Win the World Series with precision pitching and batting.', 'Step up to the plate in Nolan Ryan''s Baseball on SNES.', 'Features an innovative 16-bit "pitching" view and detailed player stats. Master the heat on the mound in this technical sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nomark-baku-haitou---shijou-saikyou-no-janshi-tachi-japan', 'SNES', 'Nomark Baku Haitou - Shijou Saikyou no Janshi-tachi (Japan)', '1994', 'Gambling', 'Nichibutsu', '1', 'Mahjong Simulation', 'Mahjong simulation based on the gambling manga series.', 'Defeat the strongest Mahjong players in intense tournaments.', 'Play Nomark Baku Haitou on the Super Famicom.', 'A 16-bit title focused on high-stakes Mahjong matches. Features character-driven dialogue and strategic gameplay based on the popular source material.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nontan-to-issho---kurukuru-puzzle-japan', 'SNES', 'Nontan to Issho - Kurukuru Puzzle (Japan)', '1994', 'Puzzle', 'Toei Animation', '1', 'Logic Puzzle', 'Colorful tile-matching puzzle game for all ages.', 'Clear the board with Nontan the cat in this cute puzzler.', 'Enjoy Nontan to Issho: Kurukuru Puzzle on SNES.', 'A charming 16-bit puzzle game featuring fluid animations and a catchy soundtrack. Perfect for quick sessions of addictive, family-friendly fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nosferatu-japan', 'SNES', 'Nosferatu (Japan)', '1994', 'Action', 'Seta', '1', 'Action Platformer', 'Cinematic action-platformer with a focus on hand-to-hand combat.', 'Rescue your beloved from the vampire''s castle in this horror epic.', 'Experience the atmospheric Nosferatu on the SNES.', 'A 16-bit visual masterpiece. Blends Prince of Persia-style rotoscoped movement with a unique martial arts combat system against gothic monsters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nosferatu-usa', 'SNES', 'Nosferatu (USA)', '1994', 'Action', 'Seta', '1', 'Action Platformer', 'Cinematic action-platformer with a focus on hand-to-hand combat.', 'Defeat the Prince of Darkness in this cinematic 16-bit title.', 'Survive the night in Nosferatu for the Super Nintendo.', 'Features incredible pixel art and a tense, survival-horror atmosphere. Use combos and dodges to survive the traps and beasts of the castle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('numbers-paradise-japan', 'SNES', 'Numbers Paradise (Japan)', '1993', 'Puzzle', 'Nichibutsu', '1', 'Number Puzzle', 'Collection of number-based logic and math puzzles.', 'Solve increasingly difficult numerical challenges to win.', 'Challenge your brain in Numbers Paradise on Super Famicom.', 'A 16-bit logic game that tests your mental math and pattern recognition. Features a clean interface and dozens of levels to master.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('o-chan-no-oekaki-logic-japan', 'SNES', 'O-chan no Oekaki Logic (Japan)', '1995', 'Puzzle', 'Nintendo', '1', 'Picture Logic', 'Picture logic puzzle game (Nonogram) featuring cute characters.', 'Solve the grid to reveal hidden 16-bit pixel art.', 'Play O-chan no Oekaki Logic on the Super Famicom.', 'A relaxing and addictive logic puzzler. Use the clues to fill in the squares and uncover the charming illustrations of the Hebereke universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('obitus-usa', 'SNES', 'Obitus (USA)', '1994', 'RPG', 'Psygnosis', '1', 'Action RPG', 'First-person RPG and adventure hybrid with a dark fantasy theme.', 'Navigate the treacherous castle and find your way home.', 'Explore the mysterious Obitus for the Super Nintendo.', 'A unique 16-bit port of the PC classic. Combines dungeon-crawling with side-scrolling action sequences and complex inventory management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oda-nobunaga---haou-no-gundan-japan', 'SNES', 'Oda Nobunaga - Haou no Gundan (Japan)', '1993', 'Strategy', 'Angel', '1', 'Real-Time Strategy', 'Tactical strategy game focused on the life of Oda Nobunaga.', 'Lead the Oda clan to total domination of Japan.', 'Master history in Oda Nobunaga: Haou no Gundan on SNES.', 'Features large-scale 16-bit tactical maps and a focus on military formations. Experience the dramatic rise of Japan''s most famous unifier.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('odekake-lester---lelele-no-le-japan', 'SNES', 'Odekake Lester - Lelele no Le (Japan)', '1994', 'Action', 'Atelier Double', '1', 'Action Platformer', 'Quirky action-adventure platformer starring a clumsy hero.', 'Help Lester survive the island and find his way back home.', 'Experience Odekake Lester on the Super Famicom.', 'The Japanese version of "Lester the Unlikely." A 16-bit platformer known for its unique character animations and environmental puzzle-solving.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oekaki-logic-japan-np', 'SNES', 'Oekaki Logic (Japan) (NP)', '1995', 'Puzzle', 'Nintendo', '1', 'Picture Logic', 'Classic Nonogram puzzle game (Nintendo Power flash version).', 'Solve hundreds of logic puzzles to reveal 16-bit images.', 'Play Oekaki Logic (NP) on the Super Famicom.', 'A specialized digital release featuring a vast library of "Paint by Numbers" puzzles. Simple, addictive, and perfect for fans of logic games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oekaki-logic-2-japan-np', 'SNES', 'Oekaki Logic 2 (Japan) (NP)', '1996', 'Puzzle', 'Nintendo', '1', 'Picture Logic', 'Expanded Nonogram puzzle sequel (Nintendo Power flash version).', 'Master even more complex picture logic challenges.', 'Challenge Oekaki Logic 2 (NP) on the Super Famicom.', 'Features new puzzle sizes and refined UI. A 16-bit logic staple that offers hours of brain-teasing gameplay for puzzle enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ogre-battle---the-march-of-the-black-queen-usa', 'SNES', 'Ogre Battle - The March of the Black Queen (USA)', '1993', 'Strategy', 'Quest', '2', 'Tactical Strategy RPG', 'Epic real-time tactical RPG with branching paths and alignment.', 'Lead a rebellion to overthrow the empire and save the world.', 'Master the legendary Ogre Battle on the SNES.', 'A 16-bit masterpiece. Manage tarot cards, unit formations, and city liberation in a massive world with multiple endings and deep lore.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('okamoto-ayako-to-match-play-golf---ko-olina-golf-club-in-hawaii-japan', 'SNES', 'Okamoto Ayako to Match Play Golf - Ko Olina Golf Club in Hawaii (Japan)', '1993', 'Sports', 'Nintendo', '2', 'Golf Simulation', 'Realistic golf simulation featuring the professional golfer.', 'Win the match play tournament at Hawaii''s premier club.', 'Tee off in Okamoto Ayako to Match Play Golf on SNES.', 'Features the real Ko Olina Golf Club layout. A technical 16-bit sports title with smooth swing mechanics and beautiful tropical scenery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('olivias-mystery-japan', 'SNES', 'Olivia''s Mystery (Japan)', '1993', 'Adventure', 'Human Entertainment', '1', 'Adventure', 'Unique picture-puzzle and spot-the-difference adventure.', 'Solve the visual mysteries to advance through the story.', 'Experience Olivia''s Mystery on the Super Famicom.', 'A charming 16-bit title that blends a light narrative with engaging visual puzzles. Test your observation skills to uncover hidden secrets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('olympic-summer-games-europe', 'SNES', 'Olympic Summer Games (Europe)', '1992', 'Sports', 'U.S. Gold', '4', 'Olympic Sports', 'Official multi-sport simulation of the 1996 Atlanta games.', 'Win the gold medal in a variety of athletic events.', 'Go for the gold in Olympic Summer Games on SNES.', 'Features 16-bit renditions of the 100m sprint, long jump, and archery. Compete against the world''s best in this comprehensive sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('olympic-summer-games-usa', 'SNES', 'Olympic Summer Games (USA)', '1992', 'Sports', 'U.S. Gold', '4', 'Olympic Sports', 'Official multi-sport simulation of the 1996 Atlanta games.', 'Lead your nation to victory in the ultimate summer games.', 'Play Olympic Summer Games for the Super Nintendo.', 'Master the timing-based 16-bit mechanics across multiple disciplines. A great multiplayer title for friends looking to break world records.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('on-the-ball-europe', 'SNES', 'On the Ball (Europe)', '1992', 'Sports', 'Taito', '2', 'Soccer Simulation', 'Physics-based puzzle-racing game (Cameltry port).', 'Rotate the maze to guide the ball to the exit before time runs out.', 'Experience On the Ball for the Super Nintendo.', 'A unique 16-bit title where you control the environment rather than the player. Features mind-bending mazes and impressive Mode 7 rotation effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('on-the-ball-usa', 'SNES', 'On the Ball (USA)', '1992', 'Sports', 'Taito', '2', 'Soccer Simulation', 'Physics-based puzzle-racing game (Cameltry port).', 'Master the labyrinth rotation in this addictive puzzle classic.', 'Challenge your skills in On the Ball on the SNES.', 'Includes various game modes and a level editor. A fast-paced 16-bit experience that rewards quick reflexes and spatial awareness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ongaku-tsukuru-kanaderu-japan', 'SNES', 'Ongaku Tsukuru Kanaderu (Japan)', '1995', 'Music', 'Nintendo', '1', 'Music Creation', 'Music composition and creation tool for the SNES.', 'Compose and play your own 16-bit musical masterpieces.', 'Create music with Ongaku Tsukuru Kanaderu on SNES.', 'A powerful 16-bit creative utility. Use a wide variety of instrument samples and a professional sequencer to write, edit, and save your own soundtracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('onizuka-katsuya-super-virtual-boxing---shin-kentou-ou-densetsu-japan', 'SNES', 'Onizuka Katsuya Super Virtual Boxing - Shin Kentou Ou Densetsu (Japan)', '1995', 'Sports', 'Human Entertainment', '2', 'Boxing Simulation', 'First-person professional boxing simulation.', 'Climb the ranks and win the world title as Katsuya Onizuka.', 'Experience Super Virtual Boxing on the Super Famicom.', 'A technical 16-bit boxing game with a unique "behind-the-gloves" perspective. Master the timing of jabs and hooks in this realistic sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oomono-black-bass-fishing---jinzouko-hen-japan', 'SNES', 'Oomono Black Bass Fishing - Jinzouko Hen (Japan)', '1994', 'Sports', 'Natsume', '1', 'Fishing Simulation', 'Realistic black bass fishing simulation set in man-made lakes.', 'Catch the legendary bass and win the tournament circuit.', 'Go fishing in Oomono Black Bass on the Super Famicom.', 'Features detailed 16-bit underwater views and lure physics. Manage your equipment and scout the best spots in various artificial lake environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oonita-atsushi-fmw---kagekara-no-chousen-japan', 'SNES', 'Oonita Atsushi FMW - Kagekara no Chousen (Japan)', '1993', 'Sports', 'Human Entertainment', '2', 'Pro Wrestling', 'Hardcore professional wrestling based on the FMW promotion.', 'Defeat the rival wrestlers in intense, high-stakes matches.', 'Play Oonita Atsushi FMW on the Super Famicom.', 'A 16-bit wrestling title featuring the legendary Atsushi Onita. Known for its "deathmatch" style and over-the-top special moves inspired by the FMW era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oonita-atsushi-fmw---kagekara-no-chousen-japan-beta', 'SNES', 'Oonita Atsushi FMW - Kagekara no Chousen (Japan) (Beta)', '1993', 'Sports', 'Human Entertainment', '2', 'Pro Wrestling', 'Hardcore professional wrestling (Pre-release build).', 'Test the early grappling mechanics and character sprites.', 'Check out the Oonita Atsushi FMW Beta on the SNES.', 'A rare 16-bit development look at the FMW wrestling game. Witness the initial implementation of the crowd animations and the balancing of the fighter stats.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oozumou-damashii-japan', 'SNES', 'Oozumou Damashii (Japan)', '1992', 'Sports', 'Face', '2', 'Sumo Wrestling', 'Traditional Sumo wrestling simulation with a focus on technique.', 'Reach the rank of Yokozuna through strength and strategy.', 'Master Sumo in Oozumou Damashii on the Super Famicom.', 'A respectful 16-bit simulation of Japan''s national sport. Master dozens of traditional moves and manage your wrestler''s energy in high-tension bouts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('operation-europe---path-to-victory-1939-45-usa', 'SNES', 'Operation Europe - Path to Victory 1939-45 (USA)', '1993', 'Strategy', 'Koei', '1', 'Turn-Based War Strategy', 'World War II grand strategy and tactical simulation.', 'Lead your forces to victory in the European theater.', 'Master history in Operation Europe on the SNES.', 'A deep 16-bit military sim from Koei. Manage supply lines, diplomacy, and troop movements across realistic maps of the 1939-1945 conflict.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('operation-logic-bomb-europe', 'SNES', 'Operation Logic Bomb (Europe)', '1993', 'Action', 'Jaleco', '2', 'Run and Gun', 'Top-down sci-fi action shooter with tactical elements.', 'Infiltrate the secret facility and stop the biological threat.', 'Play the intense Operation Logic Bomb on the SNES.', 'A visually sharp 16-bit shooter. Use high-tech weapons and a holographic decoy to navigate a base filled with traps, robots, and interdimensional monsters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('operation-logic-bomb-usa', 'SNES', 'Operation Logic Bomb (USA)', '1993', 'Action', 'Jaleco', '2', 'Run and Gun', 'Top-down sci-fi action shooter with tactical elements.', 'Restore order to the lab by defeating the rogue experiments.', 'Experience Operation Logic Bomb on the Super Nintendo.', 'Features smooth 16-bit scrolling and challenging puzzles. A hidden gem for fans of action games that require both fast reflexes and careful exploration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('operation-thunderbolt-usa', 'SNES', 'Operation Thunderbolt (USA)', '1994', 'Shooter', 'Taito', '2', 'Light Gun Shooter', 'Light-gun rail shooter and sequel to Operation Wolf.', 'Rescue the hostages and eliminate the terrorist threat.', 'Blast away in Operation Thunderbolt for the SNES.', 'A high-intensity 16-bit port of the arcade classic. Use the Super Scope or controller to mow down enemy forces in this fast-paced military rescue mission.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oraga-land-shusai---best-farmer-shuukakusai-japan', 'SNES', 'Oraga Land Shusai - Best Farmer Shuukakusai (Japan)', '1995', 'Simulation', 'ASCII', '1', 'Farming Simulation', 'Farming and resource management board game hybrid.', 'Become the best farmer by harvesting the most successful crops.', 'Play Oraga Land Shusai on the Super Famicom.', 'A charming 16-bit simulation where you manage a farm and compete in festivals. Features colorful graphics and lighthearted strategic gameplay for the whole family.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oraga-land-shusai---best-farmer-shuukakusai-japan-sample', 'SNES', 'Oraga Land Shusai - Best Farmer Shuukakusai (Japan) (Sample)', '1995', 'Simulation', 'ASCII', '1', 'Farming Simulation', 'Farming and resource management (Development sample).', 'Explore the early town mechanics and farming cycles.', 'Check out the Oraga Land Sample on the Super Famicom.', 'A rare 16-bit pre-release build. Features unpolished menus and experimental crop growth rates used for testing the game''s core economic balance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oscar-europe', 'SNES', 'Oscar (Europe)', '1993', 'Platformer', 'Flair Software', '2', 'Action Platformer', 'Whimsical side-scrolling platformer starring a movie star.', 'Recover the missing film reels across diverse movie sets.', 'Experience the colorful Oscar for the Super Nintendo.', 'A vibrant 16-bit platformer with an Hollywood theme. Navigate through stages based on different film genres, using a magical yo-yo to defeat enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oscar-usa', 'SNES', 'Oscar (USA)', '1993', 'Platformer', 'Flair Software', '2', 'Action Platformer', 'Whimsical side-scrolling platformer starring a movie star.', 'Save the Oscars and defeat the villains in this 16-bit quest.', 'Play Oscar for the Super Nintendo.', 'Master the 16-bit platforming across levels like the Sci-Fi set and the Western town. Features fluid animations and hidden secrets in every movie studio.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ossu!!-karate-bu-japan', 'SNES', 'Ossu!! Karate-bu (Japan)', '1994', 'Action', 'Technos Japan', '2', 'Beat ''em Up', 'One-on-one fighting game based on the delinquent manga.', 'Win the tournament and prove your martial arts dominance.', 'Experience Ossu!! Karate-bu on the Super Famicom.', 'A 16-bit fighter featuring digitized backgrounds and over-the-top special moves. Follow the story of the tough high school brawlers in this cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('othello-world-japan', 'SNES', 'Othello World (Japan)', '1990', 'Board Game', 'Nintendo', '2', 'Board Game', 'The classic board game of strategy and flipping tiles.', 'Outsmart the AI and fill the board with your color.', 'Play Othello World on the Super Famicom.', 'A clean and effective 16-bit rendition of the classic Reversi/Othello game. Features various difficulty levels and charming character avatars.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('otoboke-ninja-colosseum-japan', 'SNES', 'Otoboke Ninja Colosseum (Japan)', '1995', 'Action', 'Anco', '2', 'Arcade Action', 'Competitive action-puzzle game featuring cute ninjas.', 'Defeat your rivals in a Bomberman-style arena battle.', 'Play Otoboke Ninja Colosseum on the Super Famicom.', 'A frantic 16-bit multiplayer gem. Use ninja tools and traps to clear enemies and friends alike in colorful, grid-based combat arenas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('otogirisou-japan', 'SNES', 'Otogirisou (Japan)', '1992', 'Adventure', 'Chunsoft', '1', 'Horror Visual Novel', 'Atmospheric "Sound Novel" and horror adventure.', 'Investigate the creepy mansion and survive the night.', 'Experience the haunting Otogirisou on the Super Famicom.', 'The game that pioneered the 16-bit "Sound Novel" genre. A dark, text-heavy mystery where your choices lead to multiple endings and terrifying outcomes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('out-of-this-world-usa', 'SNES', 'Out of This World (USA)', '1992', 'Action', 'Delphine Software', '1', 'Cinematic Platformer', 'Cinematic action-adventure with revolutionary rotoscoped graphics.', 'Survive a hostile alien world and find a way back home.', 'Experience the masterpiece Out of This World on SNES.', 'A 16-bit cinematic triumph. Known for its minimalist storytelling, challenging puzzles, and fluid animations that feel like an interactive animated film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('out-of-this-world-usa-beta', 'SNES', 'Out of This World (USA) (Beta)', '1992', 'Action', 'Delphine Software', '1', 'Cinematic Platformer', 'Cinematic action-adventure (Pre-release prototype).', 'Test the early physics and cinematic triggers of the alien world.', 'Explore the Out of This World Beta on the SNES.', 'A rare 16-bit development look at a gaming icon. Witness the fine-tuning of the lethal alien encounters and the iconic introductory cutscene.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('out-to-lunch-europe', 'SNES', 'Out to Lunch (Europe)', '1993', 'Platformer', 'Minds Eye', '2', 'Action Platformer', 'Fast-paced platformer about a chef chasing runaway ingredients.', 'Capture the escaping food items across international stages.', 'Play the wacky Out to Lunch on the Super Nintendo.', 'A unique 16-bit platformer. Control Pierre the chef as you travel the world, using your net and flour bombs to catch sentient veggies and fruits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('out-to-lunch-usa', 'SNES', 'Out to Lunch (USA)', '1993', 'Platformer', 'Minds Eye', '2', 'Action Platformer', 'Fast-paced platformer about a chef chasing runaway ingredients.', 'Save your menu by capturing every runaway ingredient.', 'Experience Out to Lunch on the Super Nintendo.', 'Features vibrant 16-bit graphics and a humorous tone. Traverse levels from Switzerland to the Caribbean in this frantic and creative culinary adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('outer-world-japan', 'SNES', 'Outer World (Japan)', '1992', 'Action', 'Delphine Software', '1', 'Cinematic Platformer', 'Cinematic action-adventure (Japanese release of Out of This World).', 'Navigate the alien landscape in the official Japanese version.', 'Experience Outer World on the Super Famicom.', 'The 16-bit Japanese edition of the cult classic. Features the same iconic "Prince of Persia" style movement and unforgiving, atmospheric puzzle-solving.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('outlander-europe', 'SNES', 'Outlander (Europe)', '1992', 'Action', 'U.S. Gold', '1', 'Action Adventure', 'Post-apocalyptic action-driving and shooting hybrid.', 'Drive across the wasteland to rescue your family.', 'Survive the road in Outlander for the Super Nintendo.', 'A unique 16-bit blend of first-person driving (similar to Road Rash) and side-scrolling action. Scavenge for fuel and ammo while fending off road warriors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('outlander-usa', 'SNES', 'Outlander (USA)', '1992', 'Action', 'U.S. Gold', '1', 'Action Adventure', 'Post-apocalyptic action-driving and shooting hybrid.', 'Reach the safe zone in this Mad Max-inspired adventure.', 'Experience the gritty Outlander on the Super Nintendo.', 'Master the 16-bit road combat and on-foot exploration. A challenging title that captures the tension of a desperate journey through a lawless desert.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('p-man-japan', 'SNES', 'P-Man (Japan)', '1994', 'Action', 'Irem', '2', 'Arcade Action', 'Side-scrolling platformer starring the hero of the jungle.', 'Rescue your friends and defeat the evil invaders as P-Man.', 'Play the vibrant P-Man on the Super Famicom.', 'Known as "Prehistorik Man" in the West. A high-quality 16-bit platformer with impressive sound, huge bosses, and a great sense of humor set in the Stone Age.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-attack-europe', 'SNES', 'Pac-Attack (Europe)', '1993', 'Puzzle', 'Namco', '2', 'Falling Block Puzzle', 'Falling-block puzzle game featuring the iconic Pac-Man.', 'Clear the blocks and eat the ghosts to reach the high score.', 'Play the addictive Pac-Attack on the Super Nintendo.', 'A 16-bit twist on the Tetris formula. Drop pieces to line up ghosts for Pac-Man to eat, clearing the board and earning massive point multipliers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-attack-usa', 'SNES', 'Pac-Attack (USA)', '1993', 'Puzzle', 'Namco', '2', 'Falling Block Puzzle', 'Falling-block puzzle game featuring the iconic Pac-Man.', 'Clear the blocks and eat the ghosts to reach the high score.', 'Play the addictive Pac-Attack on the Super Nintendo.', 'Features a challenging Puzzle Mode and competitive 2-player 16-bit action. A colorful and engaging title that remains a favorite for puzzle enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-in-time-europe', 'SNES', 'Pac-in-Time (Europe)', '1994', 'Platformer', 'Milestone', '1', 'Action Platformer', 'Side-scrolling action-platformer featuring a younger Pac-Man.', 'Travel through time and use your gadgets to escape the past.', 'Play Pac-in-Time for the Super Nintendo.', 'A unique 16-bit departure from the maze genre. Use a grappling hook, bubbles, and hammers to navigate levels while collecting pellets in a vibrant, multi-themed world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-in-time-europe-beta', 'SNES', 'Pac-in-Time (Europe) (Beta)', '1994', 'Platformer', 'Milestone', '1', 'Action Platformer', 'Side-scrolling action-platformer (Early European build).', 'Test the grappling physics and early level layouts.', 'Check out the Pac-in-Time Beta on the SNES.', 'A rare 16-bit development look at Pac-Man''s platforming debut. Witness the fine-tuning of the physics-based movement and the evolution of the forest-themed stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-in-time-japan', 'SNES', 'Pac-in-Time (Japan)', '1994', 'Platformer', 'Milestone', '1', 'Action Platformer', 'Side-scrolling action-platformer featuring a younger Pac-Man.', 'Restore the timeline in the official Japanese version.', 'Experience Pac-in-Time on the Super Famicom.', 'The original 16-bit Japanese release. Features charming pixel art and a focus on environmental puzzles that require clever use of Pac-Man''s various abilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-in-time-usa', 'SNES', 'Pac-in-Time (USA)', '1994', 'Platformer', 'Milestone', '1', 'Action Platformer', 'Side-scrolling action-platformer featuring a younger Pac-Man.', 'Navigate the obstacles of the past to return home.', 'Join the adventure in Pac-in-Time for the SNES.', 'Master the 16-bit "swinging" mechanic. A creative platformer that blends Pac-Man''s classic pellet-collecting with modern 90s action-adventure gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-man-europe', 'SNES', 'Pac-Man (Europe)', '1992', 'Arcade', 'Namco', '2', 'Classic Arcade', 'Arcade-perfect port of the world''s most famous maze game.', 'Eat all the pellets while avoiding the four ghosts.', 'Play the legendary Pac-Man on the Super Nintendo.', 'A faithful 16-bit rendition of the arcade icon. Experience the perfect patterns and high-score chasing gameplay that defined the golden age of gaming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-man-usa', 'SNES', 'Pac-Man (USA)', '1992', 'Arcade', 'Namco', '2', 'Classic Arcade', 'Arcade-perfect port of the world''s most famous maze game.', 'Achieve the high score in this faithful North American port.', 'Play the classic Pac-Man on the Super Nintendo.', 'Features vibrant colors and authentic sound effects. This 16-bit release brings the definitive arcade experience to the comfort of the home console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-man-2---the-new-adventures-europe', 'SNES', 'Pac-Man 2 - The New Adventures (Europe)', '1994', 'Adventure', 'Namco', '1', 'Point-and-Click Adventure', 'Interactive adventure where you guide an autonomous Pac-Man.', 'Help Pac-Man complete errands while managing his mood.', 'Play Pac-Man 2: The New Adventures on SNES.', 'A unique 16-bit title. Use a slingshot to interact with the environment and influence Pac-Man''s emotions in this colorful, cartoon-like adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-man-2---the-new-adventures-france', 'SNES', 'Pac-Man 2 - The New Adventures (France)', '1994', 'Adventure', 'Namco', '1', 'Point-and-Click Adventure', 'Interactive adventure with localized French text.', 'Guide Pac-Man through his daily chores in French.', 'Jouez à Pac-Man 2 en français sur le SNES.', 'The complete 16-bit point-and-click adventure with localized menus. Solve puzzles and enjoy the humorous animations of a very moody Pac-Man.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-man-2---the-new-adventures-germany', 'SNES', 'Pac-Man 2 - The New Adventures (Germany)', '1994', 'Adventure', 'Namco', '1', 'Point-and-Click Adventure', 'Interactive adventure with localized German text.', 'Help Pac-Man survive his neighborhood in the German version.', 'Spielen Sie Pac-Man 2 auf Deutsch für das SNES.', 'Experience the 16-bit comedy-adventure with localized German dialogue. Direct Pac-Man through various scenarios using your slingshot and wits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-man-2---the-new-adventures-usa', 'SNES', 'Pac-Man 2 - The New Adventures (USA)', '1994', 'Adventure', 'Namco', '1', 'Point-and-Click Adventure', 'Interactive adventure where you guide an autonomous Pac-Man.', 'Solve the mystery of the Ghost Witch in the USA edition.', 'Experience Pac-Man 2 on the Super Nintendo.', 'Master the 16-bit emotional management. Pac-Man''s reactions change based on how you treat him, leading to hundreds of unique and funny animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachi-slot-gambler-japan', 'SNES', 'Pachi-Slot Gambler (Japan)', '1993', 'Gambling', 'Coconuts Japan', '1', 'Pachislot Simulation', 'Realistic Pachi-Slot gambling simulation.', 'Master the slot machines and build your virtual fortune.', 'Play Pachi-Slot Gambler on the Super Famicom.', 'A detailed 16-bit simulation of Japanese slot parlors. Features multiple machines with unique odds and bonus games for fans of the virtual casino experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachi-slot-kanzen-kouryaku---universal-shindai-nyuuka-volume-1-japan', 'SNES', 'Pachi-Slot Kanzen Kouryaku - Universal Shindai Nyuuka Volume 1 (Japan)', '1994', 'Gambling', 'KSS', '1', 'Pachislot Simulation', 'Universal-brand Pachi-Slot machine simulation (Volume 1).', 'Hit the jackpot on authentic digital slot machines.', 'Experience Universal Pachi-Slot Vol 1 on SNES.', 'Features licensed 16-bit machines with realistic reels and sounds. Manage your coins and try to trigger the "Big Bonus" in this professional-grade simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachi-slot-kenkyuu-japan', 'SNES', 'Pachi-Slot Kenkyuu (Japan)', '1993', 'Gambling', 'Syscom', '1', 'Pachislot Simulation', 'Pachi-Slot research and practice utility.', 'Analyze machine patterns to improve your real-world luck.', 'Play Pachi-Slot Kenkyuu on the Super Famicom.', 'A 16-bit tool designed for serious players. Includes statistical tracking and practice modes for various slot machines to help master the "eye-stop" technique.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachi-slot-land---pachipachi-coin-no-densetsu-japan', 'SNES', 'Pachi-Slot Land - Pachipachi Coin no Densetsu (Japan)', '1994', 'Gambling', 'Coconuts Japan', '1', 'Pachislot Simulation', 'RPG and Pachi-Slot hybrid adventure.', 'Travel through a fantasy land winning battles via slot machines.', 'Explore Pachi-Slot Land on the Super Famicom.', 'A unique 16-bit genre blend. Use your gambling skills to progress through an RPG narrative and defeat bosses in coin-based combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachi-slot-love-story-japan', 'SNES', 'Pachi-Slot Love Story (Japan)', '1995', 'Gambling', 'Coconuts Japan', '1', 'Pachislot Simulation', 'Pachi-Slot simulation with a romantic visual novel twist.', 'Win big at the slots to win the heart of your virtual date.', 'Experience Pachi-Slot Love Story on the Super Famicom.', 'Combines 16-bit gambling gameplay with a dating sim. Interact with various characters and use your winnings to advance the romantic storyline.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachi-slot-monogatari---pal-kougyou-special-japan', 'SNES', 'Pachi-Slot Monogatari - PAL Kougyou Special (Japan)', '1994', 'Gambling', 'KSS', '1', 'Pachislot Simulation', 'Pachi-Slot story and simulation featuring PAL Kougyou machines.', 'Experience the life of a professional gambler in this story mode.', 'Play Pachi-Slot Monogatari on the Super Famicom.', 'A 16-bit simulation that provides a narrative context to the gambling action. Includes realistic machine physics and a quest to become the best player.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachi-slot-monogatari---universal-special-japan', 'SNES', 'Pachi-Slot Monogatari - Universal Special (Japan)', '1995', 'Gambling', 'KSS', '1', 'Pachislot Simulation', 'Pachi-Slot simulation featuring Universal-brand machines.', 'Master the specialized Universal machines in this special edition.', 'Play Pachi-Slot Monogatari: Universal on SNES.', 'Features high-quality 16-bit digital recreations of popular Japanese machines. Includes a practice mode and a story mode focused on the professional gambling scene.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachinko-challenger-japan', 'SNES', 'Pachinko Challenger (Japan)', '1991', 'Gambling', 'Jaleco', '1', 'Pachinko Simulation', 'Traditional Pachinko parlor simulation and challenge.', 'Clear the objectives and win the highest amount of balls.', 'Play Pachinko Challenger on the Super Famicom.', 'A 16-bit recreation of the iconic Japanese ball-bearing game. Features diverse machine layouts and realistic physics for a true parlor atmosphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachinko-fan---shouri-sengen-japan', 'SNES', 'Pachinko Fan - Shouri Sengen (Japan)', '1992', 'Gambling', 'Irem', '1', 'Pachinko Simulation', 'Pachinko simulation with a focus on winning strategies.', 'Follow the "Declaration of Victory" and master the machines.', 'Experience Pachinko Fan: Shouri Sengen on SNES.', 'A technical 16-bit simulation that teaches players how to read the pins and timing of Pachinko machines to maximize their daily winnings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachinko-maruhi-hisshouhou-japan', 'SNES', 'Pachinko Maruhi Hisshouhou (Japan)', '1992', 'Gambling', 'Magical Company', '1', 'Pachinko Simulation', 'Pachinko simulation featuring secret winning techniques.', 'Discover the hidden methods to beat the virtual machines.', 'Play Pachinko Maruhi Hisshouhou on Super Famicom.', 'Features 16-bit guides and tips for mastering popular Pachinko machines. Practice your shots and learn the patterns of the digital reels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachinko-monogatari---pachi-slot-mo-aru-deyo!!-japan', 'SNES', 'Pachinko Monogatari - Pachi-Slot mo Aru deyo!! (Japan)', '1994', 'Gambling', 'KSS', '1', 'Pachinko and Pachislot Simulation', 'Pachinko and Pachi-Slot hybrid simulation and adventure.', 'Master both types of gambling machines in this story mode.', 'Play Pachinko Monogatari on the Super Famicom.', 'A 16-bit title that offers a variety of gambling options. Explore the town, visit different parlors, and manage your bankroll across multiple machines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachinko-monogatari-2---nagoya-shachihoko-no-teiou-japan', 'SNES', 'Pachinko Monogatari 2 - Nagoya Shachihoko no Teiou (Japan)', '1994', 'Gambling', 'KSS', '1', 'Pachinko Simulation', 'Pachinko and Pachi-Slot adventure set in the city of Nagoya.', 'Become the "Emperor of Nagoya" by dominating the parlors.', 'Experience Pachinko Monogatari 2 on Super Famicom.', 'An expanded 16-bit sequel with more machines and a deeper story. Features detailed graphics and more complex NPC interactions within the gambling world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachinko-ren-chan-tengoku---super-cr-special-japan', 'SNES', 'Pachinko Ren-chan Tengoku - Super CR Special (Japan)', '1995', 'Gambling', 'KSS', '1', 'Pachinko Simulation', 'Realistic Pachinko simulation focusing on "Ren-chan" (consecutive win) mechanics.', 'Master the special CR machines to trigger massive winning streaks.', 'Play Pachinko Ren-chan Tengoku on the Super Famicom.', 'A technical 16-bit simulation of high-stakes Pachinko. Features detailed physics for the "Super CR" series of machines, focusing on the adrenaline-pumping moments of consecutive jackpots.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachinko-tetsujin---nanaban-shoubu-japan', 'SNES', 'Pachinko Tetsujin - Nanaban Shoubu (Japan)', '1995', 'Gambling', 'Soft Machine', '1', 'Pachinko Simulation', 'Challenge-based Pachinko simulation against seven masters.', 'Defeat the seven iron-men of Pachinko in high-stakes duels.', 'Experience Pachinko Tetsujin on the Super Famicom.', 'A 16-bit gambling sim with a competitive twist. Face off against expert AI opponents across various machines, requiring precise ball control and a bit of digital luck.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachinko-wars-japan', 'SNES', 'Pachinko Wars (Japan)', '1993', 'Strategy', 'Coconuts Japan', '2', 'Turn-Based Strategy', 'Sci-fi themed Pachinko adventure and simulation.', 'Battle through space by winning on diverse Pachinko machines.', 'Play the intergalactic Pachinko Wars on the SNES.', 'A unique 16-bit blend of space adventure and gambling. Navigate through stages where your progress depends on your performance at themed Pachinko tables.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachinko-wars-ii-japan', 'SNES', 'Pachinko Wars II (Japan)', '1994', 'Strategy', 'Coconuts Japan', '2', 'Turn-Based Strategy', 'Sci-fi themed Pachinko adventure sequel with improved mechanics.', 'Save the galaxy again through the power of Pachinko.', 'Experience Pachinko Wars II on the Super Famicom.', 'An expanded 16-bit sequel featuring more complex machine designs and a deeper narrative. Includes improved animations and new types of interactive digital boards.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachio-kun-special-japan', 'SNES', 'Pachio-kun Special (Japan)', '1995', 'Gambling', 'Coconuts Japan', '1', 'Pachinko Simulation', 'Pachinko adventure starring the series'' round mascot, Pachio-kun.', 'Help Pachio-kun navigate the world of parlors and win big.', 'Join the adventure in Pachio-kun Special on SNES.', 'A 16-bit classic in Japan. Combine light exploration with realistic Pachinko gameplay as the iconic ball-shaped hero visits various themed establishments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachio-kun-special-2-japan', 'SNES', 'Pachio-kun Special 2 (Japan)', '1996', 'Gambling', 'Coconuts Japan', '1', 'Pachinko Simulation', 'Pachinko adventure sequel with a focus on world travel.', 'Journey across different lands and master their Pachinko tables.', 'Play Pachio-kun Special 2 on the Super Famicom.', 'Features improved 16-bit graphics and a wider variety of machines. Follow Pachio-kun''s journey in this lighthearted blend of RPG-lite elements and gambling simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachio-kun-special-3-japan', 'SNES', 'Pachio-kun Special 3 (Japan)', '1997', 'Gambling', 'Coconuts Japan', '1', 'Pachinko Simulation', 'The final entry in the 16-bit Pachio-kun Special trilogy.', 'Complete the ultimate Pachinko challenge in this polished finale.', 'Experience Pachio-kun Special 3 on the Super Famicom.', 'The most refined 16-bit entry in the series. Offers the largest selection of machines and a charming story that concludes Pachio-kun''s Super Famicom adventures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pacific-theater-of-operations-usa', 'SNES', 'Pacific Theater of Operations (USA)', '1994', 'Strategy', 'Koei', '1', 'Turn-Based War Strategy', 'Grand strategy simulation of WWII naval warfare in the Pacific.', 'Command the Allied or Japanese fleet to naval supremacy.', 'Master history in P.T.O. (Pacific Theater of Operations).', 'A massive 16-bit strategic sim from Koei. Manage ship production, fuel, troop morale, and tactical sea battles in a highly detailed historical setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pacific-theater-of-operations-ii-usa', 'SNES', 'Pacific Theater of Operations II (USA)', '1996', 'Strategy', 'Koei', '1', 'Turn-Based War Strategy', 'Advanced grand strategy sequel with improved tactical depth.', 'Lead your navy to victory in this comprehensive WWII sequel.', 'Experience P.T.O. II on the Super Nintendo.', 'Features a much-improved interface and more complex diplomatic options. A 16-bit masterpiece for strategy enthusiasts, covering every aspect of the Pacific war.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('packy-&-marlon-usa-enfres', 'SNES', 'Packy & Marlon (USA) (En,Fr,Es)', '1995', 'Educational', 'Radiation Oncology Center', '2', 'Educational Adventure', 'Educational action-platformer focused on diabetes management.', 'Navigate the summer camp while managing your blood sugar levels.', 'Play the educational Packy & Marlon on the SNES.', 'A unique 16-bit title designed to teach children about health. Collect food and insulin while platforming through diverse levels to keep your character healthy and active.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pagemaster-the-europe', 'SNES', 'Pagemaster, The (Europe)', '1994', 'Platformer', 'Probe Software', '1', 'Cinematic Platformer', 'Fantasy action-platformer based on the animated film.', 'Journey through classic literature worlds to defeat Mr. Hyde.', 'Explore the magical worlds of The Pagemaster on SNES.', 'Enter the worlds of Adventure, Fantasy, and Horror. A 16-bit title featuring creative level design and power-ups based on the library-themed source material.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pagemaster-the-usa', 'SNES', 'Pagemaster, The (USA)', '1994', 'Platformer', 'Probe Software', '1', 'Cinematic Platformer', 'Fantasy action-platformer based on the animated film.', 'Escape the library and find your way back home.', 'Experience The Pagemaster on the Super Nintendo.', 'Master the 16-bit platforming in levels like "The Haunted Mansion" and "Treasure Island." Features vibrant graphics and a nostalgic soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pagemaster-the-usa-beta', 'SNES', 'Pagemaster, The (USA) (Beta)', '1994', 'Platformer', 'Probe Software', '1', 'Cinematic Platformer', 'Fantasy action-platformer (Pre-release build).', 'Explore early level layouts and the "Book" power-up system.', 'Check out The Pagemaster Beta on the Super Nintendo.', 'A rare 16-bit development look. Witness the fine-tuning of the physics and the evolution of the vibrant backgrounds before the final cinematic release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paladins-quest-usa', 'SNES', 'Paladin''s Quest (USA)', '1992', 'RPG', 'Asmik Ace', '1', 'Turn-Based JRPG', 'Unique turn-based RPG with a colorful, alien aesthetic.', 'Restore the world of Lennus by finding the magical spirits.', 'Discover the vibrant Paladin''s Quest on the SNES.', 'Known as "Lennus" in Japan. Features a unique health-based magic system and a surreal 16-bit art style that stands out from typical fantasy RPGs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('panel-de-pon-japan', 'SNES', 'Panel de Pon (Japan)', '1995', 'Puzzle', 'Intelligent Systems', '2', 'Competitive Puzzle', 'Fast-paced block-matching puzzle game with an anime theme.', 'Defeat your rivals in intense competitive puzzle battles.', 'Play the original Panel de Pon on the Super Famicom.', 'The 16-bit precursor to Tetris Attack. Features a charming cast of fairies, addictive "swap and match" gameplay, and a legendary multiplayer mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('panel-de-pon-japan-en-by-zuqkeo-v10', 'SNES', 'Panel de Pon (Japan) [En by Zuqkeo v1.0]', '1995', 'Puzzle', 'Intelligent Systems', '2', 'Competitive Puzzle', 'Fast-paced block-matching puzzle game (English translation).', 'Experience the original Fairy-themed puzzle game in English.', 'Play Panel de Pon in English on the Super Nintendo.', 'A 16-bit fan translation that restores the original Japanese characters and story, making the "Lip''s Stick" world accessible to Western players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('panel-de-pon-japan-t-en-by-zuqkeo-v10', 'SNES', 'Panel de Pon (Japan) [T-En by Zuqkeo v1.0]', '1995', 'Puzzle', 'Intelligent Systems', '2', 'Competitive Puzzle', 'Fast-paced block-matching puzzle game (English translation).', 'Experience the original Fairy-themed puzzle game in English.', 'Play Panel de Pon in English on the Super Nintendo.', 'A 16-bit fan translation that restores the original Japanese characters and story, making the "Lip''s Stick" world accessible to Western players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('panic-in-nakayoshi-world-japan', 'SNES', 'Panic in Nakayoshi World (Japan)', '1994', 'Action', 'Arc System Works', '1', 'Action Platformer', 'Action-puzzle game featuring characters from popular Shoujo manga.', 'Clear the stages and save your friends from the panic.', 'Experience Panic in Nakayoshi World on the Super Famicom.', 'A top-down 16-bit brawler and puzzle hybrid. Play as characters from Sailor Moon and other Nakayoshi series in a cute, Bomberman-style arena environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('panic-in-nakayoshi-world-japan-en-by-project-sailor-moon-v10', 'SNES', 'Panic in Nakayoshi World (Japan) [En by Project Sailor Moon v1.0]', '1994', 'Action', 'Arc System Works', '1', 'Action Platformer', 'Action-puzzle game with a full English fan translation.', 'Join Sailor Moon and friends in English on their quest.', 'Play Panic in Nakayoshi World in English on SNES.', 'The Project Sailor Moon translation makes this 16-bit crossover accessible. Defeat cute enemies and solve grid-based puzzles with your favorite manga heroines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paperboy-2-europe', 'SNES', 'Paperboy 2 (Europe)', '1991', 'Action', 'Tengen', '2', 'Arcade Action', 'Quarter-view arcade action sequel about newspaper delivery.', 'Deliver papers, survive the neighborhood, and upgrade your route.', 'Ride through the chaos of Paperboy 2 on the SNES.', 'An expanded 16-bit sequel featuring more interactive environments, both boy and girl delivery options, and even more bizarre neighborhood hazards like ghosts and cannons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paperboy-2-usa', 'SNES', 'Paperboy 2 (USA)', '1991', 'Action', 'Tengen', '2', 'Arcade Action', 'Quarter-view arcade action sequel about newspaper delivery.', 'Master your bike skills to become the best delivery person.', 'Play the addictive Paperboy 2 on the Super Nintendo.', 'Features classic 16-bit arcade gameplay. Survive the week by hitting targets and avoiding obstacles in this humorous and challenging neighborhood sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parame-rom-cassette-vol-4-japan-unl', 'SNES', 'Parame ROM Cassette Vol. 4 (Japan) (Unl)', '1996', 'Utility', 'Bandai', '1', 'Data Utility', 'Homebrew software collection and digital utility (Volume 4).', 'Explore a variety of fan-made programs and mini-games.', 'Discover Parame ROM Vol. 4 on the Super Famicom.', 'A 16-bit homebrew curiosity. Includes a collection of small games, demos, and utilities developed by the Japanese enthusiast community for the Super Famicom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parame-rom-cassette-vol-5-japan-unl', 'SNES', 'Parame ROM Cassette Vol. 5 (Japan) (Unl)', '1996', 'Utility', 'Bandai', '1', 'Data Utility', 'Homebrew software collection and digital utility (Volume 5).', 'Experience the next batch of independent 16-bit creations.', 'Explore Parame ROM Vol. 5 on the Super Famicom.', 'Continues the 16-bit homebrew tradition with even more experimental software, art showcases, and simple arcade-style games from the underground development scene.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parlor!-mini---pachinko-jikki-simulation-game-japan', 'SNES', 'Parlor! Mini - Pachinko Jikki Simulation Game (Japan)', '1994', 'Gambling', 'Jaleco', '1', 'Pachinko Simulation', 'Miniature Pachinko parlor simulation for quick sessions.', 'Try your luck on various high-quality digital machines.', 'Play Parlor! Mini on the Super Famicom.', 'A compact 16-bit simulation of real-world Pachinko machines. Features accurate ball physics and the "Parlor!" brand''s signature attention to detail in machine mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parlor!-mini---pachinko-jikki-simulation-game-japan-rev-a', 'SNES', 'Parlor! Mini - Pachinko Jikki Simulation Game (Japan) (Rev A)', '1994', 'Gambling', 'Jaleco', '1', 'Pachinko Simulation', 'Miniature Pachinko parlor simulation (Updated Revision).', 'Master the digital reels in this refined miniature version.', 'Play Parlor! Mini (Rev A) on the Super Famicom.', 'An updated 16-bit revision that fixes minor UI glitches and balances the payout rates for a more realistic gambling experience on the console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parlor!-mini-2---pachinko-jikki-simulation-game-japan', 'SNES', 'Parlor! Mini 2 - Pachinko Jikki Simulation Game (Japan)', '1995', 'Gambling', 'Jaleco', '1', 'Pachinko Simulation', 'Realistic Pachinko simulation featuring real machines.', 'Master the digital pins to trigger huge jackpots.', 'Play Parlor! Mini 2 on the Super Famicom.', 'A detailed 16-bit recreation of real-world Pachinko machines. Features accurate ball physics and the specialized "Mini" format for quick simulation sessions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parlor!-mini-3---pachinko-jikki-simulation-game-japan', 'SNES', 'Parlor! Mini 3 - Pachinko Jikki Simulation Game (Japan)', '1995', 'Gambling', 'Jaleco', '1', 'Pachinko Simulation', 'Realistic Pachinko simulation featuring real machines.', 'Study the machine patterns and win virtual coins.', 'Experience Parlor! Mini 3 on the Super Famicom.', 'The third entry in the 16-bit simulation series. Focuses on authentic mechanical recreations and includes various parlor-style bonus modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parlor!-mini-4---pachinko-jikki-simulation-game-japan', 'SNES', 'Parlor! Mini 4 - Pachinko Jikki Simulation Game (Japan)', '1996', 'Gambling', 'Jaleco', '1', 'Pachinko Simulation', 'Realistic Pachinko simulation featuring real machines.', 'Beat the house on a variety of digital tables.', 'Master Parlor! Mini 4 on the Super Famicom.', 'Continues the high-fidelity 16-bit simulation of Japanese parlor gaming. Includes updated machine layouts and refined ball-collision physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parlor!-mini-5---pachinko-jikki-simulation-game-japan', 'SNES', 'Parlor! Mini 5 - Pachinko Jikki Simulation Game (Japan)', '1996', 'Gambling', 'Jaleco', '1', 'Pachinko Simulation', 'Realistic Pachinko simulation featuring real machines.', 'Test your luck and timing on professional machines.', 'Play Parlor! Mini 5 on the Super Famicom.', 'Features the latest 16-bit digital renditions of popular Japanese Pachinko tables. Offers a comprehensive practice mode to master the "eye-stop" technique.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parlor!-mini-6---pachinko-jikki-simulation-game-japan', 'SNES', 'Parlor! Mini 6 - Pachinko Jikki Simulation Game (Japan)', '1997', 'Gambling', 'Jaleco', '1', 'Pachinko Simulation', 'Realistic Pachinko simulation featuring real machines.', 'Analyze the winning probabilities of each table.', 'Experience Parlor! Mini 6 on the Super Famicom.', 'A technical 16-bit simulation that provides a deep dive into Pachinko mechanics. Features professional-grade statistics and authentic machine sounds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parlor!-mini-7---pachinko-jikki-simulation-game-japan', 'SNES', 'Parlor! Mini 7 - Pachinko Jikki Simulation Game (Japan)', '1994', 'Gambling', 'Jaleco', '1', 'Pachinko Simulation', 'Realistic Pachinko simulation featuring real machines.', 'Complete the ultimate parlor challenge in this final Mini entry.', 'Play Parlor! Mini 7 on the Super Famicom.', 'The final 16-bit "Mini" installment. Features the most polished UI of the series and a selection of the era''s most popular physical Pachinko machines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parlor!-parlor!-japan', 'SNES', 'Parlor! Parlor! (Japan)', '1995', 'Gambling', 'Jaleco', '1', 'Pachinko Simulation', 'Advanced Pachinko simulation and parlor management.', 'Climb the ranks of professional players in the city.', 'Discover the world of Parlor! Parlor! on SNES.', 'The main 16-bit series for serious Pachinko fans. Features a larger scope than the "Mini" versions, with more machines and an immersive parlor atmosphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parlor!-parlor!-2-japan', 'SNES', 'Parlor! Parlor! 2 (Japan)', '1995', 'Gambling', 'Jaleco', '1', 'Pachinko Simulation', 'Advanced Pachinko simulation and parlor management.', 'Build your fortune across multiple virtual parlors.', 'Play Parlor! Parlor! 2 on the Super Famicom.', 'An expanded 16-bit sequel with improved graphics. Master the nuances of different machine brands and manage your digital bankroll to become a high-roller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parlor!-parlor!-3-japan', 'SNES', 'Parlor! Parlor! 3 (Japan)', '1996', 'Gambling', 'Jaleco', '1', 'Pachinko Simulation', 'Advanced Pachinko simulation and parlor management.', 'Win the tournament and master new machine types.', 'Experience Parlor! Parlor! 3 on the Super Famicom.', 'Features high-quality 16-bit audio and visual recreations of iconic machines. Includes more complex logic for the digital reels and bonus sequences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parlor!-parlor!-5-japan', 'SNES', 'Parlor! Parlor! 5 (Japan)', '1997', 'Gambling', 'Jaleco', '1', 'Pachinko Simulation', 'Advanced Pachinko simulation and parlor management.', 'Dominate the latest professional parlor tables.', 'Play Parlor! Parlor! 5 on the Super Famicom.', 'The fifth 16-bit installment in the main series. Focuses on the most modern machines of the mid-90s, featuring complex interactive mini-games on the reels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parlor!-parlor!-iv-cr-japan', 'SNES', 'Parlor! Parlor! IV CR (Japan)', '1997', 'Gambling', 'Jaleco', '1', 'Pachinko Simulation', 'Pachinko simulation specializing in "CR" (Card Reader) machines.', 'Master the high-stakes CR machines for massive wins.', 'Play Parlor! Parlor! IV CR on the Super Famicom.', 'A specialized 16-bit sim focused on the "CR" generation of machines. These offered different winning odds and were a staple of Japanese gambling culture.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parodius---non-sense-fantasy-europe', 'SNES', 'Parodius - Non-Sense Fantasy (Europe)', '1991', 'Shooter', 'Konami', '2', 'Arcade Shooter', 'Humorous side-scrolling shoot ''em up (Parody of Gradius).', 'Save the world from the bizarre penguin invasion.', 'Experience the wacky Parodius on the Super Nintendo.', 'A 16-bit masterpiece from Konami. Choose from characters like Vic Viper, TwinBee, or a flying octopus in a surreal journey through levels filled with giant pandas and dancing showgirls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parodius-da!---shinwa-kara-owarai-e-japan', 'SNES', 'Parodius da! - Shinwa Kara Owarai e (Japan)', '1990', 'Shooter', 'Konami', '2', 'Arcade Shooter', 'Humorous side-scrolling shoot ''em up (Japanese version).', 'Fly through the "Non-Sense Fantasy" in the original release.', 'Play Parodius Da! on the Super Famicom.', 'The foundational 16-bit entry in the comedy SHMUP genre. Master the Bell power-up system and enjoy the frantic, colorful, and hilariously absurd combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('peace-keepers-the-usa', 'SNES', 'Peace Keepers, The (USA)', '1992', 'Beat ''em up', 'Jaleco', '2', 'Side-scrolling Beat ''em up', 'Side-scrolling beat ''em up with branching paths and multiple heroes.', 'Stop the terrorist organization and save the world.', 'Fight back in The Peace Keepers for the SNES.', 'Known as "Rushing Beat Shura" in Japan. A deep 16-bit brawler featuring four playable characters, hidden areas, and a variety of endings based on your choices.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pebble-beach-golf-links-europe', 'SNES', 'Pebble Beach Golf Links (Europe)', '1992', 'Sports', 'T&E Soft', '4', 'Golf Simulation', 'Professional golf simulation featuring the world-famous course.', 'Master the 18 holes of Pebble Beach to win the championship.', 'Tee off at Pebble Beach Golf Links on the SNES.', 'A 16-bit sports classic featuring digitized photos of the real course. Master the wind, club selection, and green slopes in this highly realistic simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pebble-beach-golf-links-usa', 'SNES', 'Pebble Beach Golf Links (USA)', '1992', 'Sports', 'T&E Soft', '4', 'Golf Simulation', 'Professional golf simulation featuring the world-famous course.', 'Win the prestigious tournament at Pebble Beach.', 'Experience Pebble Beach Golf Links for the SNES.', 'Features smooth 16-bit ball physics and a variety of modes, including skins and stroke play. A definitive golf experience for the Super Nintendo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pebble-beach-no-hatou-japan', 'SNES', 'Pebble Beach no Hatou (Japan)', '1991', 'Sports', 'T&E Soft', '4', 'Golf Simulation', 'Professional golf simulation (Original Japanese release).', 'Experience the waves and greens of Pebble Beach.', 'Play Pebble Beach no Hatou on the Super Famicom.', 'The foundational 16-bit entry of the series in Japan. Known for its high-quality digitized backgrounds and the technical depth of its swing mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pebble-beach-no-hatou-new---tournament-edition-japan', 'SNES', 'Pebble Beach no Hatou New - Tournament Edition (Japan)', '1993', 'Sports', 'T&E Soft', '4', 'Golf Simulation', 'Professional golf simulation (Enhanced Tournament Edition).', 'Compete in the ultimate tournament on the famous course.', 'Play Pebble Beach no Hatou New on SNES.', 'An updated 16-bit version featuring refined AI for opponents and new tournament structures. Offers the most comprehensive golf challenge in the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pga-european-tour-europe', 'SNES', 'PGA European Tour (Europe)', '1995', 'Sports', 'EA Sports', '4', 'Golf Simulation', 'Professional golf simulation featuring European courses.', 'Win the European Tour and climb the PGA rankings.', 'Tee off in PGA European Tour for the SNES.', 'A detailed 16-bit sports title featuring real European courses like Wentworth. Master the wind and terrain with authentic PGA players and smooth ball physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pga-european-tour-usa', 'SNES', 'PGA European Tour (USA)', '1995', 'Sports', 'EA Sports', '4', 'Golf Simulation', 'Professional golf simulation featuring European courses.', 'Become the champion of the European circuit.', 'Experience PGA European Tour on the Super Nintendo.', 'Features multiple play modes including Skins and Match Play. A technical 16-bit simulation that captures the prestige of international professional golf.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pga-tour-96-europe', 'SNES', 'PGA Tour ''96 (Europe)', '1995', 'Sports', 'EA Sports', '4', 'Golf Simulation', 'Advanced golf simulation with updated 1996 rosters.', 'Master the greens and win the ''96 PGA Championship.', 'Play the polished PGA Tour ''96 on the SNES.', 'Features improved 16-bit digitized graphics and faster UI. Includes real PGA pros and iconic courses with a deep focus on seasonal statistics and player growth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pga-tour-96-usa', 'SNES', 'PGA Tour ''96 (USA)', '1995', 'Sports', 'EA Sports', '4', 'Golf Simulation', 'Advanced golf simulation with updated 1996 rosters.', 'Climb the leaderboard in the definitive ''96 edition.', 'Experience PGA Tour ''96 for the Super Nintendo.', 'The North American release of the acclaimed sim. Offers 16-bit precision controls and realistic environmental factors like green speed and wind direction.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pga-tour-golf-europe', 'SNES', 'PGA Tour Golf (Europe)', '1991', 'Sports', 'EA Sports', '4', 'Golf Simulation', 'The foundational entry in the PGA Tour series for SNES.', 'Win the tournament across world-famous golf courses.', 'Play the classic PGA Tour Golf on the SNES.', 'A landmark 16-bit golf game. Introduced the intuitive three-click swing mechanic and features real-world licensed courses with impressive digitized scenery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pga-tour-golf-japan', 'SNES', 'PGA Tour Golf (Japan)', '1991', 'Sports', 'EA Sports', '4', 'Golf Simulation', 'The foundational entry in the PGA Tour series (Japan).', 'Master the fairway in the official Japanese version.', 'Experience PGA Tour Golf on the Super Famicom.', 'The 16-bit Japanese release of the Western hit. Features localized menus and the same deep tactical gameplay that made the series a global success.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pga-tour-golf-usa', 'SNES', 'PGA Tour Golf (USA)', '1991', 'Sports', 'EA Sports', '4', 'Golf Simulation', 'The foundational entry in the PGA Tour series for SNES.', 'Climb the rankings and become a professional golf legend.', 'Play the classic PGA Tour Golf on the SNES.', 'Features a variety of gameplay modes and authentic PGA rules. A 16-bit sports staple known for its realistic approach to the sport.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phalanx---the-enforce-fighter-a-144-europe', 'SNES', 'Phalanx - The Enforce Fighter A-144 (Europe)', '1991', 'Shooter', 'Kemco', '2', 'Horizontal Shooter', 'Side-scrolling sci-fi shoot ''em up with multiple weapon types.', 'Save the colony of Delia from an alien invasion.', 'Blast through space in Phalanx for the SNES.', 'A technically impressive 16-bit SHMUP. Features large bosses, a flexible power-up system, and smooth scrolling through detailed cavernous and space environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phalanx---the-enforce-fighter-a-144-japan', 'SNES', 'Phalanx - The Enforce Fighter A-144 (Japan)', '1991', 'Shooter', 'Kemco', '2', 'Horizontal Shooter', 'Side-scrolling sci-fi shoot ''em up (Japanese release).', 'Defeat the alien menace in the original Japanese version.', 'Experience Phalanx on the Super Famicom.', 'The original 16-bit release of the cult classic shooter. Known for its atmospheric soundtrack and challenging stages that reward weapon management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phalanx---the-enforce-fighter-a-144-usa', 'SNES', 'Phalanx - The Enforce Fighter A-144 (USA)', '1991', 'Shooter', 'Kemco', '2', 'Horizontal Shooter', 'Side-scrolling sci-fi shoot ''em up (USA release).', 'Protect the universe in this legendary 16-bit shooter.', 'Play the action-packed Phalanx on the SNES.', 'Famous for its bizarre "banjo player" cover art, but underneath is a high-quality 16-bit shooter with tight controls and creative level design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phalanx---the-enforce-fighter-a-144-usa-beta', 'SNES', 'Phalanx - The Enforce Fighter A-144 (USA) (Beta)', '1991', 'Shooter', 'Kemco', '2', 'Horizontal Shooter', 'Side-scrolling sci-fi shoot ''em up (Pre-release build).', 'Test the initial weapon balancing and stage layouts.', 'Check out the Phalanx Beta on the Super Nintendo.', 'A rare 16-bit development look. Witness the early implementation of the ship''s speed settings and the tuning of the enemy spawn patterns.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phantom-2040-europe-enfrde', 'SNES', 'Phantom 2040 (Europe) (En,Fr,De)', '1995', 'Action', 'Viacom', '1', 'Cinematic Action Platformer', 'Action-adventure platformer with branching paths and 20+ endings.', 'Stop the Maximum Inc. corporation and save the future.', 'Explore the deep Phantom 2040 on the SNES.', 'A 16-bit masterpiece of non-linear design. Use gadgets like the grappling hook and specialized guns in a massive, interconnected cyberpunk world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phantom-2040-usa', 'SNES', 'Phantom 2040 (USA)', '1995', 'Action', 'Viacom', '1', 'Cinematic Action Platformer', 'Action-adventure platformer with branching paths and 20+ endings.', 'Find your father and choose your destiny in Metropia.', 'Play the non-linear Phantom 2040 on the SNES.', 'Features incredible world-building and a "Metroidvania" style of exploration. Your 16-bit choices directly impact the fate of the city and the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phantom-2040-usa-beta', 'SNES', 'Phantom 2040 (USA) (Beta)', '1995', 'Action', 'Viacom', '1', 'Cinematic Action Platformer', 'Action-adventure platformer (Pre-release build).', 'Explore early versions of Metropia and the gadget system.', 'Check out the Phantom 2040 Beta on the SNES.', 'A rare 16-bit development slice. Witness the early implementation of the branching dialogue system and the tuning of the protagonist''s movement.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('picachu-world-unl', 'SNES', 'Picachu (World) (Unl)', '1995', 'Unlicensed', 'Unknown', '1', 'Bootleg / Hack', 'Bizarre unofficial platformer featuring a popular mascot.', 'Navigate the levels and collect items in this pirate title.', 'Experience the Picachu homebrew on the SNES.', 'A unique and unpolished 16-bit curiosity. An unofficial release that uses familiar character sprites in a simple platforming engine for the collector''s market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('picross-np-vol-1-japan-np', 'SNES', 'Picross NP Vol. 1 (Japan) (NP)', '1999', 'Puzzle', 'Nintendo', '1', 'Picture Logic Puzzle', 'Picture logic puzzle collection (Nintendo Power release).', 'Solve 16-bit puzzles based on classic Nintendo characters.', 'Play Picross NP Vol. 1 on the Super Famicom.', 'The first in a specialized series of logic games. Features dozens of Nonogram puzzles that reveal iconic Nintendo art once completed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('picross-np-vol-2-japan-np', 'SNES', 'Picross NP Vol. 2 (Japan) (NP)', '1999', 'Puzzle', 'Nintendo', '1', 'Picture Logic Puzzle', 'Picture logic puzzle collection (Vol. 2).', 'Reveal the hidden images in this second logic installment.', 'Challenge Picross NP Vol. 2 on the Super Famicom.', 'Continues the 16-bit puzzle tradition with new grid sizes and a variety of Nintendo-themed rewards for puzzle enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('picross-np-vol-2-japan-rev-a-np', 'SNES', 'Picross NP Vol. 2 (Japan) (Rev A) (NP)', '1999', 'Puzzle', 'Nintendo', '1', 'Picture Logic Puzzle', 'Picture logic puzzle collection (Vol. 2 Updated).', 'Solve even more Nonograms in this refined revision.', 'Play Picross NP Vol. 2 (Rev A) on the Super Famicom.', 'An updated 16-bit revision that fixes minor UI bugs and polishes the puzzle layouts for a smoother logic-solving experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('picross-np-vol-3-japan-np', 'SNES', 'Picross NP Vol. 3 (Japan) (NP)', '1999', 'Puzzle', 'Nintendo', '1', 'Picture Logic Puzzle', 'Picture logic puzzle collection (Vol. 3).', 'Master the 16-bit grid to unlock the secret images.', 'Experience Picross NP Vol. 3 on the Super Famicom.', 'Features a new set of challenging puzzles. A 16-bit logic staple that offers hours of brain-teasing fun for fans of the genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('picross-np-vol-4-japan-np', 'SNES', 'Picross NP Vol. 4 (Japan) (NP)', '1999', 'Puzzle', 'Nintendo', '1', 'Picture Logic Puzzle', 'Picture logic puzzle collection (Vol. 4).', 'Solve the puzzles to see classic SNES characters.', 'Play Picross NP Vol. 4 on the Super Famicom.', 'A specialized 16-bit release through the Nintendo Power service. Features creative puzzle designs and a clean, addictive interface.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('picross-np-vol-5-japan-np', 'SNES', 'Picross NP Vol. 5 (Japan) (NP)', '1999', 'Puzzle', 'Nintendo', '1', 'Picture Logic Puzzle', 'Picture logic puzzle collection (Vol. 5).', 'Complete the grids and uncover the hidden 16-bit art.', 'Challenge Picross NP Vol. 5 on the Super Famicom.', 'Provides a fresh batch of complex Nonograms. Each solved puzzle contributes to a larger gallery of high-quality pixel illustrations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('picross-np-vol-6-japan-np', 'SNES', 'Picross NP Vol. 6 (Japan) (NP)', '1999', 'Puzzle', 'Nintendo', '1', 'Picture Logic Puzzle', 'Picture logic puzzle collection (Vol. 6).', 'Test your logic skills with this sixth puzzle volume.', 'Play Picross NP Vol. 6 on the Super Famicom.', 'Continues the legendary 16-bit puzzle series. Features refined mechanics and a variety of difficulty levels suitable for all players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('picross-np-vol-7-japan-np', 'SNES', 'Picross NP Vol. 7 (Japan) (NP)', '1999', 'Puzzle', 'Nintendo', '1', 'Picture Logic Puzzle', 'Picture logic puzzle collection (Vol. 7).', 'Uncover the secrets of the 16-bit grids in Vol. 7.', 'Experience Picross NP Vol. 7 on the Super Famicom.', 'A late-gen 16-bit puzzle masterpiece. Offers some of the most challenging and rewarding Nonograms in the entire SNES library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('picross-np-vol-8-japan-np', 'SNES', 'Picross NP Vol. 8 (Japan) (NP)', '1999', 'Puzzle', 'Nintendo', '1', 'Picture Logic Puzzle', 'Picture logic puzzle collection (Vol. 8).', 'Complete the final volume of the NP Picross series.', 'Play Picross NP Vol. 8 on the Super Famicom.', 'The final 16-bit installment in the Nintendo Power series. Features the largest variety of puzzles and a celebratory gallery of Nintendo history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pieces-usa', 'SNES', 'Pieces (USA)', '1994', 'Puzzle', 'Bottom Up', '2', 'Block Puzzle', 'Competitive puzzle game involving picture-building and logic.', 'Outsmart your opponent to be the first to finish the puzzle.', 'Challenge your brain in Pieces for the Super Nintendo.', 'A unique 16-bit multiplayer title. Compete against friends or AI to solve Jigsaw-style puzzles while using items to hinder your rivals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pikiinya!-japan', 'SNES', 'Pikiinya! (Japan)', '1993', 'Puzzle', 'Crea-Tech', '2', 'Action Puzzle', 'Cute and colorful competitive action-puzzle game.', 'Clear the board and defeat the quirky Pikiinya creatures.', 'Enjoy the vibrant Pikiinya! on the Super Famicom.', 'A frantic 16-bit puzzle gem. Match blocks and trigger chain reactions in a charming, anime-style world with a strong focus on competitive multiplayer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pilotwings---fastrom', 'SNES', 'Pilotwings - Fastrom', '1990', 'Simulation', 'Nintendo', '1', 'Flight Simulation', 'Optimized version of the flight sim for faster loading/play.', 'Experience Pilotwings with improved 16-bit performance.', 'Play Pilotwings (Fastrom) on the Super Nintendo.', 'A technical 16-bit enhancement that reduces lag and improves data access, making the classic flight training simulation smoother than ever.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pilotwings-europe', 'SNES', 'Pilotwings (Europe)', '1990', 'Simulation', 'Nintendo', '1', 'Flight Simulation', 'Groundbreaking flight training simulation using Mode 7.', 'Earn your pilot''s license across four different disciplines.', 'Take to the skies in Pilotwings for the SNES.', 'A 16-bit technical showcase. Master the light plane, parachute, rocket belt, and hang glider in a revolutionary 3D-perspective environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pilotwings-japan', 'SNES', 'Pilotwings (Japan)', '1990', 'Simulation', 'Nintendo', '1', 'Flight Simulation', 'Groundbreaking flight training simulation (Japanese version).', 'Complete the flight trials in the original Japanese release.', 'Experience Pilotwings on the Super Famicom.', 'The foundational 16-bit release that demonstrated the SNES''s rotation and scaling power. A relaxing yet challenging simulation of aerial athletics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pilotwings-usa', 'SNES', 'Pilotwings (USA)', '1990', 'Simulation', 'Nintendo', '1', 'Flight Simulation', 'Groundbreaking flight training simulation using Mode 7.', 'Become a master pilot and complete the secret mission.', 'Take to the skies in Pilotwings for the SNES.', 'Master the 16-bit "landing" physics. Features iconic music and a high-stakes finale where you must pilot an attack helicopter on a rescue mission.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinball-dreams-europe', 'SNES', 'Pinball Dreams (Europe)', '1992', 'Pinball', 'Digital Illusions', '1', 'Virtual Pinball', 'Realistic pinball simulation with four themed tables.', 'Achieve the high score across Steel Wheel, Ignition, and more.', 'Play the classic Pinball Dreams on the SNES.', 'A faithful 16-bit port of the Amiga hit. Features smooth ball physics and atmospheric sound design across four distinct tables: Ignition, Steel Wheel, Beat It, and Nightmare.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinball-dreams-europe-beta', 'SNES', 'Pinball Dreams (Europe) (Beta)', '1992', 'Pinball', 'Digital Illusions', '1', 'Virtual Pinball', 'Realistic pinball simulation (Pre-release build).', 'Test the early flipper physics and table layouts.', 'Check out the Pinball Dreams Beta on the SNES.', 'A rare 16-bit development slice. Witness the fine-tuning of the ball gravity and the early implementation of the table-specific music tracks before the final release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinball-dreams-usa', 'SNES', 'Pinball Dreams (USA)', '1993', 'Pinball', 'Digital Illusions', '1', 'Virtual Pinball', 'Realistic pinball simulation with four themed tables.', 'Master the ramps and bonuses in this 16-bit pinball staple.', 'Experience Pinball Dreams on the Super Nintendo.', 'Features impressive vertical scrolling and authentic mechanical sounds. Each table offers unique challenges and high-score opportunities for pinball enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinball-fantasies-europe', 'SNES', 'Pinball Fantasies (Europe)', '1993', 'Pinball', 'Digital Illusions', '1', 'Virtual Pinball', 'Advanced pinball simulation with four massive new tables.', 'Set new high scores on Party Land, Speed Devils, and more.', 'Experience the high-speed Pinball Fantasies on SNES.', 'The 16-bit sequel to Pinball Dreams. Features more complex table designs, including the fan-favorite "Stones ''n Bones" and "Billion Dollar Mall" tables.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinball-fantasies-usa', 'SNES', 'Pinball Fantasies (USA)', '1993', 'Pinball', 'Digital Illusions', '1', 'Virtual Pinball', 'Advanced pinball simulation with four massive new tables.', 'Master the intricate bonuses of the four 16-bit tables.', 'Play the addictive Pinball Fantasies on the SNES.', 'Features enhanced graphics and more detailed table events. A definitive 16-bit pinball experience with refined ball physics and high-quality sound effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinball-pinball-japan', 'SNES', 'Pinball Pinball (Japan)', '1995', 'Pinball', 'KAZe', '1', 'Virtual Pinball', 'Traditional Japanese-style pinball simulation.', 'Rack up points and trigger special bonuses on themed tables.', 'Play Pinball Pinball on the Super Famicom.', 'A polished 16-bit arcade title. Features vibrant table art and a variety of challenges designed to test your reflexes and digital flipper skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pink-panther-in-pink-goes-to-hollywood-europe', 'SNES', 'Pink Panther in Pink Goes to Hollywood (Europe)', '1993', 'Platformer', 'Manley & Associates', '1', 'Cinematic Platformer', 'Cinematic action-platformer featuring the iconic Pink Panther.', 'Explore Hollywood movie sets and defeat the Inspector.', 'Join the Pink Panther in Pink Goes to Hollywood.', 'A stylish 16-bit platformer. Navigate through sets based on different film genres, from Westerns to Sci-Fi, while using gadgets to outsmart your enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pink-panther-in-pink-goes-to-hollywood-japan', 'SNES', 'Pink Panther in Pink Goes to Hollywood (Japan)', '1993', 'Platformer', 'Manley & Associates', '1', 'Cinematic Platformer', 'Cinematic action-platformer (Japanese release).', 'Experience Pink Panther''s movie adventure in the Japanese edition.', 'Play Pink Goes to Hollywood on the Super Famicom.', 'The official 16-bit Japanese release. Features the same smooth animations and clever level design that made the Western version a favorite for fans of the show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pink-panther-in-pink-goes-to-hollywood-usa', 'SNES', 'Pink Panther in Pink Goes to Hollywood (USA)', '1993', 'Platformer', 'Manley & Associates', '1', 'Cinematic Platformer', 'Cinematic action-platformer featuring the iconic Pink Panther.', 'Navigate the Hollywood studios and rescue your friends.', 'Experience Pink Goes to Hollywood on the SNES.', 'Master the 16-bit platforming across diverse movie-themed levels. Features charming animations and a variety of power-ups inspired by the classic cartoon series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinocchio-europe', 'SNES', 'Pinocchio (Europe)', '1994', 'Platformer', 'Virgin Interactive', '1', 'Cinematic Platformer', 'Visually stunning action-platformer based on the Disney film.', 'Help Pinocchio become a real boy through various trials.', 'Play Disney''s Pinocchio on the Super Nintendo.', 'Features some of the best 16-bit graphics on the system. Experience the story through diverse gameplay styles, including stealth, puzzles, and traditional platforming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinocchio-japan', 'SNES', 'Pinocchio (Japan)', '1994', 'Platformer', 'Virgin Interactive', '1', 'Cinematic Platformer', 'Visually stunning action-platformer (Japanese release).', 'Guide Pinocchio through the classic Disney story in Japan.', 'Experience Pinocchio on the Super Famicom.', 'The 16-bit Japanese edition of the Disney classic. Known for its incredible fluid animation and a high level of detail that captures the magic of the animated film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinocchio-usa', 'SNES', 'Pinocchio (USA)', '1994', 'Platformer', 'Virgin Interactive', '1', 'Cinematic Platformer', 'Visually stunning action-platformer based on the Disney film.', 'Journey to Pleasure Island and escape the whale Monstro.', 'Play Disney''s Pinocchio on the Super Nintendo.', 'A challenging and beautiful 16-bit adventure. Navigate through expertly crafted levels that follow the iconic movie''s plot with impressive cinematic transitions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pipe-dream-japan', 'SNES', 'Pipe Dream (Japan)', '1992', 'Puzzle', 'LucasArts', '2', 'Logic Puzzle', 'Fast-paced puzzle game about connecting pipes.', 'Connect the pipes to guide the slime to the exit before it leaks.', 'Solve the puzzles in Pipe Dream on the Super Famicom.', 'A 16-bit logic game that requires quick thinking. Build complex plumbing systems against the clock in this addictive and increasingly difficult puzzle classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pirates-of-dark-water-the-europe', 'SNES', 'Pirates of Dark Water, The (Europe)', '1994', 'Action', 'Sunsoft', '1', 'Side-scrolling Action', 'Side-scrolling beat ''em up based on the animated series.', 'Help Ren and his crew find the Treasures of Rule.', 'Experience The Pirates of Dark Water on the SNES.', 'A high-quality 16-bit brawler. Choose from multiple characters, each with unique weapons, and fight through the vibrant world of Mer to stop the evil Bloth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pirates-of-dark-water-the-usa', 'SNES', 'Pirates of Dark Water, The (USA)', '1994', 'Action', 'Sunsoft', '1', 'Side-scrolling Action', 'Side-scrolling beat ''em up based on the animated series.', 'Stop the Dark Water from consuming the world.', 'Play Pirates of Dark Water for the Super Nintendo.', 'Features beautiful 16-bit backgrounds and satisfying combat. A hidden gem in the SNES library that captures the dark, adventurous tone of the cult classic show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pirates-of-dark-water-the-usa-beta', 'SNES', 'Pirates of Dark Water, The (USA) (Beta)', '1994', 'Action', 'Sunsoft', '1', 'Side-scrolling Action', 'Side-scrolling beat ''em up (Pre-release build).', 'Test the character moves and early level layouts of Mer.', 'Check out the Pirates of Dark Water Beta on SNES.', 'A rare 16-bit development look at this licensed brawler. Witness the fine-tuning of the character animations and the early implementation of the special moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pit-fighter-europe', 'SNES', 'Pit-Fighter (Europe)', '1991', 'Fighting', 'Atari Games', '2', 'Arcade Fighting', 'Gritty digitalized-sprite fighting game.', 'Climb the ranks of the illegal pit-fighting circuit.', 'Enter the ring in Pit-Fighter for the SNES.', 'A 16-bit port of the arcade hit. Features real-life digitized actors and a variety of interactive environments where you can use weapons against your brutal opponents.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pit-fighter-usa', 'SNES', 'Pit-Fighter (USA)', '1991', 'Fighting', 'Atari Games', '2', 'Arcade Fighting', 'Gritty digitalized-sprite fighting game.', 'Defeat the champion and claim the title of Pit-Fighter.', 'Experience the arcade-style Pit-Fighter on the SNES.', 'Choose from Buzz, Ty, or Kato in this 16-bit street brawler. Known for its unique aesthetic and the inclusion of crowd interference during matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pitfall---maya-no-daibouken-japan', 'SNES', 'Pitfall - Maya no Daibouken (Japan)', '1994', 'Platformer', 'Activision', '1', 'Action Platformer', 'Action-platformer sequel to the Atari classic.', 'Explore the Mayan ruins to rescue your father, Harry Sr.', 'Join the adventure in Pitfall on the Super Famicom.', 'The 16-bit Japanese release featuring Harry Jr. Master the vine-swinging and boomerang-throwing mechanics in this visually impressive and fast-paced jungle quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pitfall---the-mayan-adventure-europe', 'SNES', 'Pitfall - The Mayan Adventure (Europe)', '1994', 'Platformer', 'Activision', '1', 'Action Platformer', 'Action-platformer sequel to the Atari classic.', 'Survive the jungle traps and defeat the evil Zakelua.', 'Play Pitfall: The Mayan Adventure on the SNES.', 'Features incredibly fluid 16-bit animations and lush jungle environments. Includes the original Atari 2600 game hidden as a secret for nostalgic fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pitfall---the-mayan-adventure-usa', 'SNES', 'Pitfall - The Mayan Adventure (USA)', '1994', 'Platformer', 'Activision', '1', 'Action Platformer', 'Action-platformer sequel to the Atari classic.', 'Master the whip and boomerang to uncover ancient secrets.', 'Experience Pitfall: The Mayan Adventure on the SNES.', 'A landmark 16-bit platformer. Navigate through mines, jungles, and waterfalls while fighting prehistoric creatures and dodging lethal traps.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pitfall---the-mayan-adventure-usa-beta', 'SNES', 'Pitfall - The Mayan Adventure (USA) (Beta)', '1994', 'Platformer', 'Activision', '1', 'Action Platformer', 'Action-platformer (Pre-release build).', 'Test the early jungle physics and vine-swinging mechanics.', 'Check out the Pitfall Beta on the Super Nintendo.', 'A rare 16-bit development slice. Witness the fine-tuning of Harry Jr.''s animations and the evolution of the vibrant Mayan temple backgrounds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('planets-champ-tg-3000-the-japan', 'SNES', 'Planet''s Champ TG 3000, The (Japan)', '1995', 'Racing', 'Taito', '2', 'Futuristic Racing', 'Sci-fi racing simulation with a focus on speed and technology.', 'Win the intergalactic championship in this futuristic racer.', 'Experience The Planet''s Champ TG 3000 on Super Famicom.', 'Known as Top Gear 3000 in the West. A high-speed 16-bit racer featuring car upgrades, planetary tracks, and intense competitive 4-player split-screen action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('plok!-europe', 'SNES', 'Plok! (Europe)', '1993', 'Platformer', 'Software Creations', '1', 'Action Platformer', 'Unique action-platformer where you launch your own limbs.', 'Reclaim your stolen flag from the Fleas across Akrillic.', 'Play the colorful Plok! on the Super Nintendo.', 'A 16-bit gem featuring a unique limb-throwing mechanic and an incredible soundtrack. Master diverse vehicle transformations and explore a vibrant world to defeat the Bobbins brothers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('plok!-france-enfr', 'SNES', 'Plok! (France) (En,Fr)', '1993', 'Platformer', 'Software Creations', '1', 'Action Platformer', 'Unique action-platformer with localized language options.', 'Defeat the Fleas in the French/English edition.', 'Jouez à Plok! en français sur le SNES.', 'Experience the 16-bit charm of Plok! with localized text. Features the same challenging platforming and iconic music that made it a cult classic on the Super Nintendo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('plok!-germany', 'SNES', 'Plok! (Germany)', '1993', 'Platformer', 'Software Creations', '1', 'Action Platformer', 'Unique action-platformer with localized German options.', 'Reclaim your flags in the official German release.', 'Spielen Sie Plok! auf Deutsch für das SNES.', 'The complete 16-bit platforming experience with German language support. Navigate through creative levels and use Plok''s detachable limbs to clear enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('plok!-japan', 'SNES', 'Plok! (Japan)', '1993', 'Platformer', 'Software Creations', '1', 'Action Platformer', 'Unique action-platformer (Japanese release).', 'Master the limb-throwing action in the Japanese edition.', 'Experience Plok! on the Super Famicom.', 'The official 16-bit Japanese release of this Western classic. Known for its high difficulty and the technical brilliance of its multi-layered soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('plok!-usa', 'SNES', 'Plok! (USA)', '1993', 'Platformer', 'Software Creations', '1', 'Action Platformer', 'Unique action-platformer where you launch your own limbs.', 'Stop the Flea invasion and rescue your grandpa.', 'Play the legendary Plok! on the Super Nintendo.', 'A high-quality 16-bit platformer. Use your arms and legs as projectiles and find powerful costumes to grant Plok temporary abilities in this surreal adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocky-&-rocky-europe', 'SNES', 'Pocky & Rocky (Europe)', '1992', 'Action', 'Natsume', '2', 'Run and Gun', 'Top-down "run-and-gun" shooter with a Shinto theme.', 'Defeat the Naughty Spirits and save the Seven Fortune Gods.', 'Play Pocky & Rocky for the Super Nintendo.', 'A 16-bit masterpiece known as Kiki Kaikai in Japan. Features beautiful pixel art and challenging 2-player co-op action as a shrine maiden and her tanuki companion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocky-&-rocky-europe-sample', 'SNES', 'Pocky & Rocky (Europe) (Sample)', '1992', 'Action', 'Natsume', '2', 'Run and Gun', 'Top-down shooter (European development sample).', 'Test the early enemy patterns and Shinto-themed levels.', 'Check out the Pocky & Rocky Sample on the SNES.', 'A rare 16-bit development look. Witness the early implementation of the sliding mechanic and the balancing of Pocky''s ofuda cards before the final release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocky-&-rocky-usa', 'SNES', 'Pocky & Rocky (USA)', '1992', 'Action', 'Natsume', '2', 'Run and Gun', 'Top-down "run-and-gun" shooter with a Shinto theme.', 'Master the cards and wand to stop the demon army.', 'Experience Pocky & Rocky on the Super Nintendo.', 'One of the most beloved 16-bit cooperative titles. Dodge projectiles and fight massive mythological bosses in a vibrant, ancient Japanese setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocky-&-rocky-2-europe', 'SNES', 'Pocky & Rocky 2 (Europe)', '1994', 'Action', 'Natsume', '2', 'Run and Gun', 'Top-down shooter sequel with new characters and partners.', 'Rescue the Moon Princess from the evil Imps.', 'Play Pocky & Rocky 2 for the Super Nintendo.', 'An expanded 16-bit sequel featuring more playable partners and a unique "fusion" mechanic. Master the cooperative puzzles and combat in this colorful adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocky-&-rocky-2-usa', 'SNES', 'Pocky & Rocky 2 (USA)', '1994', 'Action', 'Natsume', '2', 'Run and Gun', 'Top-down shooter sequel with new characters and partners.', 'Stop the kidnapping and restore peace to the land.', 'Experience Pocky & Rocky 2 on the Super Nintendo.', 'Features more interactive environments and specialized partner abilities. A high-energy 16-bit shooter that rewards teamwork and precision movement.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocky-&-rocky-2-usa-beta', 'SNES', 'Pocky & Rocky 2 (USA) (Beta)', '1994', 'Action', 'Natsume', '2', 'Run and Gun', 'Top-down shooter sequel (Pre-release build).', 'Explore early partner mechanics and boss encounters.', 'Check out the Pocky & Rocky 2 Beta on the SNES.', 'A rare 16-bit development slice. Witness the tuning of the partner AI and the early layouts of the fantasy-themed forest stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('poi-poi-ninja-world-japan-st', 'SNES', 'Poi Poi Ninja World (Japan) (ST)', '1993', 'Action', 'Taito', '2', 'Arcade Action', 'Fast-paced competitive action game featuring ninjas.', 'Defeat your rivals in a variety of ninja-themed mini-games.', 'Play Poi Poi Ninja World on the Super Famicom.', 'A frantic 16-bit multiplayer title for the Sufami Turbo accessory. Use quick reflexes to outperform opponents in stylized arena challenges and combat drills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('poko-nyan!---henpokorin-adventure-japan', 'SNES', 'Poko Nyan! - Henpokorin Adventure (Japan)', '1993', 'Platformer', 'TOSE', '1', 'Cute Platformer', 'Adorable side-scrolling platformer based on the anime.', 'Navigate through colorful levels as the shape-shifting Poko Nyan.', 'Join Poko Nyan! on the Super Famicom.', 'A charming 16-bit title featuring creative transformations. Perfect for younger players, it offers bright visuals and lighthearted platforming action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('popn-twinbee---rainbow-bell-adventures-europe', 'SNES', 'Pop''n TwinBee - Rainbow Bell Adventures (Europe)', '1994', 'Platformer', 'Konami', '2', 'Cute Platformer', 'Action-platformer spinoff of the famous SHMUP series.', 'Rescue the princess and find the legendary bells.', 'Play Pop''n TwinBee: Rainbow Bell Adventures on SNES.', 'A 16-bit departure for the series, focusing on exploration and platforming. Use your hammer and jetpack to navigate massive, non-linear levels in a vibrant world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('popn-twinbee---rainbow-bell-adventures-germany', 'SNES', 'Pop''n TwinBee - Rainbow Bell Adventures (Germany)', '1994', 'Platformer', 'Konami', '2', 'Cute Platformer', 'Action-platformer spinoff with localized German text.', 'Collect the rainbow bells in the official German version.', 'Spielen Sie Rainbow Bell Adventures auf Deutsch.', 'The complete 16-bit Konami platformer with German dialogue. Explore a "Metroidvania-lite" world with multiple paths and secret areas to uncover.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('popn-twinbee-europe', 'SNES', 'Pop''n TwinBee (Europe)', '1992', 'Shooter', 'Konami', '2', 'Arcade Shooter', 'Vertical-scrolling "cute ''em up" with 2-player co-op.', 'Blast through candy-colored skies and defeat bizarre bosses.', 'Play Pop''n TwinBee for the Super Nintendo.', 'A classic 16-bit SHMUP featuring the iconic Bell power-up system. Enjoy fluid animations and a lighthearted atmosphere in this technically polished shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('popn-twinbee-japan', 'SNES', 'Pop''n TwinBee (Japan)', '1992', 'Shooter', 'Konami', '2', 'Arcade Shooter', 'Vertical-scrolling "cute ''em up" (Original Japanese release).', 'Experience the original "TwinBee" magic in Japan.', 'Play Pop''n TwinBee on the Super Famicom.', 'Known for its incredible pastel-colored graphics and catchy soundtrack. Master the 16-bit air-to-ground combat and the unique "throwing" mechanic in co-op mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('popn-twinbee-japan-sample', 'SNES', 'Pop''n TwinBee (Japan) (Sample)', '1992', 'Shooter', 'Konami', '2', 'Arcade Shooter', 'Vertical-scrolling "cute ''em up" (Development sample).', 'Test the early ship physics and bell-dropping rates.', 'Explore the Pop''n TwinBee Sample on the SNES.', 'A rare 16-bit development look. Witness the initial implementation of the character dialogue portraits and the tuning of the enemy formation logic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('popeye---ijiwaru-majo-sea-hag-no-maki-japan', 'SNES', 'Popeye - Ijiwaru Majo Sea Hag no Maki (Japan)', '1994', 'Action', 'SNK', '1', 'Arcade Action', 'Action-adventure board game hybrid starring the famous sailor.', 'Defeat the Sea Hag across a variety of themed boards.', 'Play Popeye on the Super Famicom.', 'A unique 16-bit blend of digital board game and action mini-games. Compete to collect items and reach the finish line while avoiding the witch''s traps.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('popeye---ijiwaru-majo-sea-hag-no-maki-japan-en-by-kingmike-v10-~popeye---tale-of-teasing-witch-sea-hag', 'SNES', 'Popeye - Ijiwaru Majo Sea Hag no Maki (Japan) [En by KingMike v1.0] (~Popeye - Tale of Teasing Witch Sea Hag)', '1994', 'Action', 'SNK', '1', 'Arcade Action', 'Action-adventure board game hybrid (English translation).', 'Experience Popeye''s quest against the Sea Hag in English.', 'Play Popeye''s 16-bit adventure in English on SNES.', 'The KingMike translation makes this quirky board game accessible. Follow the story of Popeye and Olive Oyl with full English dialogue and menus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('popful-mail-japan', 'SNES', 'Popful Mail (Japan)', '1994', 'RPG', 'Falcom', '1', 'Action RPG', 'Side-scrolling Action-RPG with high-quality anime cutscenes.', 'Hunt monsters and claim bounties as the energetic Popful Mail.', 'Experience Popful Mail on the Super Famicom.', 'A vibrant 16-bit adventure from Falcom. Features fluid swordplay, multiple playable characters, and a humorous story filled with cinematic storytelling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('popoitto-hebereke-japan', 'SNES', 'Popoitto Hebereke (Japan)', '1993', 'Puzzle', 'Sunsoft', '2', 'Action Puzzle', 'Competitive block-matching puzzle game with a wacky theme.', 'Outsmart your opponents in this Hebereke spinoff.', 'Play Popoitto Hebereke on the Super Famicom.', 'A frantic 16-bit puzzle gem. Match falling blocks to trigger chain reactions and send obstacles to your rivals in a colorful and surreal world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('populous-europe', 'SNES', 'Populous (Europe)', '1991', 'Strategy', 'Bullfrog Productions', '1', 'God Game', 'Groundbreaking "God Game" and strategy simulation.', 'Guide your followers to prosperity and conquer rival deities.', 'Play the classic Populous on the Super Nintendo.', 'A landmark 16-bit strategy title. Reshape the landscape with divine powers to help your civilization grow and eventually overwhelm the enemy''s followers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('populous-japan', 'SNES', 'Populous (Japan)', '1991', 'Strategy', 'Bullfrog Productions', '1', 'God Game', 'Groundbreaking "God Game" (Japanese release).', 'Unify the land under your divinity in the Japanese edition.', 'Experience Populous on the Super Famicom.', 'The official 16-bit Japanese release of Peter Molyneux''s masterpiece. Features intuitive controls and a deep simulation of world-building and warfare.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('populous-usa', 'SNES', 'Populous (USA)', '1991', 'Strategy', 'Bullfrog Productions', '1', 'God Game', 'Groundbreaking "God Game" and strategy simulation.', 'Master the elements to ensure the dominance of your people.', 'Play the legendary Populous on the Super Nintendo.', 'One of the first 16-bit titles to offer a true sense of scale. Use earthquakes, floods, and volcanoes to destroy rival tribes in this addictive simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('populous-ii---trials-of-the-olympian-gods-europe', 'SNES', 'Populous II - Trials of the Olympian Gods (Europe)', '1994', 'Strategy', 'Bullfrog Productions', '1', 'God Game', 'Expanded "God Game" strategy set in Greek Mythology.', 'Prove your divinity by defeating rival gods and reaching Olympus.', 'Play Populous II: Trials of the Olympian Gods on SNES.', 'A massive 16-bit sequel. Features over 30 divine powers, from lightning bolts to tidal waves, and hundreds of levels where you guide your followers to victory against enemy deities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('populous-ii---trials-of-the-olympian-gods-germany', 'SNES', 'Populous II - Trials of the Olympian Gods (Germany)', '1994', 'Strategy', 'Bullfrog Productions', '1', 'God Game', 'Expanded "God Game" strategy (German localization).', 'Become the supreme god in the official German release.', 'Spielen Sie Populous II auf Deutsch für das SNES.', 'The complete 16-bit strategy experience with localized German text. Manage your civilization and use mythical powers to dominate the ancient world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('populous-ii---trials-of-the-olympian-gods-japan', 'SNES', 'Populous II - Trials of the Olympian Gods (Japan)', '1994', 'Strategy', 'Bullfrog Productions', '1', 'God Game', 'Expanded "God Game" strategy (Japanese release).', 'Challenge the Olympian gods in the Japanese edition.', 'Experience Populous II on the Super Famicom.', 'The 16-bit Japanese release featuring a refined interface. Offers a deep simulation of divine warfare and terrain manipulation across a vast mythological landscape.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('porky-pigs-haunted-holiday-europe', 'SNES', 'Porky Pig''s Haunted Holiday (Europe)', '1995', 'Platformer', 'Daydream Software', '1', 'Action Platformer', 'Atmospheric side-scrolling platformer starring Porky Pig.', 'Survive Porky''s nightmares in this spooky holiday quest.', 'Play Porky Pig''s Haunted Holiday on the SNES.', 'A charming 16-bit platformer known for its changing weather effects and surreal level design. Help Porky navigate through haunted forests and snowy mountains.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('porky-pigs-haunted-holiday-usa', 'SNES', 'Porky Pig''s Haunted Holiday (USA)', '1995', 'Platformer', 'Daydream Software', '1', 'Action Platformer', 'Atmospheric side-scrolling platformer starring Porky Pig.', 'Escape the spooky dream worlds and wake up safely.', 'Experience Porky Pig''s Haunted Holiday on the SNES.', 'Features fluid 16-bit animations and diverse environments. Battle ghostly enemies and solve light puzzles in this high-quality Looney Tunes adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('porky-pigs-haunted-holiday-usa-beta', 'SNES', 'Porky Pig''s Haunted Holiday (USA) (Beta)', '1995', 'Platformer', 'Daydream Software', '1', 'Action Platformer', 'Atmospheric side-scrolling platformer (Pre-release build).', 'Test the early weather transitions and spooky level layouts.', 'Check out the Porky Pig Beta on the Super Nintendo.', 'A rare 16-bit development look. Witness the early implementation of the seasonal background changes and the tuning of Porky''s movement physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-athlete-japan', 'SNES', 'Power Athlete (Japan)', '1993', 'Sports', 'Human Entertainment', '2', 'Arcade Sports', 'One-on-one fighting game with a diverse cast of global warriors.', 'Defeat the world''s strongest fighters in the original Japanese version.', 'Experience Power Athlete on the Super Famicom.', 'Known as Power Moves in the West. A unique 16-bit fighter featuring an 8-way movement system and large character sprites in various international locations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-drive-europe-enfrdeespt', 'SNES', 'Power Drive (Europe) (En,Fr,De,Es,Pt)', '1994', 'Racing', 'Rage Software', '1', 'Rally Racing', 'Top-down rally racing simulation with technical driving.', 'Win the international rally championship across diverse terrains.', 'Master the road in Power Drive for the Super Nintendo.', 'A challenging 16-bit racer. Features realistic car handling, weather effects, and diverse tracks ranging from snowy mountains to muddy forests.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-instinct-usa', 'SNES', 'Power Instinct (USA)', '1994', 'Fighting', 'Atlus', '2', 'Arcade Fighting', 'Quirky one-on-one fighting game with eccentric characters.', 'Win the tournament in this bizarre and fast-paced brawler.', 'Experience Power Instinct on the Super Nintendo.', 'A cult-classic 16-bit fighter. Known for its humorous special moves and the iconic elderly twins, Otane and Oume, who use their dentures as projectiles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-instinct-usa-beta', 'SNES', 'Power Instinct (USA) (Beta)', '1994', 'Fighting', 'Atlus', '2', 'Arcade Fighting', 'Quirky one-on-one fighting game (Pre-release build).', 'Test the character balancing and special move inputs.', 'Check out the Power Instinct Beta on the SNES.', 'A rare 16-bit development look at Atlus''s eccentric brawler. Witness the early implementation of the transformation mechanics and stage backgrounds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-journey-demo-by-blueskye209', 'SNES', 'Power Journey (Demo) by BlueSkye209', '2023', 'Action', 'BlueSkye209', '1', 'Homebrew Action', 'Homebrew action-platformer demo.', 'Navigate the experimental levels in this modern 16-bit showcase.', 'Play the Power Journey Demo on the SNES.', 'A modern indie project for the Super Nintendo. Features smooth 16-bit controls and demonstrates potential for a new high-quality action adventure on retro hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-lode-runner-japan-np', 'SNES', 'Power Lode Runner (Japan) (NP)', '1999', 'Puzzle', 'Hudson Soft', '2', 'Action Puzzle', 'Updated version of the classic trap-setting puzzle game.', 'Collect all the gold and avoid the guards in this enhanced port.', 'Play Power Lode Runner on the Super Famicom.', 'A 16-bit update to the arcade legend. Features a level editor, improved graphics, and the same addictive puzzle-action gameplay that defined the original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-moves-usa', 'SNES', 'Power Moves (USA)', '1993', 'Fighting', 'System Vision', '2', 'Arcade Fighting', 'One-on-one fighting game with a deep training system.', 'Rise through the ranks and become the world''s best fighter.', 'Experience Power Moves on the Super Nintendo.', 'Features a unique 16-bit movement system that allows players to move between the background and foreground, adding a tactical layer to the combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-of-the-hired-japan', 'SNES', 'Power of the Hired (Japan)', '1992', 'Action', 'NCS', '1', 'Action Adventure', 'Tactical JRPG with a focus on summoning and unit management.', 'Lead your mercenaries to victory in grid-based fantasy battles.', 'Explore Power of the Hired on the Super Famicom.', 'A rare 16-bit tactical RPG. Manage a team of mages and warriors, using powerful summoning spells to turn the tide of war in a dark fantasy setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-piggs-of-the-dark-age-europe', 'SNES', 'Power Piggs of the Dark Age (Europe)', '1994', 'Platformer', 'Raise', '1', 'Action Platformer', 'Side-scrolling action-platformer featuring anthropomorphic pigs.', 'Stop the evil wizard and save the kingdom in the Dark Ages.', 'Play Power Piggs of the Dark Age on the SNES.', 'A vibrant 16-bit platformer with a humorous tone. Use medieval weapons and food-based power-ups to defeat waves of enemies in a cartoon-inspired world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-piggs-of-the-dark-age-europe-beta', 'SNES', 'Power Piggs of the Dark Age (Europe) (Beta)', '1994', 'Platformer', 'Raise', '1', 'Action Platformer', 'Side-scrolling action-platformer (Pre-release build).', 'Explore early medieval level designs and pig animations.', 'Check out the Power Piggs Beta on the SNES.', 'A rare 16-bit development slice. Witness the fine-tuning of the sword-swinging mechanics and the evolution of the vibrant kingdom backgrounds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-piggs-of-the-dark-age-usa', 'SNES', 'Power Piggs of the Dark Age (USA)', '1994', 'Platformer', 'Raise', '1', 'Action Platformer', 'Side-scrolling action-platformer featuring anthropomorphic pigs.', 'Restore peace to the land of the Piggs in this 16-bit quest.', 'Experience Power Piggs of the Dark Age on the SNES.', 'Features large character sprites and creative level design. A hidden 16-bit gem for fans of 90s mascot platformers and lighthearted action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-rangers-zeo---battle-racers-europe', 'SNES', 'Power Rangers Zeo - Battle Racers (Europe)', '1996', 'Racing', 'Natsume', '2', 'Arcade Kart Racing', 'Combat-based racing game featuring the Zeo Rangers.', 'Win the intergalactic race using weapons and speed boosts.', 'Race for victory in Power Rangers Zeo on the SNES.', 'A 16-bit racer inspired by Mario Kart. Choose your favorite Zeo Ranger and navigate treacherous tracks while using special power-ups to disable your rivals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-rangers-zeo---battle-racers-usa', 'SNES', 'Power Rangers Zeo - Battle Racers (USA)', '1996', 'Racing', 'Natsume', '2', 'Arcade Kart Racing', 'Combat-based racing game featuring the Zeo Rangers.', 'Claim the gold in this high-octane 16-bit racing tournament.', 'Play Power Rangers Zeo: Battle Racers on the SNES.', 'Features a variety of vehicles and tracks from the TV show. Master the 16-bit drifting and weapon management to defeat King Mondos forces.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-soukoban---english-v10', 'SNES', 'Power Soukoban - English v1.0', '1990', 'Puzzle', 'Thinking Rabbit', '1', 'Logic Puzzle', 'Classic block-pushing puzzle game (English translation).', 'Solve increasingly difficult puzzles to clear the board.', 'Play Power Soukoban in English on the Super Nintendo.', 'A 16-bit fan translation of the Japanese logic classic. Includes dozens of levels that test your spatial reasoning and strategic planning.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-soukoban-japan', 'SNES', 'Power Soukoban (Japan)', '1990', 'Puzzle', 'Thinking Rabbit', '1', 'Logic Puzzle', 'Classic block-pushing puzzle game with an action twist.', 'Navigate the warehouse and solve the sokoban challenges.', 'Experience Power Soukoban on the Super Famicom.', 'A polished 16-bit puzzle game. Features a story mode and a clean interface for solving the legendary block-pushing enigmas of the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('powermonger---mashou-no-bouryaku-japan', 'SNES', 'PowerMonger - Mashou no Bouryaku (Japan)', '1993', 'Strategy', 'Bullfrog Productions', '1', 'Real-Time Strategy', 'Grand strategy and management sim sequel to Populous.', 'Conquer the land through military force and resource management.', 'Master the world in PowerMonger on the Super Famicom.', 'A deep 16-bit strategy title from Bullfrog. Manage supply lines, forge alliances, and lead your armies across a massive, persistent 3D-perspective world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('powermonger-europe', 'SNES', 'PowerMonger (Europe)', '1993', 'Strategy', 'Bullfrog Productions', '1', 'Real-Time Strategy', 'Grand strategy and management sim sequel to Populous.', 'Unify the continent under your banner in this strategic epic.', 'Experience PowerMonger on the Super Nintendo.', 'Features a complex 16-bit simulation engine where weather and terrain affect your troops. A rewarding experience for fans of serious military strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('powerup-patch-v130', 'SNES', 'Powerup Patch (V1.3.0)', '2022', 'Utility', 'Community', '1', 'Modification Patch', 'Modern engine enhancement patch for various SNES titles.', 'Optimize your 16-bit gaming experience with improved code.', 'Get the Powerup Patch V1.3.0 for the SNES.', 'A technical 16-bit modification that improves loading times, reduces slowdown, and fixes minor engine bugs in a variety of supported Super Nintendo games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prehistorik-man-europe-enfrde', 'SNES', 'Prehistorik Man (Europe) (En,Fr,De)', '1995', 'Platformer', 'Titus Interactive', '1', 'Action Platformer', 'High-quality side-scrolling platformer with a stone-age theme.', 'Rescue your village''s food supply and defeat the dinosaurs.', 'Join the quest in Prehistorik Man on the SNES.', 'A visually stunning 16-bit platformer. Features incredible sprite work, huge bosses, and a variety of creative levels including high-speed chase sequences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prehistorik-man-usa', 'SNES', 'Prehistorik Man (USA)', '1995', 'Platformer', 'Titus Interactive', '1', 'Action Platformer', 'High-quality side-scrolling platformer with a stone-age theme.', 'Master the prehistoric tools to save your tribe.', 'Experience Prehistorik Man on the Super Nintendo.', 'Known for its impressive 16-bit sound and fluid animations. A top-tier platformer that combines humor, exploration, and challenging boss fights.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('primal-rage-europe', 'SNES', 'Primal Rage (Europe)', '1994', 'Fighting', 'Atari Games', '2', 'Arcade Fighting', 'One-on-one fighting game featuring stop-motion prehistoric beasts.', 'Defeat the rival gods to rule over the post-apocalyptic Urth.', 'Play the brutal Primal Rage on the Super Nintendo.', 'A unique 16-bit fighter with digitized stop-motion animation. Control massive dinosaurs and giant apes, using primal powers and finishers in a fight for global dominance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('primal-rage-usa', 'SNES', 'Primal Rage (USA)', '1995', 'Fighting', 'Atari Games', '2', 'Arcade Fighting', 'One-on-one fighting game featuring stop-motion prehistoric beasts.', 'Conquer the Urth in the definitive North American version.', 'Experience Primal Rage for the Super Nintendo.', 'Features a unique combo system and specialized "fatality" style moves. A 16-bit arcade port that captures the gritty atmosphere of the original hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('primal-rage-usa-beta', 'SNES', 'Primal Rage (USA) (Beta)', '1995', 'Fighting', 'Atari Games', '2', 'Arcade Fighting', 'One-on-one fighting game (Pre-release build).', 'Test the early animation frames and hitboxes of the beasts.', 'Check out the Primal Rage Beta on the SNES.', 'A rare 16-bit development look. Witness the fine-tuning of the dinosaur special moves and the evolution of the detailed, post-apocalyptic stage backgrounds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prime-usa-proto', 'SNES', 'Prime (USA) (Proto)', '1994', 'Action', 'Atlus', '1', 'Action Adventure', 'Action-adventure platformer based on the comic book hero (Prototype).', 'Stop the villains and master your newfound superpowers.', 'Explore the unreleased Prime Proto on the SNES.', 'A rare 16-bit prototype featuring the Ultraverse superhero. Explore non-linear levels and use super-strength to defeat enemies in this unreleased comic book adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prince-of-persia-europe', 'SNES', 'Prince of Persia (Europe)', '1992', 'Platformer', 'Broderbund', '1', 'Cinematic Platformer', 'Cinematic platformer with realistic rotoscoped movement.', 'Escape the dungeon and rescue the Princess in under 60 minutes.', 'Play the definitive Prince of Persia on the SNES.', 'The best 16-bit version of the classic. Features expanded levels, improved graphics, new boss fights, and a beautiful orchestral soundtrack not found in other ports.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prince-of-persia-japan', 'SNES', 'Prince of Persia (Japan)', '1992', 'Platformer', 'Broderbund', '1', 'Cinematic Platformer', 'Cinematic platformer with realistic rotoscoped movement (Japan).', 'Navigate the Sultan''s palace in the official Japanese release.', 'Experience Prince of Persia on the Super Famicom.', 'The 16-bit Japanese edition featuring the same expanded content and fluid animations that made the SNES version a standout cinematic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prince-of-persia-usa', 'SNES', 'Prince of Persia (USA)', '1992', 'Platformer', 'Broderbund', '1', 'Cinematic Platformer', 'Cinematic platformer with realistic rotoscoped movement.', 'Rescue the Princess and defeat Jaffar in this 16-bit epic.', 'Play the classic Prince of Persia on the Super Nintendo.', 'Master the 16-bit sword fighting and environmental puzzles. This version doubles the length of the original game with new traps and secret rooms.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prince-of-persia-2---the-shadow-&-the-flame-europe', 'SNES', 'Prince of Persia 2 - The Shadow & The Flame (Europe)', '1993', 'Platformer', 'Broderbund', '1', 'Cinematic Platformer', 'Cinematic platformer sequel with enhanced combat and visuals.', 'Discover your true identity and reclaim your kingdom.', 'Experience Prince of Persia 2 on the Super Nintendo.', 'A visually stunning 16-bit sequel. Features more complex combat, diverse environments from deserts to ruins, and a deeper focus on the cinematic narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prince-of-persia-2---the-shadow-&-the-flame-usa', 'SNES', 'Prince of Persia 2 - The Shadow & The Flame (USA)', '1993', 'Platformer', 'Broderbund', '1', 'Cinematic Platformer', 'Cinematic platformer sequel with enhanced combat and visuals.', 'Uncover the secrets of the past and defeat the Shadow.', 'Play Prince of Persia 2: The Shadow & The Flame on SNES.', 'Master the improved 16-bit platforming and swordplay. A challenging adventure that expands on the mechanics of the first game with larger, more detailed stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-maker---legend-of-another-world-japan', 'SNES', 'Princess Maker - Legend of Another World (Japan)', '1994', 'Simulation', 'Gainax', '1', 'Life Simulation', 'Life simulation and "breeding" game featuring a fantasy setting.', 'Raise your adopted daughter to adulthood and shape her future.', 'Play Princess Maker on the Super Famicom.', 'A landmark 16-bit simulation. Manage your daughter''s education, part-time jobs, and social life to unlock dozens of different endings based on your choices.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-minerva-english', 'SNES', 'Princess Minerva (English)', '1993', 'Action', 'Telenet Japan', '1', 'Action RPG', 'Turn-based RPG with an all-female cast and tactical combat.', 'Lead your team of warriors to stop an ancient evil.', 'Experience Princess Minerva in English on the SNES.', 'A 16-bit JRPG with a focus on character interactions and equipment management. The fan translation makes this colorful, anime-styled adventure accessible to everyone.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-minerva-japan', 'SNES', 'Princess Minerva (Japan)', '1993', 'Action', 'Telenet Japan', '1', 'Action RPG', 'Turn-based RPG with an all-female cast and tactical combat.', 'Build your party and save the kingdom in the original release.', 'Play Princess Minerva on the Super Famicom.', 'Features vibrant 16-bit pixel art and a humorous tone. A classic RPG experience that emphasizes party balance and strategic turn-based encounters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-now-hero-with-cape', 'SNES', 'Princess now hero With Cape', '2022', 'Platformer', 'Homebrew', '1', 'Fan Platformer', 'Fan-made Mario World hack where Princess Peach is the hero.', 'Rescue Mario and save the kingdom with the Cape Feather.', 'Play Princess now hero With Cape on the SNES.', 'A creative 16-bit romhack that swaps the roles. Use Peach''s unique flight mechanics with the Cape to navigate challenging custom-designed Mario World levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-now-hero-with-super-leaf', 'SNES', 'Princess now hero With Super Leaf', '2022', 'Platformer', 'Homebrew', '1', 'Fan Platformer', 'Fan-made Mario World hack where Princess Peach is the hero.', 'Rescue Mario while using the power of the Super Leaf.', 'Play Princess now hero With Super Leaf on the SNES.', 'A 16-bit modification that introduces the Raccoon suit for Peach. Features custom level design focused on vertical exploration and floating mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-football-93-japan', 'SNES', 'Pro Football ''93 (Japan)', '1993', 'Sports', 'TOSE', '2', 'American Football', 'Professional American football simulation (1993 rosters).', 'Win the championship in the refined Japanese version.', 'Play Pro Football ''93 on the Super Famicom.', 'Features official 16-bit team logos and updated player stats for the ''93 season. A solid simulation with a focus on tactical play-calling and seasonal tracking.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-football-japan', 'SNES', 'Pro Football (Japan)', '1992', 'Sports', 'TOSE', '2', 'American Football', 'Professional American football simulation.', 'Lead your team to the Super Bowl in this 16-bit sim.', 'Experience Pro Football on the Super Famicom.', 'The foundational 16-bit football title for the Japanese market. Features a comprehensive playbook and realistic player attributes for the early 90s era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-kishi-jinsei-simulation---shougi-no-hanamichi-japan', 'SNES', 'Pro Kishi Jinsei Simulation - Shougi no Hanamichi (Japan)', '1993', 'Simulation', 'Hect', '1', 'Board Game Simulation', 'Professional Shogi (Japanese Chess) life simulation.', 'Climb the ranks of the pro Shogi world and become a master.', 'Play Shougi no Hanamichi on the Super Famicom.', 'A unique 16-bit blend of strategy and RPG elements. Manage your career, practice matches, and face legendary opponents in high-stakes Shogi tournaments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-mahjong-kiwame-japan', 'SNES', 'Pro Mahjong Kiwame (Japan)', '1992', 'Board Game', 'Athena', '1', 'Mahjong', 'Professional Mahjong simulation with high-level AI.', 'Master the tiles and defeat the professional Mahjong masters.', 'Play Pro Mahjong Kiwame on the Super Famicom.', 'A 16-bit simulation designed for serious players. Features multiple rule sets, detailed statistical tracking, and a challenging tournament mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-mahjong-kiwame-ii-japan', 'SNES', 'Pro Mahjong Kiwame II (Japan)', '1993', 'Board Game', 'Athena', '1', 'Mahjong', 'Professional Mahjong simulation sequel.', 'Win the national tournament in this expanded Mahjong sim.', 'Experience Pro Mahjong Kiwame II on the Super Famicom.', 'Features improved 16-bit graphics and more sophisticated AI. Includes a variety of professional opponents and refined tutorials for mastering advanced strategies.');